window.__D("text/likkutei-sichot/c134",{"p":[[1300201350,"און די דריי מצוות וואס עליהם נשען כל בית ישראל, וואס מען האט פארטריט צו נשי ובנות ישראל: „מבצע נרות שבת קודש ויו״ט\", „מבצע כשרות האכילה ושתי׳\", און „מבצע טהרת המשפחה\"\nוואס די דריי מצוות האבן אויך א שייכות מיוחדת צו היינטיקער סדרה, ווי מפרשים זאגן<sup data-n=\"109\">109</sup> אז די דריי זאכן וואס רש״י בריינגט בפרשתנו<sup data-n=\"110\">110</sup> בנוגע שרה ורבקה — „נר דלוק מערב שבת לערב שבת\", „ברכה מצוי׳ בעיסה\", און „ענן קשור על האוהל\" — זיינען פארבונדן מיט די דריי מצות הנ״ל.\nאון ווי גערעדט אמאל בארוכה<sup data-n=\"111\">111</sup> אז דורכן קיום פון מצות הנ״ל פון יעדע אידישע טאכטער — איז מצד דעם וואס זי איז בת שרה רבקה (רחל ולאה) — טוען זיך אויף בא איר ברוחניות די דריי ענינים הנ״ל.\nלא. קען אימעצער מיינען: אמת טאקע מען דארף טאן בכל הנ״ל — אבער וואס איז די איילעניש? און כאטש טאקע מען דארף זיין מקדימים למצוות<sup data-n=\"112\">112</sup> — איז דאך אבער דער ענין הזריזות ניט נוגע צום עצם קיום המצוה, טא וואס איז אזוי דער הכרח צו טאן דאס דוקא איצטער גלייך — עס „מאכט ניט אויס\" אז מען וועט עס טאן מיט א שעה שפעטער, אדער אפילו מיט א טאג שפעטער.\nדערצו מאכט ער נאך א „חשבון\": וויבאלד אז מקיים זיין די מצוה מער בהידור וכיו״ב איז וויכטיקער פאר דעם ענין הזריזות (בנוגע לכמה ענינים)<sup data-n=\"113\">113</sup> — איז דאך „בעסער\", אז ער זאל אפלייגן די ארבעט אין הפצת התורה והיהדות אויף מארגן, ווען ער וועט ניט האבן קיין טרדות און האבן א רואיקע קאפ — וואס דאן וועט ער קענען אויפטאן בעבודתו א סאך מער.\nאיי וואס עס קען זיין אז אויך מארגן וועט ער זיין טרוד — איז מה רעש: וועט ער זיין א אונס, איז אונס רחמנא פטרי׳<sup data-n=\"114\">114</sup>.\nווען דער חיוב פון דער הפצת התורה והיהדות וואלט געווען פארבונדן דוקא מיטן זמן פון דער שעה אדער פון דעם טאג, ס׳איז מער ניט וואס שפעטער קען ער עס משלים זיין — וואלט טאקע ניט געהאלפן טענת אונס [ווי מען געפינט בא כמה מצוות, וואס זייער חיוב מצד עצמם איז בתחילת זמן מסוים, און דאס וואס מען קען עס טאן שפעטער איז עס נאר בגדר תשלומין — אז אפילו ווען ער איז געווען א אונס בזמן התשלומין פטר׳ט עס אים ניט<sup data-n=\"115\">115</sup>];\nוויבאלד אבער אז דער חיוב פון הפצת התורה והיהדות איז ניט פארבונדן מיט א זמן מסוים, במילא — טענה׳ט ער — אז דאס איז בדוגמא ווי די מצוות וואס זיינען פארבונדן מיט כללות המשך זמן מסוים (און ניט מיט תחילתו דוקא), אז אפילו ווען במשך כל הזמן האט ער ניט געוואלט מקיים זיין די מצוה, און ברגע האחרון איז ער",[["109","109","חזקוני (ריב״א), רע״ב, גו״א ועוד עה״פ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151172\" data-slug=\"likkutei-sichot\" data-id=\"1300151172\">לקו״ש חט״ו ע׳ 172־3</a>."],["110","110","כד, סז."],["111","111","וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151171\" data-slug=\"likkutei-sichot\" data-id=\"1300151171\">לקו״ש שם ע׳ 171</a>."],["112","112","פסחים ד, א. וש״נ."],["113","113","ראה שד״ח כללים מע׳ ז כלל א־ג. מע׳ פ כלל לט. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191074\" data-slug=\"likkutei-sichot\" data-id=\"1300191074\">לקו״ש חי״ט ע׳ 74</a> ובהנסמן שם."],["114","114","ב״ק כח, ב. וש״נ."],["115","115","צפע״נ לרמב״ם הל׳ נערה בתולה פ״א ה״ז. הפלאה כתובות (נד, סע״ב ואילך). ועוד."]]],[1300201351,"געווארן א אונס — איז ניטא אויף אים קיין חיוב<sup data-n=\"115\">115</sup>, דאונס רחמנא פטרי׳.\nאויף דעם קומט די צווייטע הוראה (פון די דריי ענינים שבפרשתנו) — דער גודל החשיבות פון זמן, וואס פון דעם איז פארשטאנדיק (כנ״ל סכ״ט) אז מען דארף מייקר זיין כל רגע ורגע, און ניט אפלייגן אויף שפעטער — און מצד כמה טעמים:\n(א) עס קען דאך זיין (כנ״ל) אז אין א רגע שפעטער וועט ער דאס ניט קענען טאן\n[און ווי דער רבי נשיא דורנו זאגט אין דעם מאמר פון יום ההילולא<sup data-n=\"116\">116</sup>: „דמי הוא היודע עתו וזמנו\". דאס מיינט, אז אפילו ווען ער וועט מאריך ימים זיין ביז מאה ועשרים שנה, איז אבער „מי הוא היודע\" צי אין דעם שפעטערדיקן עת וזמן וועט ער עס קענען טאן].\nוואס דאן איז אפילו אין די ענינים וואס (זיינען ניט פארבונדן מיט קיין זמן מסויים, ובמילא איז „אונס רחמנא פטרי׳\"), וועט פעלן דער ענין וואס ער האט געדארפט אויפטאן [ווארום אונס כמאן דעביד לא אמרינן<sup data-n=\"117\">117</sup>].\n(ב) וויבאלד אז אלע ענינים זיינען בהשגחה פרטית, איז פון דעם גופא וואס מען האט אים געגעבן בשעה זו די מעגליכקייטן און די געלעגנהייט צו טאן א געוויסן ענין — איז עס אן אנווייזונג מלמעלה אז ער דארף עס טאן איצטער. וכמרז״ל<sup data-n=\"118\">118</sup>: מצוה הבאה לידך אל תחמיצנה.\n(ג) וויבאלד אז א איד דארף אויפטאן אויך אין זמן, אז זיינע טעג (כולל אויך שעות<sup data-n=\"119\">119</sup> ורגעים) זאלן זיין „יומין שלימין\" — איז אפילו אויב ער וואלט געוואוסט זיכער אז די מצוה וועט ניט „נתחמץ\" ווערן און ער וועט איר קענען טאן אויך שפעטער בשלימות — וועלן דאך אבער זיינע ימים ניט זיין קיין שלימים.\nלב. נאך אן ענין אין דעם:\nוויבאלד אז ענין הנ״ל (צו אויפטאן אין וועלט) איז פארבונדן מיט עבודת עבד [ווי גערעדט פריער בארוכה בענין „יפה שיחתן של עבדי אבות\", אז די עבודה פון „שיחתן\" איז בירור עניני העולם, און דאס איז פארבונדן מיט „עבדי אבות\"] — זעט מען דאך בפועל,\nאז בשעת אן עבד האט א מעגליכקייט צו שמש זיין את אדונו, לייגט ער עס ניט אפ אויף שפעטער נאר ער טוט עס גלייך בא דער ערשטער געלעגנהייט.\nאון דאס וואס ער לייגט ניט אפ אויף שפעטער נאר ער טוט עס גלייך ובזריזות — ווייזט עס אויף דעם תענוג וואס ער האט אין דעם, תענוג האדון<sup data-n=\"120\">120</sup>,<sup data-n=\"121\">121</sup>,\nוואס דער תענוג איז מוסיף אויך אין דער עשי׳ בפועל (כנראה במוחש), און בשעת דער תענוג איז בשלימות — איז אויך די עשי׳ בשלימות.\n* * *\nלג. די הוראה כללית פון [דעם צד השוה פון די אלע דריי ענינים פון] פרשתנו — אז מען דארף אויפטאן אין די עניני העולם — איז פארבונדן אויך (כנ״ל סעיף א) מיט דעם ענין פון מוצאי",[["116","116","ד״ה באתי לגני השי״ת ס״ה."],["117","117","ירושלמי קידושין פ״ג ה״ב."],["118","118","ראה מכילתא (הובא בפרש״י) בא יב, יז."],["119","119","ראה אוה״ת בלק ריש ע׳ תתקמט."],["120","120","ראה אגה״ק סכ״א."],["121","121","ראה המשך תרס״ו ע׳ שכו."]]],[1300201352,"שבת קודש, און מיטן ענין פון [מוצאי שבת מברכים] חודש כסלו. והביאור בזה:\nדי צוויי ענינים פון תורה מיט שיחה [ועד״ז די צוויי ענינים פון „פרחה נשמתה\" און „שני חיי שרה\", און די צוויי ענינים פון „זקן\" און „בא בימים\"] ווי זיי זיינען אין דעם זמן פון שבעת ימי ההיקף — איז עס שבת און ששת ימי החול:\nשבת, וויבאלד אז דאן שטייט מען העכער פון וועלט — איז בכלל דער ענין פון תורה. כמובן אויך פון דעם וואס די גמרא זאגט<sup data-n=\"122\">122</sup> אז לכולי עלמא בשבת ניתנה תורה, און פון דעם וואס שטייט אין זהר<sup data-n=\"123\">123</sup> (ומרומז אויך אין גמרא<sup data-n=\"124\">124</sup>) אז א תלמיד חכם ווערט אנגערופן שבת;\nאון ששת ימי החול, וויבאלד אז דאן האט מען צוטאן מיט עובדין דחול, און נאך מער: אפילו די תורה ומצוות פון ימי החול דארפן אנקומען צום שבת (שלאחריהם) אז זיי זאלן נתעלה ווערן למעלה<sup data-n=\"125\">125</sup> — איז בכללות דער ענין פון „שיחה\".\nאון דאס איז די שייכות פון דער הוראה כללית הנ״ל פון פרשת ח״ש מיט מוצאי שבת קודש:\nוויבאלד אז במוצאי שבת גייט מען איבער פון בחינת תורה צו בחינת שיחה [וואס דער שינוי איז אויך בנוגע צום ענין פון זמן. ווארום שבת איז „למעלה מבחי׳ זמן\"<sup data-n=\"126\">126</sup> און במוצאי שבת הויבט זיך אן (בחי׳) זמן. ביז אז דער שינוי (בנוגע לזמן) שבמוצאי שבת איז אויך בפשטות: וואס שבת (כולל כל זמן ההיקף) ווערט אן ענין פון עבר, און מוצאי שבת, התחלת זמן והיקף חדש — אן ענין פון הוה]\nקען דאך א איד מורא האבן פון דער ירידה אין עניני העולם (בחי׳ שיחה) —\nזאגט מען אויף דעם אז ער האט ניט וואס צו מורא האבן — „אל תירא עבדי יעקב\"<sup data-n=\"127\">127</sup> — ווארום די ירידה איז צורך עלי׳, אז דוקא דורך דער ירידה אין דער „שיחה\" פון ימי החול וועט ער נתעלה ווערן נאך העכער פון ענין התורה (דשבת שלפניו), „יפה שיחתן כו׳ מתורתן כו׳\".\nלד. עד״ז (און נאך מער<sup data-n=\"128\">128</sup>) איז אויך בנוגע צו חודש כסלו: אין דעם ענין פון חנוכה [וואס דאס איז עיקר ענינו פון חודש כסלו (אזוי ווי יעדער חודש וואס עיקר ענינו איז די מועדים שבו)], גיט זיך ארויס דער גודל העילוי וואס ווערט דורך דער ירידה אין עולם:\nאין יענעם זמן (פאר דעם נס פון חנוכה) איז געווען א חושך בעולם, ביז אז אומות העולם האבן געקענט זאגן צו אידן „כתבו לכם על קרן השור וכו׳\"<sup data-n=\"129\">129</sup>.\nאבער דער חושך האט געבראכט צו א העכערן אור, צו „והוי׳ יגי׳ חשכי\"<sup data-n=\"130\">130</sup> — „והוי׳\" (בתוספת וא״ו)<sup data-n=\"131\">131</sup>,\nוכמבואר בכ״מ, אז די העלמות",[["122","122","שבת פו, ב."],["123","123","ח״ג כט, א."],["124","124","שבת קיט, א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011040\" data-slug=\"likkutei-sichot\" data-id=\"1300011040\">לקו״ש ח״א ע׳ 40</a>."],["125","125","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו״ת בהר מא, א</a>. ובכ״מ."],["126","126","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו״ת שה״ש כה, א</a>. ובכ״מ."],["127","127","לשון הכתוב — ישעי׳ מד, ב. ירמי׳ ל, י. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו״ת בלק עב, ב</a>."],["128","128","דמכיון שהירידה ד(לפני) חנוכה היא בענין החושך דעוה״ז (כדלקמן בפנים) — גם העלי׳ היא ביותר."],["129","129","ירושלמי חגיגה פ״ב ה״ב. ב״ר פ״ב, ד. וש״נ."],["130","130","ש״ב כב, כט."],["131","131","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">תו״א מא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">ש״א מג, א</a> ואילך."]]],[1300201353,"והסתרים וכו׳ האבן ארויסגערופן בא אידן דעם ענין פון מס״נ<sup data-n=\"132\">132</sup>,\nביז אז דערפון איז ארויסגעקומען דער ענין פון נרות חנוכה וואס זיינען העכער אפילו פון נרות המקדש, כמובן (אויך) פון דעם וואס דוקא נרות חנוכה (משא״כ נרות המקדש) „אינן בטלין לעולם\"<sup data-n=\"133\">133</sup>.\n* * *\nלה. אע״פ אז די הדגשה (עיקרית) אין אלע דריי כללות׳דיקע ענינים פון היינטיקער סדרה איז מעלת בירור העולם — זעט מען אבער ווי אין דעם ענין פון „שני חיי שרה\" ווערט דערמאנט (בפירוש רש״י<sup data-n=\"134\">134</sup>) אויך דער ענין פון „פרחה נשמתה\"; אזוי אויך אין צווייטן ענין, שטייט ניט בלויז „בא בימים\" נאר אויך „זקן\"; און אזוי אויך בנוגע צום דריטן ענין — פרשה של שיחת אליעזר, וואס אע״פ אז אין דער פרשה איז מודגש דער ענין פון „יפה שיחתן כו׳\", איז דאך אליעזר געווען ניט נאר „עבד אברהם\" נאר אויך „דולה ומשקה מתורת רבו\"<sup data-n=\"102\">102</sup>.\nוואס פון דעם קומט ארויס די הוראה, אז עס דארפן זיין ביידע אופני עבודה — בדוגמת ווי גערעדט פריער (סעיף כח) אז בא יעדער אידן דארף זיין סיי די עבודה פון „בן\", סיי די עבודה פון „עבד\".\nלו. די הוראה האט א שייכות מיוחדת צו שנה זו ביחוד:\nווי גערעדט פריער<sup data-n=\"135\">135</sup>, אז די קביעות פון ראש השנה פון דעם יאר [וואס ער איז דער „קאפ\" פון דעם יאר, און פירט אן מיט כל ימי השנה<sup data-n=\"136\">136</sup>]\n— סיי דער ראש השנה כפשוטו, סיי דער טאג פון י״ט כסלו וואס ער איז דער ראש השנה לתורת החסידות ולדרכי החסידות<sup data-n=\"137\">137</sup> —\nאיז ביום השלישי שהוכפל בו כי טוב<sup data-n=\"138\">138</sup>, טוב לשמים וטוב לבריות<sup data-n=\"139\">139</sup>.\nוואס די צוויי ענינים „(טוב ל)שמים\" און „(טוב ל)בריות\" — זיינען בדוגמת ווי די צוויי ענינים פון תורה און שיחה:\n„שמים\" — איז דער ענין פון „תורה\", „מן השמים השמיעך את קולו\"<sup data-n=\"140\">140</sup>; און „בריות\", וואס פי׳ אז זייער איינציקע מעלה איז נאר דאס וואס זיי זיינען „בריות\"<sup data-n=\"141\">141</sup> — איז דער ענין פון „שיחה\".\nאון אויף דעם זאגט מען אז די צוויי עבודות פון תורה און שיחה [„פרחה נשמתה\" און „שני חיי שרה\"; „זקן\" און „בא בימים\"] דארפן זיין צוזאמען — ווי גערעדט פריער<sup data-n=\"135\">135</sup>, אז דער אויפטו פון „יום שהוכפל בו כי טוב\" איז [ניט נאר אז אין אים זיינען דא סיי דער „טוב לשמים\" סיי דער „טוב לבריות\", נאר אויך] אז די ביידע טובים (וואס אין אים) זיינען פארבונדן און פאראייניקט צוזאמען.\nלז. ענין הנ״ל האט אויך א שייכות מיוחדת צו היינטיקן מוצאי שבת — און מצד צוויי ענינים:",[["132","132","וראה הקדמת שערי אורה."],["133","133","רמב״ן ר״פ בהעלותך."],["134","134","פרשתנו כג, ב."],["135","135","לעיל ע׳ 289־90."],["136","136","עס״ר בתחלתו."],["137","137","ראה „היום יום\" בסופו."],["138","138","רש״י בראשית א, ז."],["139","139","קידושין מ, א. ובאוה״ת (בראשית לג, ב. משפטים ע׳ א׳קנז. ועוד) מקשר זה עם יום השלישי שהוכפל בו כי טוב."],["140","140","ואתחנן ד, לו. וראה יתרו כ, יט: מן השמים דברתי עמכם."],["141","141","ראה תענית כ, סע״א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."]]],[1300201354,"א) אין (ראש חודש ועד״ז אין) שבת מברכים החודש זיינען כלול כל ימי החודש 141*), ובפרט די חגים ומועדים שבו. וואס דערפון איז מובן אז היינטיקער שבת האט א שייכות מיוחדת צום „חג החגים\"<sup data-n=\"142\">142</sup> י״ט כסלו וואס זיין קביעות איז (כנ״ל) ביום השלישי שהוכפל בו כי טוב.\nב) בשבת זיינען עולה ונכלל די אלע טעג פון דער פריערדיקער וואך 142*). ובמילא, האט דער היינטיקער שבת א שייכות מיוחדת צום טאג פון כ״ף חשון — דער יום הולדת פון רבי׳ן (מהורש״ב) נ״ע — וואס אויך זיין קביעות (בשנה זו) איז געווען ביום השלישי שהוכפל בו כי טוב, טוב לשמים וטוב לבריות.\nוואס ענין הנ״ל — די התאחדות פון „טוב לשמים\" מיט „טוב לבריות\" — איז מודגש אין כמה פעולות פון דעם בעל יום ההולדת, ובפרט — אין ישיבת „תומכי תמימים\" וואס ער האט מייסד געווען.\nאון ווי גערעדט כמה פעמים<sup data-n=\"143\">143</sup>, אז דער תפקיד פון „תמימים\" איז — אז צוזאמען מיט זייער אייגענער עבודה בלימוד הנגלה והחסידות ובעבודת התפלה („טוב לשמים\"), זאלן זיי זיין אויך „נרות להאיר\" — באלייכטן די וואס זיינען מחוץ להם, ביז באלייכטן אויך די „בריות\".\nלח. ענין הנ״ל איז מרומז אויך אין דעם נאמען פון רבי׳ן נ״ע [וואס דער נאמען פון א מענטשן ווייזט אויף זיין ענין<sup data-n=\"144\">144</sup>]:\nדער ערשטער נאמען פון רבי׳ן נ״ע — „שלום\" — ווייזט אויף דעם ענין וואס „התורה ניתנה לעשות שלום בעולם\"<sup data-n=\"145\">145</sup>, אויפטאן אין וועלט אז זי זאל זיין שלום (פארבונדן) מיט תורה;\nאון זיין צווייטער נאמען, וואס אין אים איז דא סיי א שם בלשון הקודש און סיי א שם בלע״ז — און פון ביידן צוזאמען ווערט איין ווארט (ווי מען זעט דאס אויך בחתימתו הקדושה) — ווייזט עס אויך, ווי פון לע״ז מיט (לשון) קודש ווערט איין זאך.\n* * *\nלט. א נתינת כח נוספת צו דורכפירן כל האמור לעיל, האט מען פון פרשת ואלה תולדות יצחק — וואס מען האט אנגעהויבן צו לייענען דעם שבת אין דעם זמן פון רעוא דרעוין;\nבשעת מען זאגט א אידן אז עס דארף זיין דער „ויעקב הלך לדרכו\", ער דארף ארויסגיין אין וועלט, און אין אזא וועלט וואס דארטן איז דא ניט נאר יעקב נאר (אויך) עשו וואס איז „יודע ציד\"<sup data-n=\"146\">146</sup> און „איש שדה\"<sup data-n=\"147\">147</sup>, און אדרבה: ס׳איז גאר „אקדימי׳ טעניתי׳\"<sup data-n=\"148\">148</sup>,",[["","","141*) ראש חודש כולל כל ימי החודש (שלכן נקרא ראש חודש ולא תחילת החודש), ושבת שלפניו — שבת מברכים — כולל בתוכו יום הר״ח בתור ראש חודש [נוסף על מה שיום השבת כולל את כל ימי השבוע שלאחריו] — כי בו „מברכים\" — [?] מלשון (ברכה ו)המשכה — את ראש החודש."],["142","142","הקדמה לחוברת י״ט כסלו. וראה לקו״ש ח״ה ע׳ 436 ואילך. 142*) ראה אוה״ת בראשית ד״ה ויכולו (מב, ב ואילך)."],["143","143","וראה גם שיחת אחש״פ תשל״ז. ושם, שנוסף לזה שצ״ל ב׳ העבודות — שיהיו „עמדו יחדיו\"."],["144","144","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061035\" data-slug=\"likkutei-sichot\" data-id=\"1300061035\">לקו״ש ח״ו ע׳ 35־36</a> ובהנסמן שם."],["145","145","רמב״ם סוף הל׳ חנוכה."],["146","146","תולדות כה, כז. וראה פרש״י שם."],["147","147","תולדות שם. וראה אוה״ת עה״פ."],["148","148","זח״א קעט, ב. *) נדפס בקונטרס בפ״ע. לקו״ש חי״ד ע׳ 314 ואילך."]]],[1300201355,"ובפרט נאך ווי זי איז בזמן הגלות, גלות אדום [„עשו הוא אדום\"<sup data-n=\"149\">149</sup>], און אין דעם גופא — אין זמן פון סיום הגלות, חושך כפול ומכופל, קען מען דאך מורא האבן —\nאיז מען מכריז ומודיע: „ואלה תולדות יצחק\" — וואס פירושו איז (ווי רש״י זאגט) „יעקב ועשו האמורים בפרשה\" (וואס פון די „יינה של תורה\" וואס אין דער פרש״י איז):\nדאס וואס ס׳איז פאראן די מציאות פון (יעקב ו)עשו איז זיין גאנצע מציאות<sup data-n=\"150\">150</sup> דאס וואס ער איז „תולדות יצחק\": אזוי ווי עס דארף זיך דורכפירן ענינו של יצחק<sup data-n=\"151\">151</sup>, צחוק עשה לי אלקים, שמחה ותענוג<sup data-n=\"152\">152</sup>, וואס די שמחה ותענוג שלמעלה (וואס דער תענוג איז דער תענוג פון די צדיקים — כולל שרה און יצחק) איז דוקא אין דער עבודה פון „אתכפיא ואתהפכא חשוכא לנהורא\"<sup data-n=\"153\">153</sup>\n[וואס דאס איז אויך דער דיוק „צחוק עשה לי אלקים\", ווייל דער צחוק ותענוג שלמעלה טוט זיך אויף („עשה לי\") דוקא דורכן בירור ההסתר פון שם אלקים 153*)].\nוואס בכדי אז דאס זאל זיך דורכפירן בפועל, דארף מען האבן אז יעקב [וואס ער (און נאר ער) איז זרעו של יצחק<sup data-n=\"154\">154</sup>] זאל זיין אין אזא אופן אז „ידו אוחזת בעקב עשו\"<sup data-n=\"155\">155</sup> — צוליב דעם איז דא עשו, און דאס איז זיין גאנצע מציאות.\nוואס דאס איז אויך וואס רש״י איז מדייק „יעקב ועשו\", פריער יעקב און דערנאך עשו — אע״פ אז דער סדר ווי זיי זיינען „אמורים בפרשה\" איז פריער עשו און דערנאך יעקב — ווייל<sup data-n=\"156\">156</sup> וויבאלד אז די גאנצע מציאות פון עשו׳ן איז צוליב יעקב׳ן (כנ״ל), קומט דאך יעקב פאר עשו<sup data-n=\"157\">157</sup>.\nמ. און דאס איז אויך מרומז בפרש״י „יעקב ועשו האמורים בפרשה\" [נוסף אויף נאך אן ענין: וואס איז (יעקב און) עשו — דאס געזאגט אין (א טייל פון דער) פרשה (תורה), זיין מציאות איז תורה:\nבכדי אז תורה זאל זיין בשלימות, דארף אין איר זיין אויך די פסוקים (און פרשה) וואס ריידן וועגן עשו׳ן [אזוי ווי די פסוקים „אנכי הוי׳ אלקיך גו׳\"<sup data-n=\"158\">158</sup> — אזוי ווי עס שטייט<sup data-n=\"159\">159</sup> בנוגע צום פסוק<sup data-n=\"160\">160</sup> „ותמנע היתה פלגש\" (וואס אויך דער פסוק איז אין דעם סיפור פון תולדות עשו) — קומט דאס אויבענגעזאגטע]]",[["149","149","וישלח לו, א. ח."],["150","150","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ״ז</a>."],["151","151","„עיקר תולדותיהם של צדיקים מע״ט\" (פרש״י נח ו, ט)."],["152","152","וירא כא, ו ובמפרשים שם."],["153","153","תניא שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו״א יז, ד</a> ואילך. 153*) תו״א שם."],["154","154","נדרים לא, א. פרש״י ויצא כח, טו. ולהעיר, דבשו״ע אדה״ז (או״ח סתקצ״א ס״ב), ד״סברא הראשונה [„דאם יאמר לזרעו תזכור יהי׳ גם עשו בכלל\"] הוא עיקר משום דבתפלת ימים נוראים יש לנו לפרש בענין שלא יהא שום ספק בקשתנו\" — ומ״מ, בסידורו (וכ״ה בפע״ח וסי׳ האריז״ל) קבע הנוסח „ועקידת יצחק לזרעו .. תזכור\" (ולא לזרעו של יעקב), שמזה משמע דזה שעשו „אינו נחשב מזרעו של יצחק כלל\" — אין שייך בזה ספק."],["155","155","תולדות כה, כו."],["156","156","הביאור בזה ע״פ פשוטו של מקרא — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051128\" data-slug=\"likkutei-sichot\" data-id=\"1300051128\">לקו״ש ח״ה ע׳ 116</a> ואילך."],["157","157","וראה רש״י תולדות שם."],["158","158","יתרו כ, ב."],["159","159","רמב״ם בסנהדרין פ׳ חלק יסוד השמיני. וראה סנהדרין צט, ב."],["160","160","וישלח לו, יב."]]],[1300201356,"בכדי עס זאל זיך דורכפירן די כוונה פון דירה בתחתונים, דער „ונגלה כבוד הוי׳ וראו כל בשר גו׳\"<sup data-n=\"161\">161</sup> וואס וועט זיין לע״ל — וואס דער ענין איז דאך פארבונדן מיט תורה [ווי ער זאגט אין תניא<sup data-n=\"162\">162</sup>: (א) אז צוליב דעם האט דער אויבערשטער געגעבן תורה אידן, בכדי זיי זאלן קענען מקבל זיין דעם „אור ה׳ הנגלה לעתיד בלי שום לבוש\". (ב) אז א „מעין\" פון דעם גילוי דלעתיד איז געווען בשעת מתן תורה] — צוליב דעם איז דא די מציאות פון עשו, בכדי עס זאל זיין „אתכפיא סט״א ואתהפכא חשוכא לנהורא\", וואס דאס וועט בריינגען דעם גילוי דלעתיד.\nמא. קען מען דאך אבער מיינען: כל הנ״ל איז ווי עשו איז מצד שרשו והכוונה, וואס די כוונה וועט נשלם ווערן ערשט לע״ל [וואס דאן וועט זיין דער „ועלו מושיעים בהר ציון לשפוט את הר עשו\"<sup data-n=\"163\">163</sup>]; אבער דערווייל איז דאך עשו מנגד וכו׳ — איז ווי קען זיין איצט דער „אל תירא עבדי יעקב\" ?\nאויף דעם זאגט מען אז עשו איז „תולדות יצחק\": אע״פ אז דער נאמען „יצחק\" איז „על שם העתיד\", ווייל דער „גילוי הצחוק והתענוג\" [וואס טוט זיך אויף דורכן (גילוי ה)העלם פון שם אלקים, ביז ווי דאס קומט ארויס אין עשו] וועט זיין ערשט לעתיד לבוא<sup data-n=\"164\">164</sup>,\nפונדעסטוועגן, איז פון דעם גופא וואס מען רופט אים אן איצטער מיטן נאמען „יצחק\" „על שם העתיד\" — און מען זעט בגלוי — און אויך ווייס דערפון און ברימט זיך דערמיט וואס ער איז „תולדות יצחק\" — איז מובן, אז אויך איצטער איז בגלוי אז מציאותו של עשו איז (די כוונה וואס עשו וועט נשלם ווערן לעתיד —) דאס וואס ער איז „תולדות יצחק\" און „אמור בפרשה\".\nאזוי איז אויך בנוגע צו דעם וואס לעתיד וועלן אידן זאגן צו יצחק׳ן „כי אתה אבינו\"<sup data-n=\"165\">165</sup> מצד דעם וואס ער וועט מציל זיין אידן פון גלות — א מעין פון דעם ענין איז שוין דא איצטער: זייענדיק נאך אין גלות, איז ער מגן אויף אידן 165*), און פון דעם קומט דערנאך ארויס — דאס וואס ער איז זיי מציל פון גלות.\nמב. און אויך דעם ענין איז רש״י מרמז אין „יעקב ועשו האמורים בפרשה\": „פרשה\" איז (אויך) פון לשון „הפרשה\".\nאע״פ אז די תורה ווי זי איז דא למטה איז זי באופן דהפרשה, דביקות בלתי ניכרת<sup data-n=\"166\">166</sup> — ובפרט פסוקים וועלכע עס רעדט זיך וועגן מעשה עשו — פונדעסטוועגן, דורך דעם וואס א איד לערנט תורה (ווי זי איז דא למטה) דעם ענין „ואלה תולדות יצחק — יעקב ועשו\", און אפילו ווי ער לערנט עס באופן פשוט — טוט ער דורך דעם אויף (כדלקמן סעיף מד) אז עס זאל זיך אנהערן אז כל מציאותו של עשו איז „תולדות יצחק\" און „אמור בפרשה\".",[["161","161","ישעי׳ מ, ה."],["162","162","פל״ו."],["163","163","עובדי׳ א, כא."],["164","164","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370085\" data-slug=\"torah-or\" data-id=\"3901370085\">תו״א יח, א</a>."],["165","165","ישעי׳ סג, טז. שבת פט, ב. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו״א כא, סע״ג</a>, וזה שאמרו לעתיד על יצחק דוקא כי אתה אבינו שייך לענין הצחוק והתענוג, שיתגלה לעתיד. 165*) להעיר מענין אמירת פ׳ העקדה בכל יום (וראה שו״ע אדה״ז אה״ח ס״א). ובחותם ברכת זכרונות: ועקדת יצחק לזרעו היום ברחמים תזכור. וראה שבת (שם) דמסיים וחותם: הא קריבית נפשי קמך."],["166","166","ראה המשך תער״ב ח״א פקע״ט."]]],[1300201357,"ועוד בזה: דא רעדט זיך וועגן עשו׳ן ווי ער שטייט אין א מצב פון הבדלה והפרשה, אז אין אים הערט זיך ניט אן זיין שרש און כוונה — און אעפ״כ איז ער „תולדות יצחק\" און „אמור בפרשה\" (אין א פרשה פון תורה), אז א איד האט בכח צו זען אויך אין עשו׳ן ווי ער איז דא למטה מופרש פון שרשו [און נאך מער: אז ער האט בכח צו פועל׳ן עס אויך אין עשו׳ן (כדלקמן סעיף מד)], אז כל מציאותו איז דאס וואס ער איז „תולדות יצחק\" און „אמור בפרשה\" (אין תורה).\nמג. נאך אן ענין אין דעם: דער לשון „האמורים בפרשה\" (מלשון הפרשה) באציט זיך דאך (ניט נאר צו „עשו\" נאר) אויך צו יעקב. וואס דערמיט איז רש״י מרמז:\nכל הנ״ל רעדט זיך וועגן א נשמה (יעקב) ווי זי איז דא למטה מלובש אין א גוף, וואס דאן איז זי אין אן אופן של הפרשה [ווי גערעדט<sup data-n=\"167\">167</sup> אז בשעת די נשמה ווערט א נברא (און עאכו״כ ווי זי קומט אראפ למטה) שטייט זי אין א דביקות בלתי ניכרת],\nאון אעפ״כ — האט זי אויך במצב זה בכח צו זען, און פועל׳ן אויך אויף עשו׳ן, אז כל מציאותו איז „אמור בפרשה\".\nמד. אזוי ווי תורה איז דאך בעה״ב אויף וועלט 167*) — איז בשעת עס קומט פרשת תולדות און אידן לייענען און לערנען די פרשה, טוען זיי אויף דורך דעם אז אויך אין וועלט, ביז אין עשו׳ן, זאל זיך הערן, אז מציאותו איז צוליב תורה און צוליב אידן.\nדאס הייסט, אז ניט נאר וואס דורך דעם „הקל קול יעקב\"<sup data-n=\"168\">168</sup> איז „אין ידי עשו שולטות\"<sup data-n=\"169\">169</sup>, נאר נאך מער: וויבאלד אז „לא ברא הקב״ה דבר אחד בעולמו לבטלה\"<sup data-n=\"170\">170</sup>, איז נאך דעם ווי מען פועל׳ט אויף די הענט פון עשו׳ן ערשטן שלב אז זיי זאלן ניט שולט זיין ח״ו (ביז אפילו אז לא יעלה על מחשבתם כלל) — וועט מען פועל׳ן אין זיי א העכערן ענין, אז זיי (די ידים) זאלן מסייע זיין אידן,\nאז נאך זייענדיק אין סיום זמן הגלות, וועלן זיי ניט נאר ניט מבלבל זיין נאר אדרבה: וועלן מסייע זיין צו יעדער אידן און צו אלע אידן — סיי צו די אידן וואס געפינען זיך אין חו״ל, ועאכו״כ צו די אידן וואס געפינען זיך אין ארץ הקודש, ארץ אשר גו׳ עיני הוי׳ אלקיך בה מראשית השנה ועד אחרית שנה<sup data-n=\"171\">171</sup> — בכל ענינים הדרושים, אז אידן זאלן קענען לערנען תורה און מקיים זיין מצוות מתוך הרחבה, און אין אן אופן פון „מלכתחילה אריבער\" 171*).\nמה. ובכדי דאס צו פועל׳ן — דארף זיין דער „אל תירא עבדי יעקב\", ניט מורא האבן און ניט נתפעל ווערן פון קיינע בלבולים, ווארום (כאמור לעיל) די גאנצע מציאות פון עשו (כולל אלע העלמות והסתרים) איז נאר בכדי אז יעקב זאל קענען דורכפירן זיין שליחות.\nוואס דערפון קומט אויך די תוצאה בנוגע צו ארצנו הקדושה, וואס מען האט גערעדט פריער<sup data-n=\"172\">172</sup> אז אידן דארפן",[["167","167","בהמאמר ס״ג. 167*) להעיר ממרז״ל עה״פ לאל גומר עלי (ירוש׳ נדרים ס״ו ה״ח. ועוד)."],["168","168","תולדות כז, כב."],["169","169","ב״ר פס״ה, כ."],["170","170","שבת עז, ב."],["171","171","עקב יא, יב. 171*) ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011124\" data-slug=\"likkutei-sichot\" data-id=\"1300011124\">לקו״ש ח״א ע׳ 124</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121194\" data-slug=\"likkutei-sichot\" data-id=\"1300121194\">חי״ב ע׳ 186</a>. ועוד."],["172","172","לעיל ע׳ 301."]]],[1300201358,"זיך באזעצן אין אלע שטחים פון ארץ ישראל, און אין דעם אופן ווי אברהם אבינו האט עס געטאן און געמאכט א „סימן לבנים\" — „ויבן שם מזבח להוי׳\"<sup data-n=\"173\">173</sup>: אז אין די אלע ערטער זאל מען בויען א מקום תורה און א מקום תפלה\n[וואס משחרב ביהמ״ק [ביז ביאת המשיח, וואס ערשט דעמולט וועט זיין דער ביהמ״ק השלישי, ניט לפני זה, ווי דער קלארער פס״ד ברמב״ם<sup data-n=\"174\">174</sup>] איז דעם) „אין לו להקב״ה בעולמו אלא ד׳ אמות של הלכה\"<sup data-n=\"175\">175</sup> — מקום תורה;\nאון עד״ז איז בנוגע צו מקום תפלה, וואס די תפלות זיינען דאך כנגד קרבנות<sup data-n=\"176\">176</sup> (מזבח)],\nאון אויך א מקוה טהרה, וואס דאס איז דאך נוגע אפילו לאנשים, און בכדי די תפלות זאלן זיין כדבעי איז נוגע אז עס זאל זיין טהרה [כתשובת הרמב״ם הידועה<sup data-n=\"177\">177</sup>, וואס אע״פ וואס ער פסק׳נט<sup data-n=\"178\">178</sup> אז טבילה איז ניט מעכב און „בטלה תקנה זו\", פונדעסטוועגן האט ער קיינמאל ניט מבטל געווען טבילת עזרא], ובפרט לויט׳ן ביאור פון אלטן רבי׳ן<sup data-n=\"179\">179</sup>,\nועאכו״כ אז דאס איז א הכרח גמור צו טהרת בנות ישראל. ובפרט אז דאס איז דאך נוגע צו „יכלו כל נשמות שב(אוצר הקרוי) גוף\" וואס דעמולט איז „בן דוד בא\" 179*).\nאון דורך דער התיישבות אין אלע שטחים פון ארץ ישראל (און באופן האמור) — וועט מען פועל׳ן (כנ״ל) אויך אויף די אומות העולם, אז זיי זאלן מסייע זיין אין דעם. ווארום אויך זיי וועלן „דערהערן\" (מצד דעם וואס „מזלייהו חזו\"<sup data-n=\"180\">180</sup>) אז די מציאות פון עשו איז צוליב העלפן יעקב׳ן.\nאון דאס וועט זיין אויך א הכנה קרובה צו דעם קיבוץ פון כל בני ובנות ישראל, שלימות העם, לארץ ישראל השלימה בביאת (און דורך) משיח צדקנו, וואס נאך דעם וועט אויך זיין דער „ירחיב ה״א את גבולך\"<sup data-n=\"181\">181</sup> — אז די ארץ ישראל השלימה וועט ווערן בהרחבה, דורך דעם וואס עס וועט נתוסף ווערן קני קניזי וקדמוני.\nמו. אזוי ווי אלע ענינים דלעתיד טוען זיך אויף דורך מעשינו ועבודתנו אין זמן הגלות<sup data-n=\"182\">182</sup> — פאדערט זיך, פון יעדן אידן, אז זיין עבודה זאל זיין (בהוספה אויף — שלימות, אויך) אין אן אופן פון „ירחיב\": נוסף אויף דעם וואס מען איז מחוייב ע״פ דין און ע״פ ציווי רבותינו נשיאינו (וואס איז שוין געווארן א גדר פון „דבר משנה\" (כפס״ד הידוע<sup data-n=\"183\">183</sup>)) — זאל ער נאך מוסיף זיין מדילי׳, לפנים משורת הדין.\nוואס דאס האט אויך א קשר מיוחד מיט חנוכה, ווארום בחנוכה איז דאך א",[["173","173","לך לך יב, ז־ח."],["174","174","הל׳ מלכים פי״א (בתחלת וסוף הפרק)."],["175","175","ברכות ח, א."],["176","176","שם כו, ב. — כן להעיר אשר בתי כנסיות הם „מקדש מעט\" (מגילה כט, א)."],["177","177","אגרת הרמב״ם לר׳ פינחס ב״ר משולם — נדפסה בשו״ת הרמב״ם ליפסיא סי׳ קמ. אגרות הרמב״ם ע׳ 178 ואילך. וראה גם רבינו יונה ברכות כב, א."],["178","178","הל׳ תפלה פ״ד ה״ד וה״ו."],["179","179","לקו״ת דברים מג, סע״ב. מאה שערים ד״ה הרנינו כו׳. 179*) יבמות סב, סע״א."],["180","180","ראה מגילה ג, א. וש״נ."],["181","181","שופטים יט, ח. ספרי הובא בפרש״י שם."],["182","182","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל״ז</a>."],["183","183","ראה הל׳ ת״ת לאדה״ז רפ״ב (ומציין לשו״ע חו״מ ר״ס כה)."]]],[1300201359,"„מנהג פשוט\"<sup data-n=\"184\">184</sup> ביי אלע אידן, אויך ביי אנשים פשוטים, צו פירן זיך ווי „מהדרין מן המהדרין\",\nוואס די הנהגה („מנהג פשוט\") פארבונדן מיט פשיטות הנשמה וואס איז דא בא יעדער אידן איז ממשיך אויך פון פשיטות העצמות, וואס דעמולט ווערן בטל אלע מדידות והגבלות,\nאז אידן שטייען נאך בסוף זמן הגלות בקומה זקופה און גרייטן זיך צו מקבל זיין פני משיח צדקנו, וואס דעמולט וועט זיין „אני מראה לכם נרות של ציון\"<sup data-n=\"185\">185</sup> — די ז׳ נרות המקדש, און אויך די שמונה נרות חנוכה ווי זיי וועלן זיין לעתיד (וואס הנרות הללו „אינן בטלין לעולם\"<sup data-n=\"133\">133</sup>),\nאויך דעם כנור של שמונה נימין<sup data-n=\"186\">186</sup>, וואס איז א הכנה אויך צום כינור של עשר נימין<sup data-n=\"187\">187</sup> [בדוגמת ווי דער כיבוש פון שבעה אומות איז א הכנה צום כיבוש פון ארץ עשר אומות],\nבביאת משיח צדקנו, בקרוב ממש.",[["184","184","רמ״א או״ח סתרע״א ס״ב."],["185","185","יל״ש ר״פ בהעלותך."],["186","186","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380167\" data-slug=\"likkutei-torah\" data-id=\"4001380167\">ערכין יג, ב</a>. וראה לקו״ת תזריע כא, ד. וראה אוה״ת חנוכה שכו, ב (ולהעיר מלקו״ת שם כב, א, שמציין לסד״ה ת״ר נר חנוכה בענין שמונה נסיכי אדם. וכן בתו״א סד״ה ת״ר נ״ח (לד, ג): „ועמ״ש ע״פ למנצח על השמינית\") שמקשר ענין ח׳ נרות חנוכה עם כנור של ח׳ נימין."],["187","187","ערכין שם."]]],[1300201360,"בס״ד. אור ליום ג׳ פ׳ ויחי, עשרה בטבת, יהפך לשמחה — בחדרו — ה׳תשל״ח. — הנחה —\nיהודה אתה יודוך אחיך וגו׳¹, ומבאר כ״ק אדמו״ר הזקן בתו״א ריש פרשתנו², שיהודה הוא על שם הפעם אודה את הוי׳³ הוא בחי׳ הודי׳ שבכללות נש״י, ובכדי שהודי׳ זו תהי׳ בהתגלות הוא ע״י אחיך, ראובן שמעון ולוי [האחים של יהודה שנולדו לפניו]. וזהו יודוך אחיך, שאחיך [ראובן שמעון ולוי] הם הגורמים ומביאים בחי׳ ההודי׳ דיהודה (שתהי׳ בהתגלות). ומבאר שם, שראובן ושמעון הו״ע ב׳ פרשיות דק״ש ולוי הו״ע אמת ויציב (שלאחרי ק״ש), ועי״ז באים אח״כ לשמו״ע, בחי׳ ההודי׳ והביטול דבחי׳ יהודה.\nב) והענין הוא (כמבואר בתו״א שם), דהנה ראובן הוא על שם כי ראה גו׳⁴, ושמעון על שם כי שמע גו׳⁵. וענינם בעבודת ה׳ (בכאו״א מישראל), בחי׳ ראובן הוא שעבודתו לקונו היא לא בבחי׳ השגה לבד כ״א בבחי׳ ראי׳. והיינו שההתאמתות שלו באלקות היא בוודאות הכי גדולה, בדוגמת אדם שרואה איזה דבר שאין שייך שיהי׳ אצלו שום ספק בזה, מכיון שהוא עצמו ראה את הדבר⁶, ועד״ז הוא בעבודת ה׳, שההתבוננות שלו [ובפרט בהענין דהשגחה פרטית⁷] היא באופן (דהסתכלות⁸) שהענין מתאמת אצלו כאילו הוא רואה בראי׳ חושית ממש. ומראי׳ זו הוא בא לבחי׳ אהבת הוי׳, וכמ״ש⁴ (גבי קריאת שם ראובן) כי ראה גו׳ כי עתה יאהבני. והו״ע פרשה ראשונה דק״ש, ואהבת את הוי׳ אלקיך גו׳⁹.",[["1","1","ויחי מט, ח."],["2","2","ד״ה זה (מה, א ואילך). וראה הגהות וביאורי הצ״צ באוה״ת (שסא, ב ואילך. תתקצו, א ואילך. תתשלח, ב ואילך). ד״ה זה תרפ״ח."],["3","3","ויצא כט, לה."],["4","4","שם כט, לב."],["5","5","שם כט, לג."],["6","6","ראה אוה״ת וירא קד, א. ד״ה פדה בשלום תש״ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061132\" data-slug=\"likkutei-sichot\" data-id=\"1300061132\">לקו״ש ח״ו ע׳ 121</a>. וראה גם ד״ה וכל מאמינים תרס״ג. כי חלק תש״ט. ולהעיר ג״כ מאגה״ק סי״ט."],["7","7","מכיון שענין זה רואים במוחש (ראה סה״ש תש״ג ע׳ 119 החילוק שבין ההתבוננות בענין יש מאין להתבוננות בהשגחה פרטית)."],["8","8","ראה בארוכה ד״ה יהודה אתה תרפ״ח. וראה גם תו״א (מה, א), שענין ראובן הוא „לאסתכלא ביקרא דמלכא״."],["9","9","ואתחנן ו, ה."]]],[1300201361,"ובחי׳ שמעון (על שם כי שמע גו׳) הוא שהעבודה שלו היא בבחי׳ שמיעה והשגה לבד ולא בבחי׳ ראי׳. ומכיון שאז הוא עדיין בבחי׳ ריחוק [בדוגמת אדם השומע איזה דבר שמספרים לו, אבל הוא עצמו לא ראה], לכן אצלו העבודה בקו היראה. והו״ע פרשה שני׳ דק״ש, והי׳ אם שמוע תשמעו גו׳ השמרו לכם פן יפתה גו׳¹⁰. דמכיון שענין האלקות אצלו הוא רק בבחי׳ שמיעה (אם שמוע תשמעו), לכן צריכה להיות עבודתו בקו היראה (השמרו לכם גו׳).\nובחי׳ לוי על שם ילוה אישי אלי¹¹ הוא מה שאחר ק״ש אומרים אמת ויציב וכו׳ הדבר הזה עלינו, הדבר הזה קאי על התורה, כי ע״י התורה נעשה ילוה אישי אלי (כדלקמן).\nג) ובביאור הענין, הנה ג׳ בחינות הנ״ל (ראובן שמעון ולוי) הם ג׳ הקוין שעליהם העולם עומד¹² [גם העולם קטן זה האדם¹³, אתם קרויין אדם¹⁴] תורה עבודה וגמ״ח. בחי׳ ראובן (אהבה) הוא קו הגמ״ח. כי כאשר יש לו אהבת הוי׳ יש לו גם אהבת ישראל [שהרי אהבת הוי׳ ואהבת ישראל הם כולא חד¹⁵], ולכן, עבודתו היא בקו הגמ״ח, כי אהבה היא¹⁶ סיבת החסד ופנימיותה, המשכה מלמעלמ״ט. ובחי׳ שמעון (יראה) הוא קו העבודה, ענין התפלה, קו השמאל [ובתפלה גופא הו״ע פרשה שני׳ דק״ש, כנ״ל], העלאה מלמטלמ״ע. ובחי׳ לוי על שם ילוה אישי אלי הוא קו התורה, כי ע״י אורייתא ישראל וקוב״ה כולא חד¹⁷. וזהו״ע ילוה אישי אלי, כי ע״י התורה נעשה חיבור עם אישי זה הקב״ה, עד שישראל וקוב״ה כולא חד. וזהו מה שבחי׳ לוי הו״ע אמת ויציב כו׳ הדבר הזה שקאי (כנ״ל) על התורה.\nד) וזהו יהודה אתה יודוך אחיך, שהעבודה דבחי׳ (אחיך) ראובן שמעון ולוי, ב׳ פרשיות דק״ש ואמת ויציב, היא הקדמה והכנה לבחי׳ יהודה, העבודה דשמו״ע, הודי׳ וביטול, כעבדא קמי׳ מרי׳¹⁸. שהביטול דתפלת",[["10","10","עקב יא, יג. שם טז."],["11","11","ויצא כט, לד."],["12","12","אבות פ״א מ״ב."],["13","13","תנחומא פקודי ג. ובכ״מ."],["14","14","יבמות סא, רע״א."],["15","15","סה״ש קיץ ה׳ש״ת ע׳ 3. ועוד."],["16","16","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380846\" data-slug=\"likkutei-torah\" data-id=\"4001380846\">אגה״ק סט״ו (קכג, א</a>). דרמ״צ יב, ב. צז, סע״א ואילך. וראה גם לקו״ת ראה לב, ד."],["17","17","ראה זח״ג עג, א."],["18","18","שבת י, א."]]],[1300201362,"העמידה הוא ביטול בתכלית למעלה גם מהביטול דק״ש. וכמובן גם מחילוקי הדינים (בענין הפסק וכו׳) בין ק״ש לשמו״ע¹⁹. וענין זה [מה שע״י העבודה דבחי׳ ראובן שמעון ולוי מגיעים אח״כ לבחי׳ יהודה (בן הרביעי)] הוא ע״ד הידוע²⁰ בענין ג׳ הכתרים [כתר תורה כתר כהונה וכתר מלכות, שהם בג׳ הקוין תורה עבודה וגמ״ח²¹] וכתר שם טוב שעולה על גביהן²² [שהוא למעלה מהם], שבכדי להגיע לבחי׳ כתר שם טוב הוא ע״י ג׳ הכתרים, עולה על גביהן.\nה) והנה זה שבחי׳ יהודה צריך להקדמת העבודה דבחי׳ ראובן שמעון ולוי, היינו בכדי שההודי׳ דבחי׳ יהודה תהי׳ בגילוי. אבל בהעלם ובפנימיות הרי ההודי׳ זו היא בתמידות. וכמבואר בתו״א²³ שהיו״ד דיהודה מורה על ההוה והתמידות כמו ככה יעשה איוב כל הימים²⁴, דהיינו שההודי׳ שבכאו״א מישראל היא בתמידות. דמ״ש³ הפעם אודה את הוי׳ (שלא כל העתים שוות) הוא רק בנוגע להגילוי, מצד העלם והסתר הגוף ונה״ב (ובפרט מצד העלם והסתר הגלות), אבל נפש האלקית שבכאו״א מישראל [שהיא מהותו האמיתי] היא תמיד באמנה אתו²⁵ ואודה את הוי׳ הוא אצלו בתמידות, ואין שייך בזה שום שינוי ח״ו. והקדמת העבודה דבחי׳ ראובן ושמעון ולוי הוא בכדי לעורר²⁶ את ההודי׳ שבפנימיות הלב שתהי׳ בגילוי, ועד שתצא פעולתה מהכח אל הפועל ממש במחשבה דיבור ומעשה.\nו) וממשיך בכתוב ידך בעורף אויבך, שע״י גילוי ההודי׳ דבחי׳ יהודה נעשה ידך בעורף אויבך ברוחניות (כמבואר הענין בתו״א²⁷) וגם בגשמיות, דאין מקרא יוצא מידי פשוטו²⁸. ולאחרי ידך בעורף אויבך נאמר גור ארי׳ יהודה גו׳ לא יסור שבט מיהודה גו׳²⁹, וי״ל בדא״פ שבזה מרומז",[["19","19","ראה שו״ע אדה״ז סס״ו ס״ב (בנוגע לק״ש) וסי׳ קד (בנוגע לתפלה). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161018\" data-slug=\"likkutei-sichot\" data-id=\"1300161018\">לקו״ש חט״ז ע׳ 18</a> הערה 58."],["20","20","ראה בארוכה לקו״ש ח״ד ע׳ 1214 ואילך."],["21","21","המשך תער״ב בתחלתו."],["22","22","אבות פ״ד מי״ג."],["23","23","בתחילת הדרוש."],["24","24","איוב א, ה. וראה שעהיוה״א רפ״ד."],["25","25","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ״ד</a>."],["26","26","וע״ד המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ״ב (ס, א</a>)."],["27","27","מה, ג."],["28","28","שבת סג, א. וש״נ."],["29","29","ויחי מט, ט־יו״ד."]]],[1300201363,"שידך בעורף אויבך הוא עוד לפני הגאולה³⁰. דהנה גור ארי׳ גו׳ לא יסור שבט מיהודה קאי על דוד ושלמה, שמזרעם יהי׳ מלך המשיח³¹ שעליו נאמר וקם שבט מישראל³² [שאז יהי׳ ועבדי דוד מלך עליהם³³, ודוד עבדי נשיא להם לעולם³⁴, כמ״ש בההפטורה דשבת העבר, שמיני׳ מתברכין כולהו יומין³⁵]. ולפני זה, בסיום זמן הגלות³⁶, יהי׳ ידך בעורף אויבך, שכל אויבי ישראל [שכל ישראל נקראים על שם יהודה³⁷] תפול עליהם אימתה ופחד³⁸, ע״י גילוי ההודי׳ שבכללות נש״י, ועד שבאה בפועל במחשבה דיבור ומעשה, בחוקותי תלכו ואת מצוותי תשמרו גו׳³⁹, הנה עי״ז יהי׳ (כהמשך הכתובים בפ׳ בחוקותי⁴⁰) ונפלו אויביכם לפניכם וגו׳.\nז) וי״ל דזהו גם קשר דיהודה אתה יודוך אחיך ידך בעורף אויבך לויחי יעקב בארץ מצרים, שגם כשישראל נמצאים בגלות (שכל הגלויות, המלכיות⁴¹ נקראת ע״ש) מצרים הם בבחי׳ ויחי ע״י לימוד התורה תורת חיים וקיום מצוותי׳ עליהם נאמר⁴² וחי בהם [וכפירוש כ״ק אדמו״ר הזקן שאמר לנכדו כ״ק אדמו״ר הצ״צ עה״פ ויחי יעקב בארץ מצרים, שע״י שאת יהודה שלח לפניו גו׳ להורות לפניו גשנה להתקין לו בית תלמוד כו׳⁴³ הי׳ בחי׳ „ויחי״ גם במצרים⁴⁴], ועי״ז נעשה⁴⁵ (יהודה אתה יודוך אחיך) ידך בעורף",[["30","30","להעיר שגם בגלות מצרים (שכימי צאתך מארמ״צ אראנו נפלאות — בגאולתנו עתה) קדם ליצי״מ: ונתתי את חן העם הזה בעיני מצרים גו׳ (שמות ג, כא ובמרז״ל שם)."],["31","31","בפיה״מ להרמב״ם פ׳ חלק יסוד הי״ב „מזרע שלמה דוקא״. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081225\" data-slug=\"likkutei-sichot\" data-id=\"1300081225\">לקו״ש ח״ח ע׳ 215</a> הערה 53. וש״נ."],["32","32","בלק כד, יז. רמב״ם הל׳ מלכים פי״א ה״א."],["33","33","יחזקאל לז, כד."],["34","34","שם, כה."],["35","35","ראה זח״ב סג, ב. פח, א."],["36","36","להעיר מרמב״ם הל׳ מלכים ספי״א דגם לאחרי ביאת המשיח הסדר הוא: וילחום מלחמות ה׳ וינצח, ואח״כ ובנה מקדש במקומו כו׳ וקבץ נדחי ישראל כו׳."],["37","37","ב״ר פצ״ח, ו (עה״פ יהודה אתה יודוך אחיך). וראה אוה״ת ויחי שסד, א."],["38","38","בשלח טו, טז."],["39","39","ר״פ בחוקותי."],["40","40","כו, ח."],["41","41","ב״ר פט״ז, ה."],["42","42","אחרי יח, ה."],["43","43","ויגש מו, כח. תנחומא שם (פרש״י שם)."],["44","44","היום יום ע׳ יב."],["45","45","וי״ל דזה מרומז גם בזה שהתחלת הסדרה בתו״א היא בפסוק זה."]]],[1300201364,"אויבך, וכמרז״ל⁴⁶ כשהקול קול יעקב בבתי כנסיות ובתי מדרשות אין ידי עשו שולטות, ויתירה מזו, שאוה״ע עצמם מסייעים לישראל בכל הענינים הגשמיים שיוכלו ללמוד תורה ולקיים מצוות מתוך הרחבה, ובאופן דמוסיף והולך מוסיף ואור. ואור זה דוחה את חושך הגלות ומביא את הגאולה ע״י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.",[["46","46","ב״ר פס״ה, כ."]]],[1300201365,"משיחות אור ליום ג׳ פ׳ ויחי, עשרה בטבת, יהפך לשמחה — בחדרו — ה׳תשל״ח\nא. דער ענין פון א תענית איז, ווי דער רמב״ם¹ זאגט „מדרכי התשובה הוא״ — וואס אזוי איז אויך בנוגע צו די ד׳ צומות, און זיי זיינען „כדי לעורר הלבבות לפתוח דרכי התשובה״².\nדערפאר איז געווען א מנהג³ בכמה קהלות אז ביום התענית [בזמן⁴ תפלת מנחה⁵] פלעגט מען זאגן דברי כבושין⁶, אויף מעורר זיין צו תשובה.\nמצד סיבות שונות איז דער מנהג געבליבן, ליידער, נאר אין געציילטע ערטער⁷.\nא לימוד זכות אויף דעם (וואס ברוב המקומות טוט מען עס ניט), וואורום מ׳דארף ניט האבן קיין גרעסערע „דברי כבושין״ ווי די הפטורה וואס מען זאגט אין א תענית צבור צו מנחה,\nאון ס׳איז דאך⁸ א יום מלאכה ואין להטריח⁸*,\nזעט מען דאך אבער במוחש, אז די התעוררות פון (זאגן אדער) הערן א נוסח קבוע (דההפטרה) ובלשון הקודש וכו׳ איז ניט בדומה צו דער התעוררות פון די דברי כבושין וואס זיינען ניט בנוסח קבוע, זיינען בשפה המדוברת וכו׳.\nובפרט אז אין די דברי כבושין וואס מען פלעגט זאגן בתענית צבור, פלעגט מען ריידן בפירוש (אויך) וועגן ענינים העומדים על הפרק.\nב. און דאס איז אויך איינע פון די מטרות פון דעם איצטיקן ריידן:\nאזוי ווי ס׳איז געבליבן עטליכע שעות ביז צו דער התחלה פון „צום העשירי״ [וואס הויבט זיך אן ערשט אינדערפרי]\n— איז כדאי צו מעורר זיין אויף דעם מנהג הנ״ל, אז אין די ערטער וואו מען קען עס אויספירן, זאל מען זאגן נאך מנחה (א פאר ווערטער, לכה״פ) „דברי כבושין״, אדער א מזמור תהלים המתאים לענינים אלו,\nאון אין די ערטער וואס מצד טירחא דצבורא [אדער מצד ביטול מלאכה⁹, וכיו״ב] קען מען עס ניט אויספירן — זאל מען טראכטן עכ״פ במחשבה אן ענין פון „דברי כבושין״,\nאון וויבאלד אז „רחמנא לבא בעי״⁹* — ובפרט אין ענינים וואס זיינען פארבונדן מיט תשובה, וואס „עיקר",[["1","1","הלכות תעניות פ״א ה״ב."],["2","2","שם רפ״ה."],["3","3","ראה זכרונות כ״ק מו״ח אדמו״ר (ספר הזכרונות ח״א ע׳ 233. 268. „התמים״ ח״ד ע׳ לו [קפג, ב])."],["4","4","ראה ערוך השולחן או״ח (סתקע״ט ס״ג): „וכן בכל תענית או בעת צרה כשאומרים דברי מוסר יאמרו קודם תפלת מנחה״ (וכנראה שהוא ע״פ המשנה שבהערה 6)."],["5","5","אבל לא בשחרית — משום ביטול מלאכה. בדוגמת ההפטרה [„דרשו״, שהיא „מדרכי התשובה״], שאין מפטירין אותה בשחרית „משום ביטול מלאכה לעם״ (לבוש או״ח סתקס״ו ס״ב)."],["6","6","ראה תענית רפ״ב. שו״ע או״ח סו״ס תקע״ו (סתקע״ט ס״א)."],["7","7","וכבר תמה בכיו״ב במג״א שם (סו״ס תקע״ו). וראה נו״כ השו״ע שם."],["8","8","ע״פ הנ״ל בהערה 5. 8*) משא״כ בדורות הקודמים שלתפלת מנחה (בימי צום) כבר גמרו מלאכתן."],["9","9","ובפרט במדינות אלו, שהימים דתקופת טבת הם קצרים. 9*) הובא בכ״מ — והוא ע״פ (גירסת רש״י ב)סנהדרין קו, ב."]]],[1300201366,"התשובה בלב״¹⁰ — איז „מחשבה טובה הקב״ה מצרפה למעשה״¹⁰*.\nג. ואע״פ אז דער אלטער רבי איז מבאר אין תניא¹¹, אז פון דעם לשון „מצרפה למעשה״ (און ניט „כאילו עשאה״) איז מוכח אז מען דארף האבן א מעשה צו וועלכער מ׳איז מצרף די מחשבה [און דער אויפטו פון „מחשבה טובה הקב״ה מצרפה למעשה״ איז אז די מחשבה און די מעשה זאלן ניט זיין באזונדער, נאר אז די מחשבה זאל נצטרף ווערן און נתחבר ווערן צו דער מעשה, וואס דאן ווערט עס א דבר שלם],\nאיז דאך ידוע¹² דער פירוש אין „השלך על ה׳ יהבך והוא יכלכלך״¹²*, אז בשעת דער בטחון אין דעם אויבערשטן איז ווי עס דארף צו זיין, ביז אז דאס איז אין אן אופן פון „השלך על ה׳ יהבך״, איז דעמאלט „והוא יכלכלך״, אז דער אויבערשטער שטעלט צו אויך די כלים אין וועלכע עס זאל אראפ־קומען ברכתו של הקב״ה בטוב הנראה והנגלה,\nוואס דערפון איז מובן אויך בנוגע צו ענינים וואס זיינען פארבונדן מיט רוחניות [וי״ל דאדרבה, בענינים רוחניים איז דאס נאך ביתר שאת וביתר עוז], אז בשעת דער אויבערשטער זעט [וואס „ה׳ יראה ללבב״¹³] אז די מחשבה טובה [שבלב] איז בתוקף ובאמת — איז „והוא יכלכלך״, אז דער אויבערשטער איז מזמין כמה ענינים וסיבות אז ער זאל טאן אויך א מעשה¹⁴ [און אז דאס זאל אנקומען בקל — עכ״פ בערך עבודתו לפנ״ז ולאח״ז],\nובנוגע לענינינו: אז דער אוי־בערשטער וועט צושטעלן די „כלים״ אז מען זאל טאן מעש״ט בפועל, והקב״ה מצרפן.\nד. און אין דער תשובה — ביז צו תשובה מאהבה וואס טוט אויף ניט נאר אז די עונות ווערן בטל [„נעקר עונו מתחלתו״¹⁵], נאר נאך מער: אז די זדונות ווערן נהפך צו זכיות¹⁶,\nוואס דאס וועט אויך ברענגען¹⁷ דעם קיום היעוד אז „כל הצומות האלו עתידים ליבטל״¹⁸, און נאך מער „ולא עוד אלא שהם עתידים להיות ימים טובים¹⁹ וימי ששון ושמחה״¹⁸, ביז אז (ניט נאר די ימי הצומות, נאר) אויך דער",[["10","10","<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ״ט (לו, ב</a>). 10*) קידושין מ, א."],["11","11","ספט״ז."],["12","12","ראה סד״ה ולא זכר תרפ״ח. 12*) תהלים נה, כג. ולהעיר, שפסוק זה הוא בשיעור תהלים (החדשי) דעשירי בטבת."],["13","13","ש״א טז, ז."],["14","14","ראה ד״ה בטח בה׳ תש״ב ע׳ 87: „והפירוש האמיתי דמצרפה למעשה הוא דכאשר איש ישראל חושב לעשות איזה דבר בלימוד התורה בקיום המצוות .. הקב״ה מצרף כמה ענינים בהשגחה פרטית שיבוא לידי מעשה״."],["15","15","פרש״י ד״ה כאן מאהבה — יומא פו, א."],["16","16","שם פו, ב. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171185\" data-slug=\"likkutei-sichot\" data-id=\"1300171185\">לקו״ש חי״ז ע׳ 185</a> ואילך, שענין זה דזדונות נעשים כזכיות הוא אופן נעלה יותר בתשובה מאהבה גופא מהתשובה מאהבה שעל ידה נעקר עונו מתחלתו."],["17","17","ועפ״ז יומתק מ״ש הרמב״ם (סוף הל׳ תעניות): „כל הצומות האלו עתידים ליבטל כו׳״ — אף שספר היד הוא (רק) „הלכות״ (כמ״ש הרמב״ם בהקדמתו) — כי זה נוגע להתענית שהוא „כדי .. לפתוח דרכי התשובה״ שתהי׳ עד כדי שיהפכו הצומות ע״י שיהפכו הזדונות כו׳ (כמבואר בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151428\" data-slug=\"likkutei-sichot\" data-id=\"1300151428\">לקו״ש חט״ו ע׳ 415-6</a> ובהערות שם). ועוד: מכיון „שכל דברי תורה מצווין אנו לעשותן עד עולם״ (רמב״ם הל׳ יסוה״ת רפ״ט) — לכן הוזקק לומר ש„הצומות האלו (דינם מלכתחילה ש)עתידים ליבטל לימות המשיח״."],["18","18","רמב״ם סוף הלכות תעניות."],["19","19","כ״ה הגירסא בכמה דפוסים. וראה לקמן ע׳ 528 הערה 30."]]],[1300201367,"ענין הצום גופא וועט נהפך ווערן לטוב, לששון ולשמחה²⁰.\nה. די התעוררות אויף תשובה אין די ד׳ צומות איז דאך פארבונדן מיט „זכרון דברים אלו״²¹ וואס האבן פאסירט בפעם הראשונה,\nאיז דער מאורע וואס האט געטראפן בעשירי בטבת (וואס דערפאר האט מען מתקן געווען דעם „צום העשירי״) איז — „שבו²² סמך מלך בבל נבוכדנאצר הרשע על ירושלים והביאה במצור ובמצוק״, כמסופר בכמה מקומות בתנ״ך²³\n[ובפרט אין יחזקאל²⁴, וואס דארטן שטייט ניט נאר דער סיפור המאורע [אז בעשירי בטבת „סמך מלך בבל אל ירושלים״] נאר אויך אז דער אוי־בערשטער האט געהייסן פארשרייבן דאס — „כתב לך את שם היום את עצם היום הזה״²⁵ (און דורך דעם איז בא־וואוסט געווארן אז ער איז א נביא אמת²⁶, ובמילא איז דאס אויך מאמת נבואות הגאולה פון יחזקאל)].\nאון אע״פ אז אויך נאך דעם וואס „סמך מלך בבל אל ירושלים בעצם היום הזה״²⁷ איז געבליבן ירושלים גאנץ, און עאכו״כ אז דער ביהמ״ק איז געווען בשלימות, ביז אז ס׳איז ניט געווען אפילו קיין גרעון אין די קרבנות — פונדעסטוועגן איז דא א חומר אין עשרה בטבת אויף שבעה עשר בתמוז וואס אין דעם טאג איז „בטל התמיד והובקעה העיר״²⁸, און אפילו אויף תשעה באב וואס אין אים איז „חרב הבית״ (ועל אחת כו״כ אויף צום גדלי׳).\nווי דער דין איז (לפי דיעה²⁹ אחת³⁰), אז „י׳ בטבת הוא משונה משאר תעניות, שאם הי׳ חל בשבת לא היו יכולין לדחותו ליום אחר״.\nוא״ו. דעם טעם אויף דעם בפשטות י״ל³¹: דער „ותבוא העיר במצור״³² וואס איז געווען בעשרה בטבת איז געווען די התחלה וואס האט סוף סוף דערפירט צום „ותבקע העיר״³³ (וואס איז געווען בשבעה עשר בתמוז), ביז צום „וישרוף את בית ה׳״³⁴ (וואס איז געווען בתשעה באב).\nאון וויבאלד אז דער ענין פון די ד׳ צומות איז „כדי לעורר הלבבות לפתוח דרכי התשובה״ — דעריבער איז דא א (חומר און א) תוקף מיוחד אין דעם צום",[["20","20","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151429\" data-slug=\"likkutei-sichot\" data-id=\"1300151429\">לקו״ש שם ס״י (ע׳ 416-7</a>)."],["21","21","רמב״ם שם רפ״ה."],["22","22","רמב״ם שם פ״ה ה״ב."],["23","23","מ״ב כה, א־ב. ירמי׳ נב, ד־ה."],["24","24","כד, ב."],["25","25","ובפרט לדעת האבודרהם (הובאה לקמן בפנים) שמלשון את עצם גו׳ ילפינן דיש לצום זה תוקף דיוהכ״פ (שדוחה שבת)."],["26","26","רד״ק ומצודת דוד יחזקאל שם."],["27","27","יחזקאל כד, ב."],["28","28","תענית כו, ריש ע״ב במשנה."],["29","29","אבודרהם הל׳ תעניות — הובא בב״י לטאו״ח סתק״נ. ואף שכותב ע״ז (הב״י) ולא ידעתי מניין לו זה — אינו דוחה דעתו בפירוש. ואף שפרש״י (ד״ה אבל — מגילה ה, א — הביאו בב״י שם לפנ״ז) שנדחה הצום מפני השבת, הרי רש״י בפירושו (משא״כ בשו״ת שלו, כפשוט) פרשן ולא פוסק (יד מלאכי כללי רש״י ס״ב) וכשנמצא פוסק חולק (על פרש״י) אזלינן כוותי׳, והאבודרהם פוסק הוא. ובכל אופן צ״ע, דהרי ברור כתב הרמב״ם (הל׳ תעניות פ״ה ה״ה) — הובא בב״י שם: אחד מארבעה ימי הצומות שחל להיות בשבת דוחין אותו לאחר השבת (ואפי״ל דארבעה לאו דוקא — באם דין אחד מהם הוא היפך ממש״כ בטור פס״ד)."],["30","30","משא״כ בשאר הצומות (לבד יוהכ״פ) — לכ״ע אין מתענין בשבת."],["31","31","ראה עד״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151433\" data-slug=\"likkutei-sichot\" data-id=\"1300151433\">לקו״ש שם סט״ז (ע׳ 420-1</a>)."],["32","32","מ״ב כה, ב. ירמי׳ נב, ה."],["33","33","מלכים שם, ד. ירמי׳ שם, ז."],["34","34","מלכים שם, ט. ירמי׳ שם, יג. וראה תענית כט, א."]]],[1300201368,"פון עשרה בטבת, ווייל דאן (ווען „סמך מלך בבל אל ירושלים בעצם היום הזה״²⁷) איז געווען די ווארענונג מל־מעלה אז איב מען וועט ניט תשובה טאן, וועט פון דער התחלה קומען א המשך כו׳.\nז. דער „זכרון דברים אלו״ איז דאך בכדי אז „נשוב להיטיב״²¹ — איז פון די ענינים וואס מען דארף אפלערנען פון עשרה בטבת [ובפרט בזמנינו זה, וואס דער בלבול המוחות איז אויף אזוי פיל ביז אז „שמים חושך לאור ומר למתוק״³⁵]:\nירושלים איז ירא שלם³⁶, ד.ה. די שלימות פון יראת שמים³⁷. איז בשעת מען זעט א מצור אויף יראת שמים, איז אפילו ווען דער מצור איז ניט אויף ענינים חמורים נאר אויף א דקדוק קל של דברי סופרים, אדער אפילו מערניט ווי אויף אן ענין וואס עס האט מחדש געווען א תלמיד ותיק בדורות האחרונים (וואס אויך דאס איז ניתן למשה מסיני³⁸)\n[ובדוגמת ווי ס׳איז געווען דאן, אז דעם ביהמ״ק מיט די קרבנות האט מען ניט געטשעפעט, מען האט געמאכט א מצור מבחוץ³⁹ — און נאר אויף ירושלים],\nדארף מען טאן כל מיני השתדלות צו מבטל זיין דעם מצור, וואורום דאס (דער מצור אויף קלה שבקלות) איז א התחלה וואס קען ברענגען צו ווייטערדיקע תוצאות רחמ״ל, ווי די גמרא זאגט⁴⁰ „היום אומר לו כך כו׳ עד שאומר לו לך ועבוד כו׳״.\nח. ווי קען דער יצה״ר איינרייידן א אידן צו עובר זיין אפילו אויף אן ענין וואס איז נתחדש געווארן דורך א תלמיד ותיק — בשעת אז דער איד הערט אז „כל מה שתלמיד ותיק עתיד לחדש ניתן למשה מסיני״?\nאיז דער דרך אין דעם, אז דער יצה״ר רעדט אין דעם אידן, אז דורך דעם וואס ער וועט פארבייגן אויף דעם חידוש פון דעם תלמיד ותיק, וועט ער „פארדינען״ א גרעסערע מצוה (אדער עטליכע מצוות).\nאון דער יצה״ר איז נאך „מסביר״, אז תורה אליין זאגט אז מען קען מדחה זיין איין ענין צוליב א צווייטן, אזוי ווי עשה דוחה לא תעשה: פקוח נפש דוחה שבת, וכיו״ב.\nדער אמת איז אבער, אז מיט דער דאזיקער טענה (צו פארבייגן אן ענין קל צוליב אן ענין חמור) איז דער יצה״ר אויסן (ניט צו פארהיטן דעם ענין חמור, נאר) צו מכשיל זיין דעם אידן אין אן ענין קל, און דורך דעם⁴¹ — (דערנאך) אויך אין אן ענין חמור, ווי געבראכט פריער וואס די גמרא זאגט „היום אומר לו כך כו׳ עד שאומר כו׳״.\nומובן בפשטות, אז דאס האט קיין שייכות ניט צו דעם וואס עשה דוחה לא תעשה וכיו״ב — וואורום דאס (וואס עשה דוחה ל״ת) איז א דין אין עשה ול״ת גופא וואס תורה זאגט: בשעת אבער עס קומט א בשר ודם און וויל",[["35","35","ישעי׳ ה, כ."],["36","36","תוד״ה הר — תענית טז, א."],["37","37","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">לקו״ת ר״ה ס, ב</a>."],["38","38","נסמן בלקו״ש ח״ד ע׳ 1088 הערה 11."],["39","39","שענין המצור — בפשטות הוא: להפסיק תוספת חיזוק דהעיר (ע״י שיביאו לתוכה ענייני אכר״ש וכו׳), למנוע יציאה מן (והשפעה של) העיר מחוצה לה וכו׳."],["40","40","שבת קה, ב."],["41","41","וכדבר משנה: עבירה גוררת עבירה (אבות פ״ד מ״ב)."]]],[1300201369,"מאכן „מסחר״ אין מצוות און עבירות, „פארקויפן״ א קליינע מצוה ד.ה. אריינ־באקומען אן עבירה, בכדי צו „פאר־דינען״ א גרויסע מצוה — ברייננגט עס דערצו, אז סוף סוף פארקויפט מען ניט נאר „קלה שבקלות״ נאר, ר״ל, אויך „חמורה שבחמורות״, כנ״ל.\nט. עפ״ז זיינען גדולי ישראל שבדו־רות שלפנינו אויך מסביר וואס עס שטייט אויף דעם אויבערשטן „לא יקח שוחד״⁴². דלכאורה תמוה: ס׳איז דאך „לה׳ הארץ ומלואה״⁴³, טא ווי איז שייך מען זאל געבן עפעס דעם אויבערשטן (ובנדו״ד — שוחד און מען דארף בא־וואורענען אז „לא יקח שוחד״)?\nאיז דער ביאור אין דעם: די איינציקע זאך וואס מ׳גיט, כביכול, דעם אוי־בערשטן (און במילא קען מען מיינען אז דערמיט איז מען אים משחד) איז — ענינים וואס זיינען פארבונדן מיט יראת שמים, וואורום „הכל בידי שמים חוץ מיראת שמים״⁴⁴.\nאון אויף דעם זאגט דער פסוק „לא יקח שוחד״: אז מען זאל זיך ניט איינרייידן אז מען קען משחד זיין דעם אויבערשטן.\nי׳ד. די הוראה איז נוגע במיוחד בענין החינוך:\nס׳זיינען דא אזוינע וואס מיינען אז בכדי צו פועל׳ן אויף די עלטערן און זיי זאלן וועלן געבן זייערע קינדער אין כשר׳ע מוסדות [אדער בכדי צו פועל׳ן אויף די קינדער גופא וואס געפינען זיך דערוויילע בחוץ] דארף מען מאכן פאר־שידענע „קולות״ און „פשרות״ —\nאויף דעם איז די הוראה פון „עשרה בטבת״, אז אויב מען לאזט צו ח״ו א מצור אויף ירושלים — לכאורה, נאר אויף דער שלימות פון יראת השם — זאל מען וויסן די תוצאות וואס עס קומען ארויס דערפון.\nניט נאר וועט אזא חינוך ניט ברייננגען דעם קינד און צוגרייטן אים אז שפעטער, ווען ער וועט ווערן עלטער, זאל ער זיין שטארק אין יראת שמים כדבעי, וואורום: אזא חינוך ברייננגט אז „גם כי יזקין לא יסור ממנה״⁴⁵ פון דער וועג פון פשרות — נאר נאך מער: דורך דעם וואס מען איז אים מחנך אז מען „מעג״ פארבייגן אויף „קלות״ — איז די תוצאה דערפון, אז ער וועט פארבייגן אויך אויף „חמורות״.\nואדרבה — אויב מען וויל זיין זיכער אז דער קינד זאל זיין אפגעהיט אין חמורה שבחמורות — מוז מען אים זאגן דאס וואס עס שטייט אין תורת אמת. בשעת מען לערנט מיטן קינד אידישקייט, תורה באופן פון פשרות — דערפילט דער קינד סוף סוף אז מען זאגט אים ניט דעם אמת — ובמילא איז דאס היפך האמת, און ער פארלירט דעם צוטרוי צום מחנך (אויך בנוגע צו דעם וואס ער זאגט אים אן צו זיין אפגעהיט אין חמורה שבחמורות).\nאון וויבאלד אז יעדער פרט (סיי לטוב סיי למוטב) פון א מענטשן אין זיין יוגנט בעת ער איז נאך א „שתיל״ אדער א „גרעין״⁴⁶ אנטוויקלט זיך אין א פיל גרעסערע מאס בעת ער ווערט עלטער,",[["42","42","עקב י, יז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241073\" data-slug=\"likkutei-sichot\" data-id=\"1300241073\">לקו״ש חכ״ד ע׳ 73</a> ואילך."],["43","43","תהלים כד, א."],["44","44","ברכות לג, ב."],["45","45","משלי כב, ו. וברש״י שם: אם לטוב אם לרע. וראה רלב״ג שם."],["46","46","ראה שופטים כ, יט: כי האדם עץ השדה. וראה קונטרס חנוך לנער ע׳ 37. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011082\" data-slug=\"likkutei-sichot\" data-id=\"1300011082\">לקו״ש ח״א ע׳ 82</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061320\" data-slug=\"likkutei-sichot\" data-id=\"1300061320\">ח״ו ע׳ 310</a> ואילך."]]],[1300201370,"איז כדאי כל היגיעה וההשתדלות אז דער חינוך זאל זיין בשלימות בכל הפרטים.\nיא. עד״ז איז אויך בשעת מען טרעפט א אידן וואס אין יארן איז ער שוין א גדול, אבער ער איז א קטן, קליין אין ענינים פון אידישקייט, טאר מען ניט מאכן א חשבון:\nהיות אז אויב מען וועט אים זאגן וועגן שלימות פון (אידישקייט) תורה ומצוותי׳, אז עס זיינען אויך היינט דא תרי״ג מצוות דארף מען מורא האבן אז מען זאל אים אינגאנצן פארלירן, דעריבער וועט מען אים זאגן אז איצטער⁴⁷ האט מען צוגעפאסט, ר״ל, די תורה צו דער צייט און באשלאסן (דורך אן אפשטימונג פון די און די ברוב דעות) אז עס זיינען דא נאר א טייל פון די מצוות —\nח״ו ור״ל צו זאגן אזוי: מען דארף אים זאגן דעם אמת אז ער איז מחוייב (אזוי ווי אלע אידן אין אלע דורות) צו מקיים זיין אלע מצוות וואס תורת אמת הייסט זיי זיין, וואורום „זאת התורה לא תהא מוחלפת (ח״ו)״⁴⁸,\nאון אויב דערווילע קען מען אויף אים ניט פועל׳ן ער זאל גלייך מקיים זיין אלע מצוות — דארף מען אנהויבן צו ריידן מיט אים (בנוגע לקיום בפועל תיכף) בנוגע גלייך מקיים זיין א מצוה⁴⁹ וואס מ׳קען פועל׳ן (עכ״פ — בספק וספק ספיקא) און „מצוה גוררת מצוה״⁵⁰ — וועט די מצוה ברייננגען אים צום קיום פון נאך א מצוה⁵¹, ביז אז ער וועט ווערן „תמים ושלם בכל אברי הנפש״⁵² — ברמ״ח אברים כנגד רמ״ח מ״ע, און בשס״ה גידים כנגד שס״ה מל״ת.\nיב. דאס איז אויך פון די ענינים וואס מען דארף ארויסנעמען פון עשרה בטבת\n— ובמיוחד פון עשרה בטבת בשנה זו, וואס די קביעות פון עשרה בטבת איז ביום השלישי שהוכפל בו כי טוב⁵³, „טוב לשמים וטוב לבריות״⁵⁴ —\nאז נוסף צו דער תשובה וואס יעדער איד דארף טאן בנוגע צו די ענינים וואס בינו לבין קונו („טוב לשמים״), דארף זיין די תשובה אויך בנוגע צו טאן מיט אידן, ביז אפילו מיט „בריות״⁵⁵\nאז פון עשרה בטבת אן זאל ער אנהויבן טאן ביתר שאת וביתר עז אין דער עבודה פון „אוהב את הבריות ומקרבן לתורה״⁵⁶, דורך פועל׳ן אויף זיי",[["47","47","ידועה ה„קושיא״ — שאין עתה מצות קרבנות, חידוש תקנת פרוזבול וכו׳ — וקושיא מעיקרא אינה, כי זהו פרט מדין תורה בקרבנות שיהיו בביהמ״ק (כמו שהדין בבער״פ דוקא) ושמיטה רק ביחיד ולא בב״ד וכו׳."],["48","48","עיקר הט׳ מי״ג עיקרים. וראה רמב״ם הל׳ יסוה״ת רפ״ט. הל׳ מלכים פי״א סוף ה״ג. פיה״מ לפ׳ חלק יסוד התשיעי (ע״פ הוצאת הרב קאפח — שהחזיר עטרה — ההשמטות — למקומן)."],["49","49","שהרי גם כשהוא במצב כזה שאינו רוצה כלל לקיים מצוות, מחוייב הוא בכל אחת מהן [וכמ״ש הרמב״ם (אגרת השמד (ד״ה והמין הרביעי)) לענין ירבעם בן נבט — אף שהוא יוצא מהכלל דכל ישראל יש להם חלק לעוה״ב], ומחוייבים [מצד אהבת ישראל, ערבות, ועוד] להשתדל שיקיים מצוה — איזו שאפשר להשפיע עליו בזה והוכח תוכיח אפילו מאה פעמים."],["50","50","אבות פ״ד מ״ב."],["51","51","ראה ג״כ פיה״מ להרמב״ם במרז״ל (סוף מכות): רצה הקב״ה לזכות כו׳."],["52","52","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו״ת נצבים מה, ג</a>."],["53","53","ראה פרש״י בראשית א, ז."],["54","54","קידושין מ, א. ובאוה״ת (בראשית לג, ב. משפטים ע׳ א׳קנו. ועוד) מקשר זה עם יום השלישי שהוכפל בו כי טוב."],["55","55","ראה תענית כ, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."],["56","56","אבות פ״א מי״ב. וראה תניא שם."]]],[1300201371,"דעם קיום המצוות גלייך אין וואס עס לאזט זיך פועל׳ן אויף זיי, און אויב באמת לית ברירה — עכ״פ איין מצוה, עטליכע מצוות\nומה טוב — אנהויבענדיק פון די מצוות כלליות (די צען מבצעים⁵⁷) — וואס דאס וועט זיי ברייננגען סוף סוף (כנ״ל) צום קיום פון אלע מצוות.\nיג. נאך אן ענין אין „אוהב את הבריות ומקרבן לתורה״: אז בשעת מען זעט א אידן וואס מיינט אז מצד מצבו ומעשיו בעבר איז ער ניט שייך צו (כל ה)תומ״צ, און אבדה תקותו ח״ו — דארף מען אים מעודד זיין (ובתוקף ובספ״י) — דורך מסביר זיין אים אז בשעתא חדא וברגעא חדא קען ער נתהפך ווערן מן הקצה אל הקצה [און דאס איז ניט סתם אן עידוד לשם עידוד, נאר דאס איז א פס״ד פון תורת אמת⁵⁸],\nאויך דארף מען אים מסביר זיין (כאמור לעיל) אז דורך דעם וואס ער וועט אנהויבן מקיים זיין איין מצוה, עכ״פ, ובפרט פון די מצוות כלליות — איז דאס גופא וועט אין אים פועל׳ן א זיכוך און ברייננגען אים סו״ס צום קיום פון אלע מצוות.\nיד. די הוראה הנ״ל פון עשרה בטבת [אז מען טאר ניט פארבייגן אין מצוה צוליב א צווייטער] איז שייך במיוחד צו עסקנים:\nס׳זיינען דא ליידער אזוינע עסקנים וואס מאכן א „מסחר״ מיט מצוות. מען איז זיך עוסק „באמונה״ אין מוותר זיין אויף איין מצוה, מיטן אויסרייד אז צוליב דעם וועט מען „פארדינען״ א צווייטע מצוה (טענה׳נדיק, אז די מצוה וועלכע מען „פארדינט״ איז מער נוגע, אדער אז זי איז מער על סדר היום, וכיו״ב).\nדארף מען וויסן אז דער אוי־בערשטער איז „לא יקח שוחד״, און דאס וואס מען טאר ניט על פי תורה — איז א איסור גמור, אפילו ווען מען וויל זיך איינרייידן (אדער איינרייידן א צווייטן) אז דאס וואס מען שווייגט בנוגע איין ענין איז בכדי צו פארדינען א צווייטן ענין.\nובפרט נאך אז מען האט שוין אפגעטייטשט בפירוש בנוגע צו כמה ענינים אז די שתיקה פון די עסקנים איז א (שתיקה כ)הודאה.\nטו. והדגשה יתירה בכהנ״ל — לויט דעם רמז־פירוש אין „עוסק בצרכי צבור באמונה״ — אז די עסקנות איז דורכ־געדרונגען מיט אמונה אין דעם אויבערשטן,\nאז דאס וואס ער קען אויפטאן (דורך זיין עסקנות) בצרכי צבור איז עס ניט ח״ו מצד כוחו ועוצם ידו⁵⁹ (זיין חכמה וכו׳) נאר מצד דערויף וואס „הוא הנותן לך כח לעשות חיל״⁶⁰\nביז ועיקר — אז נאר די אמונה אין דעם אויבערשטן איז די סיבה וואס",[["57","57","הידועים והן: מבצע אהבת ישראל, חינוך, תורה, תפילין, מזוזה, צדקה, בית מלא ספרים — יבנה וחכמי׳, נרות שבת קודש ויו״ט, כשרות האכר״ש, וטהרת המשפחה."],["58","58","קידושין מט, ב. שו״ע אהע״ז סל״ח סל״א."],["59","59","וידועה דעת הסמ״ג (מל״ת סד) וז״ל: ומכאן אזהרה שלא יתגאה האדם במה שחננו הבורא הן בממון הן ביופי הן בחכמה אלא יש לו להיות ענו מאד ושפל ברך לפני ה׳ אלהים ואנשים ולהודות לבוראו שחננו זה המעלה .. וראיתי בחלום במראית הלילה הנה שכחת את העיקר השמר לך פן תשכח את הוי׳ .. והתבוננתי עליו בבקר והנה יסוד גדול הוא ביראת השם."],["60","60","עקב ח, יז־יח. *) התחלת הענין ד„כוחי ועוצם גו׳ כי הוא הנותן גו׳״."]]],[1300201372,"ברייננגט אים צו זיין אן עסקן: בשעת ער זעט אז מען איז אים מכריח צו טאן אין עסקנות ציבורית, חאטש ער איז באמת בורח מן הכבוד, ווייס ער, אז דאס איז א הוראה מלמעלה אז ער דארף טאן אין דעם און נאר דערפאר איז ער אן עסקן —\nבמילא איז דאך ניטא קיין ארט אז ער זאל ווערן א משוחד פון כבוד, פון דעם ביינקל וכו׳, און זיכער ניט — אז זיי זאלן ווערן „לחמו״ אן וועלכן (לדעתו) ער קען ניט אויסקומען —\nוואס דאמאלסט „פארקויפט״ ער די מצוה קלה (לדעתו) און דאס ווערט די התחלה אז מחמת דער דאגה תמידית פן יחסר לחמו — כבוד און דער ביינקל — פארקויפט ער א מצוה חמורה וכו׳,\nמשא״כ אויב בעל כרחך אתה עסקן, ועוד וג״ז עיקר ער ווייס כנ״ל אז זיין עסקנות והצלחה איז ניט כוחו ועוצם ידו נאר זיין עסק בזה איז א כלי און לבוש צום „וברכך הוי׳ אלקיך״⁶¹\n— איז פשוט, אז דאס וועט אויך ברייננגען⁶² ער זאל זיין „עוסק בצרכי צבור באמונה״ כפשוטו, צוליב טובת הציבור און ניט כו׳, און זיין עסקנות וועט זיין כפי רצון ה׳, וואס דאן דוקא איז עס א כלי צום ברכת ה׳.\n* * *\nויה״ר אז דער עסק בצ״צ באמונה לויט תוה״ק און דער חינוך באמונה לויט תוה״ק זאלן נאכמער צואיילען ביאת משיח צדקנו, און ער וועט מסיים זיין דעם גלות און דערנאך⁶³ וועט זיין די אתחלתא דגאולה, און תיכף דערנאך — די גאולה בשלימותה, „והיתה לה׳ המלוכה״⁶⁴.",[["61","61","ראה טו, יח."],["62","62","וכמשנ״ת בארוכה בקונטרס ומעין מכ״ה פ״ג. ד״ה וידעת תרנ״ז. וראה גם ד״ה בהקדמה (ג, א ואילך). סהמ״צ להצ״צ מצות תגלחת מצורע ס״ג."],["63","63","כפס״ד הרמב״ם הל׳ מלכים ספי״א ובתחלתו. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051161\" data-slug=\"likkutei-sichot\" data-id=\"1300051161\">לקו״ש ח״ה ע׳ 149</a> הערה 51."],["64","64","עובדי׳ א, כא."]]],[1300201373,"שיחת עשרה בטבת, יהפך לשמחה, אחרי תפלת מנחה, ה׳תשל״ח – בבית הכנסת –\nא. בהמשך צו דעם וואס עס האט זיך גערעדט נעכטן אין אווענט, אור ליום העשירי בטבת [וואס בשנה זו, איז (ווי דערמאנט אויך נעכטן) עשירי בטבת חל ביום השלישי שהוכפל בו כי טוב, „טוב לשמים וטוב לבריות״] בנוגע צו באנייען, אפרישן און מוסיף זיין אין דעם מנהג וואס איז געווען בכו״כ קהלות אז ביום התענית לאחרי חצות היום (בקשר מיט תפלת המנחה אדער אחרי תפלת מנחה) פלעגט מען ריידן דברי כבושין¹ —\nאיז אע״פ אז דאס איז ניט געווען נהוג בביהכנ״ס דרבותינו נשיאינו², און אויף מחדש זיין א נייעם ענין דארף מען האבן א זהירות יתירה\nפונדעסטוועגן, ווי גערעדט כמה פעמים (אויך אין די לעצטע התוועדות׳ן³), אז בשעת עס רעדט זיך וועגן ענינים וואס זיינען מוסיף אין יראת שמים [ובפרט, וואס זיינען מוסיף אין קיום המצוות בפועל, וואס המעשה הוא העיקר⁴] — איז דאס ניט נאר א הצדקה (א באראכטיקונג) אויף די נייע ענינים, נאר דאס איז אויך א התעוררות און א עידוד, וויבאלד מען זעט אז זיי זיינען מוסיף אין יראת שמים —\nוואס יראת שמים איז „זה⁵ השער לה׳ צדיקים יבואו בו״⁶ — דער טויער דורך וועלכן מען גייט אריין אין אלע ענינים פון תומ״צ [ובלשון הזהר⁷: „דא איהי תרעא לאעלא״].\nאון ווי עס שטייט אין זהר⁸ אויף „בזאת יבא אהרן אל הקודש״⁹, אז „זאת״ איז יראת ה׳. און אויף דעם זאגט מען — כפשטות הכתוב — „בזאת יבא אהרן אל הקודש״, אז דער אריינגיין פון דעם כהן גדול אין קודש הקדשים ביום הכיפורים, וואס ער איז דער יום המקודש מכל השנה, איז געווען „בהאי זאת״, וואס „דא היא יראת ה׳״,\nוואס די כניסה פון כה״ג ביום הכיפורים לקדה״ק, גיט דעם כח און מאיר אין דער עבודה פון יעדער אידן בכל ימי השנה, ביז אין מחשבה דיבור ומעשה¹⁰.\nב. בהמשך צום מנהג הנ״ל פון ריידן דברי כבושין — דארף ניט זיין אין דערויף דוקא אן אריכות, ווארום ווי־באלד אז יעדער איד וויל מקיים זיין דעם אויבערשטנס רצון (כפס״ד ברור",[["1","1","בכ״ז ראה בשיחה הקודמת ס״א ובהנסמן שם."],["2","2","לא בריגא, אטוואצק ולא כאן. וע״פ השמועה גם לא בליובאוויטש."],["3","3","דמוצאי ש״פ מקץ, שבת חנוכה, דזאת חנוכה ש.ז."],["4","4","אבות פ״א מי״ז."],["5","5","תהלים קיח, ב."],["6","6","כתר שם טוב סרל״ט (ל, ד). וראה גם זח״ב נא, א ובאו״ת להה״מ לתהלים עה״פ (עז, ד) שמקשר „זה השער לה׳״ עם „בזאת יבוא אהרן גו׳״."],["7","7","ח״א יא, ב."],["8","8","ח״ג נו, ב."],["9","9","אחרי טז, ג."],["10","10","כמובן מזה שעבודתו בקדה״ק מכפרת על כאו״א מבנ״י במחו״ד״מ שלהם. ובפרט ע״פ המבואר בכ״מ (עט״ר לז, א. אוה״ת שמע״צ ע׳ א׳תשפ. המשך וככה תרל״ז ספצ״ז. ועוד) שכפרת־תשובה יוהכ״פ היא תשובה שלימה שזדונות נעשו לו כזכיות."]]],[1300201374,"פון רמב״ם¹¹, איז דאך גענוג א ווארט, א רמז אליין,\nועאכו״כ אז איצט איז נאך דערויף וואס מען האט געזאגט און געהערט די הפטרה „דרשו הוי׳ גו׳״ —\nוועט מען דעריבער בלויז דערמאנען (און מבאר זיין קצת) אן ענין וואס מען האט ערשט געזאגט אין דער הפטרה [וואס איז כולל כל הענינים], די דברים נפלאים וואס דער אויבערשטער זאגט דורך ישעי׳ הנביא\n[וואס ער האט געהייסן מיטן נאמען ישעי׳ ווייל ענינו איז געווען ישועה¹², כולל די ישועה פון דער גאולה האמיתית והשלימה ע״י משיח צדקנו¹³],\nוואס פון דעם וואס די נבואה איז נכתבה — איז א ראי׳ אז הוצרכה לדורות¹⁴,\nובפרט נאך אז מען האט קובע געווען צו זאגן די נבואה הנ״ל אין א הפטרה — די הפטרה פון די ימי הצומות, כולל אויך דעם „צום העשירי״.\nג. פון די ענינים וואס מען זאגט אין דער הפטרה איז: „כה אמר ה׳ שמרו משפט ועשו צדקה גו׳״¹⁵ — דער אויבערשטער זאגט צו אידן אז זיי זאלן טאן אין משפט (תורה¹⁶) און אין צדקה\n[וואס די צוויי זאכן ברייננגן די גאולה ווי עס שטייט¹⁷ „ציון במשפט תפדה ושבי׳ בצדקה״],\nאון ער איז מוסיף „כי קרובה ישועתי לבוא״, מיין ישועה — די ישועה פון דעם אויבערשטן, כביכול¹⁸, איז אפהענגיק אין דעם וואס יעדער איד, און אלע אידן, וועלן טאן אין משפט (תורה) און טאן אין צדקה.\nד. דערנאך איז ער מוסיף „וצדקתי להגלות״, אז דעמאלט (ווען עס וועט קומען „ישועתי״) וועט אויך נתגלה ווערן די צדקה פון דעם אויבערשטן („וצדקתי״) — דאס וואס „צדקה עשה הקב״ה בישראל שפיזרן לבין האומות״¹⁹.\nדער ענין פון „פיזרן לבין האומות״ איז א פלא און א תמיהה הכי גדולה: היתכן אז בנו יחידו של ממה״מ הקב״ה [וואס אלע אידן, אפילו ווען זיי געפינען זיך אין קושי השיעבוד פון מצרים, זיינען זיי מאמינים בני מאמינים²⁰. ביז אז תורת אמת איז מעיד אז יעדער איד, יהי׳ מי שיהי׳, וויל מקיים זיין דעם אויבערשטנס רצון (ווי געבראכט פריער דעם פס״ד ברור פון רמב״ם)] וואס דארף זיך געפינען בא אביו המלך, זאל גאר זיין אין גלות?\nאויף דעם זאגט ער „וצדקתי להגלות״, אז לע״ל וועט נתגלה ווערן ווי דער גלות איז געווען אן ענין פון צדקה.\nאיצטער — איז עס בבחי׳ אמונה: ווי־באלד אז חז״ל זאגן „צדקה עשה הקב״ה בישראל שפיזרן לבין האומות״, גלויבט מען אז דאס איז אזוי. דאס איז אבער נאך ניט בגילוי בהבנה²¹. לע״ל וועט זיין",[["11","11","הל׳ גירושין ספ״ב."],["12","12","פרש״י ומצו״ד ישעי׳ מט, א. וראה זח״ב קעט, סע״ב. ובארוכה — ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181353\" data-slug=\"likkutei-sichot\" data-id=\"1300181353\">לקו״ש חי״ח ע׳ 343</a> ואילך ובהנסמן שם."],["13","13","שעליו ניבא בכו״כ מקומות בספרו."],["14","14","מגילה יד, א."],["15","15","ישעי׳ נו, א."],["16","16","לקו״ת ר״פ דברים עה״פ ציון במשפט תפדה."],["17","17","ישעי׳ א, כז."],["18","18","ראה מגילה כט, א."],["19","19","פסחים פז, ב."],["20","20","שבת צז, א."],["21","21","כי לאחרי כל הביאורים בזה (בירור הניצוצי קדושה (תו״א ר״פ לך. תו״ח ר״פ ח״ש. ביאוה״ז"]]],[1300201375,"„וצדקתי להגלות״, אז מען וועט זעהן בגילוי ווי דער גלות איז געווען אן ענין של צדקה.\nה. און אויך דאס (דער „וצדקתי להגלות״) איז אפהענגיק אין דעם „שמרו משפט ועשו צדקה״ וואס אידן טועהן אויף ממהר זיין דעם „קרובה ישועתי״.\nאע״פ אז מען גלויבט באמונה שלימה בדברי חז״ל אז דער גלות איז אן ענין של צדקה,\nאיז אבער צוזאמען דערמיט איז מען מתפלל און זועק וצועק²² אז עס מוז שוין זיין דער „קץ שם לחושך״²³ [ובפרט לויטן פס״ד ברור בש״ס²⁴ אז ס׳איז שוין „כלו כל הקיצין״ (אז ס׳איז שוין נאך אלע קיצין, לויט אלערליי חשבונות) ובמילא מוז שוין זיין „מיד הן נגאלין״²⁵],\nוואס דאס (די תפלה וצעקה) ברייננגט אויך א הוספה אין דעם „שמרו משפט ועשו צדקה״\n— סיי אין משפט (תורה) און צדקה כפשוטם, ביז אויך ווי זיי זיינען בפנימיות הענינים [כמובא בתורת החסידות הכללית דורכן בעש״ט און מבואר בתורת חסידות חב״ד דורך דעם אלטן רבי׳ן און רבותינו נשיאינו ממלאי מקומו] —\nברייננגט דאס ניט נאר דעם „קרובה ישועתי״ [אז דער אויבערשטער איז ממלא די בקשה פון אידן און נעמט זיי ארויס פון גלות בשעתא חדא וברגעא חדא], נאר אויך דעם „וצדקתי להגלות״ — אז מען וועט זעהן די „צדקה״ פון דעם ענין הגלות.\nו. דערנאך איז ער מוסיף אין דער הפטרה נאך אן ענין — אז אויך די „בני הנכר״ וועלן זיין „נלוים על ה׳ לשרתו ולאהבה את שם ה׳ להיות לו לעבדים גו׳״²⁶:\nבזמן הגלות זיינען דאך א טייל פון די בני הנכר אין אן אופן פון (ווי ער זאגט אין תהלים²⁷) „רגשו גוים ולאומים יהגו״,\nאיז נוסף צו דער הבטחה גמורה וואס דוד מלך ישראל (וואס ער איז חי וקיים) איז מבטיח²⁸, אז אויך (בשעת דעם „רגשו״ און „יהגו״) איצטער (בזמן הגלות) איז דאס „ריק״, און אז דער אויבערשטער לאכט זיך אויס פון דעם גאנצן ענין (ווי ער איז מפרט אין תהלים²⁹ בארוכה),\nהאט מען אויך די הבטחה אז לע״ל וועלן בני הנכר זיין „נלוים על ה׳ לשרתו גו׳ להיות לו לעבדים גו׳״ ביז אז",[["","","(לאדהאמ״צ) קלו, א ואילך. ובכ״מ). עונש דחטאינו וכו׳) הרי כמה דרכים למקום ולא ע״י יסורים ר״ל ובפרט יסורי גלות דקשה ממיתה (ראה ס׳ החינוך מצוה תי). וי״ל דביאורים הנ״ל הם הסברה ע״פ סדר ההשתל׳ והעולמות (לאחרי שנבה״ע ומדידה והגבלה שלו כפי שעלה ברצון), אבל לפנ״ז — אין הגבלות, וכמה דרכים כו׳ כנ״ל. ודוגמתו בטעמי ברה״ע — שישנם כמו שהוא לנשמות באצילות וכו׳, אבל הטעם בעצם כי נתאווה הקב״ה כו׳ (ראה המשך תרסי״ג ע׳ ז׳ ואילך. ע׳ תמו). עד״ז בענין דאתדל״ע נמשכת באתדל״ת. ועוד. ואכ״מ."],["22","22","ויתרה מזה — התורה מצווה להתפלל וכו׳ ע״ז ולהתפלל כו״כ פעמים — בתפלת יה וכו׳. והוספה בימי הצומות, בברכות ההפטורה ודעננו."],["23","23","איוב כח, ג."],["24","24","סנהדרין צז, סע״ב."],["25","25","לשון הרמב״ם הל׳ תשובה פ״ז ה״ה."],["26","26","ישעי׳ נו, ו."],["27","27","ב, א."],["28","28","בתהלים שם."],["29","29","שם, ד ואילך."]]],[1300201376,"„כי ביתי בית תפלה יקרא לכל העמים״³⁰\n[וואס דאס איז מתאים מיט דעם וואס שטייט „אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה׳ לעבדו שכם אחד״³¹ — ווארום „לעבדו״ איז דער ענין התפלה],\nאון ער איז מסיים (בההפטרה) „עוד אקבץ עליו לנקבציו״³² — אז נוסף אויף דעם וואס עס וועט זיין (כהתחלת הכתוב) „מקבץ נדחי ישראל״, וועט נאך צוקומען אויך און אין זיי (אין די אידן, „עליו לנקבציו״) א הוספה פון די ניצוצי קדושה שבאומות העולם³³.\nז. שוין גערעדט כמה פעמים בנוגע צו דעם וואס דער אלטער רבי פסק׳נט אין שו״ע³⁴ אז בערב שבת דארף מען טועם זיין „מכל תבשיל ותבשיל״, אז די זעלבע זאך איז בנוגע צו די שיתא אלפי שנין (וואס זיי זיינען כנגד די ששת ימי בראשית³⁵) — אז „בערב שבת״ דארף זיין די טעימה פון יעדער ענין („מכל תבשיל ותבשיל״) וואס וועט זיין לע״ל.\nאון וויבאלד אז אלץ וואס דער אויבערשטער הייסט אידן טאן איז ער דאס (אויך) מקיים³⁶, און נאך ביתר שאת וביתר עז — איז א זיכערע זאך, אז דער אויבערשטער גיט אידן [יעדער אידן³⁷ און אלע אידן] צו פארזוכן פון יעדער ענין טוב וואס וועט זיין אז ס׳וועט קומען די גאולה האמיתית והשלימה.\nד.ה. אז נוסף דערצו וואס דער אויבערשטער העלפט יעדער אידן אין דער עבודה פון „שמרו משפט ועשו צדקה״, אז ער זאל האבן חיות אין לימוד התורה (משפט) און אין קיום המצוות (צדקה) בהידור, ביז אין אן אופן פון „מהדרין מן המהדרין״\n[אין אן אופן אז דאס זאל זיין פאר־בונדן מיט „צדקתי״ און „ישועתי״ של הקב״ה, מיט גליא דקוב״ה און אויך מיט סתים דקוב״ה — וואס צו דעם פאדערט זיך אז דער „שמרו משפט״ זאל זיין אין גליא דאורייתא און אויך אין סתים דאורייתא³⁸,\nוואס אויך דאס (סתים דאורייתא) איז שייך צו יעדער אידן, ווארום יעדער איד האט א חלק סיי אין פשט סיי אין רמז סיי אין דרוש סיי אין סוד,\nווי עס שטייט אין כתבי האריז״ל³⁹, אז אין יעדער ענין פון תורה — סיי אין פשט, סיי אין רמז, סיי אין דרוש, סיי אין סוד — זיינען דא ששים ריבוא פירושים, כנגד ששים ריבוא ישראל (וואס אין דעם זיינען נכלל אלע נשמות⁴⁰),\nביז אז ס׳איז א פס״ד אז עס איז דא א חיוב אויף יעדער אידן צו לערנען און „להשיג מידיעת התורה הן בפשטי ההלכות הן ברמזים ודרשות וסודות״⁴¹],\nוועט ער אויך געבן צו פארזוכן ב„ערב שבת״ דעם „תבשיל״ דלע״ל",[["30","30","ישעי׳ שם, ז."],["31","31","צפני׳ ג, ט."],["32","32","ישעי׳ שם, ח."],["33","33","שאוה״ע עצמם יביאום וכמש״נ בכמה נבואות ישעי׳, ועד ש„והיו מלכים אומניך גו׳״ (ישעי׳ מט, כג)."],["34","34","או״ח סו״ס רנ."],["35","35","רמב״ן בראשית ב, ג. סידור דרושי ר״ה רלד, א. ועוד."],["36","36","שמו״ר פ״ל, ט."],["37","37","שהרי כל ישראל יש להם חלק לעוה״ב (סנהדרין ר״פ חלק)."],["38","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380096\" data-slug=\"likkutei-torah\" data-id=\"4001380096\">ראה זח״ג עג, א</a>. לקו״ת ויקרא ה, ג."],["39","39","שער הגלגולים הקדמה יז. ש׳ רוה״ק (קח, ב). ליקוטי מהרח״ו שבסוף ש׳ מרז״ל."],["40","40","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז (מח, א</a>)."],["41","41","הל׳ ת״ת לאדה״ז פ״א ס״ד."]]],[1300201377,"בנוגע די אומות, אז נאך זייענדיק בזמן הגלות וועט שוין זיין א מעין פון „ובני הנכר הנלוים על ה׳ לשרתו גו׳״, ביז א מעין פון „והיו⁴² מלכים אומניך ושרותיהם מניקותיך״.\nאון וויבאלד אז לויט אלע סימנים פון סוף מס׳ סוטה האלט מען שוין גאר נאענט צו דער גאולה — ובפרט אז מען האט געהערט מפורש און ברור⁴³ פון כ״ק מו״ח אדמו״ר נשיא דורנו אז איצטער איז שוין דער זמן הכי אחרון פון גלות — איז דאך פארשטאנדיק, אז מען קען שוין דאס (דעם „לטעום מכל תבשיל ותבשיל״) מער ניט אפלייגן ח״ו,\nאון דעריבער איז שוין צייט אז ניט נאר זאלן זיי מפסיק זיין דעם לחץ און די איומים, נאר אדרבה, זיי זאלן ארויס־העלפן אידן בכל מושבותיהם בכל הענינים הגשמיים, אז אידן זאלן קענען מוסיף זיין אין משפט וצדקה מתוך מנוחת הנפש און מנוחת הגוף,\nאון דאס וועט מוסיף זיין נאך מער זריזות אין דעם „אחישנה״ פון דער גאולה האמיתית והשלימה דורך משיח צדקנו,\nוואס דעמולט וועט מען ניט נאר טועם זיין פון יעדער תבשיל, נאר מען וועט האבן דעם תבשיל, יעדער תבשיל, באופן דאכילה,\nאון וויבאלד אז „ואתם תהיו לי ממלכת כהנים״⁴⁴ — וועט די „אכילה״ זיין מתוך גדלות⁴⁵ ומתוך שמחה וטוב לבב.\nאון בכדי אז כל הנ״ל זאל זיין בזריזות — דארף מען מוסיף זיין בזריזות אין תורה און צדקה, און אויך אין תפלה (וואס על ידה זיינען די תורה און צדקה ווי עס דארף צו זיין⁴⁶) ובמכש״כ פון דעם וואס אפילו בנוגע צו „כל העמים״ דארף זיין „בית תפלה יקרא לכל העמים״.\nויהי רצון אז בקרוב ממש זאל מקויים ווערן דער פס״ד הרמב״ם⁴⁷ אז „כל הצומות האלו״ (כולל אויך דעם צום העשירי) וועלן נהפך ווערן „לששון ולשמחה ולמועדים טובים והאמת והשלום אהבו״,\nבעגלא דידן, במהרה בימינו אמן.",[["42","42","ישעי׳ שם."],["43","43","ראה שיחת ח״י אלול תש״א. מכתב כ״ק מו״ח אדמו״ר היום יום בתחלתו. הקול קורא דלאלתר לגאולה (הקריאה והקדושה סיון, תמוז, מנ״א תש״א. תשרי תש״ג. אגרות קודש שלו (ח״ה ע׳ שסא; שעז: תח; ח״י ע׳ תל)). ועוד."],["44","44","יתרו יט, ו."],["45","45","כמו אכילת (קדשים ד)כהנים (קרח יח, ח. זבחים צא, א). וכן ע״פ פרש״י (יתרו שם) „כהנים״ — שרים הרי ענינם שררה וגדלות."],["46","46","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">לקו״ת ברכה צו, ב</a>. ובכ״מ (לענין תורה). ומזה מובן גם לענין צדקה (מצוות) — מכיון ש(גדול) תלמוד (ש)מביא לידי מעשה. ולהעיר מהפס״ד (או״ח סקנ״ג): מביהכ״נ (תפלה) לביהמ״ד (תורה) ואח״כ ילך לעסקיו (שאז הוא עיקר העבודה דצדקה). וראה לקו״ש ח״ה ע׳ 438, שהצדקה שקודם התפלה (יהיב פרוטה לעני והדר מצלי) — ענינה הוא הכנה לתפלה (ולא כ״כ העבודה דצדקה מצד עצמה), ועיקר העבודה דצדקה (מצד עצמה) היא לאחרי התפלה ותורה, כנ״ל."],["47","47","הל׳ תעניות בסופן."]]],[1300201378,"הוספות * שיחות"],[1300201379,"מפתח\nמוצאי ש\"פ נח , ו'מ\"ח,תש\"מ .....\nש\" פלך לך , ח'מ\"ח , תשמ \"א ...,..\nש\"פ וירא , כ'מ\"ח,תש\"מ ........\nג' , טו \" בכסלו , תשמ \"א .........\nי\"ט כסלו , תשמ \"כ ..... ..............\nכ\"ג כסלו , תש \"מ ...... ,.,...........\n437 ' 456 . . . .\n. . . . . .\n. . . . . . .\n. . . . . . .\n. . . . . . .\n,\nכ\"ה כסלו , תשמ \"א ... ..............\nג',ב' דחנוכה , תשל \"ח ... ....,.........\nכ\"ו כסלו , תש \"מ ...... ............,.\n'\nאור לח .דחנוכה ,חשל \" ט . . . . . . . . . , . . . . . .\nאו רל 1, זאת חנוכה \" , תשמ \"ב .,............\nזאת חנוכה ,תשמ \" ב . . . . . . . . . . . . . . . . . . .\nג' , עשרה בטבת , תשל \"ט\n.\n. .\nר' , עשרה בטבת , תשמ \"א .\n. .\n. . . . . . . . . .\n. .\n,\n. . . . . . . . . . . .\n, 377 381 386 417 432 468 472 486 496 509 518 526"],[1300201380,"א. מ׳האט שוין גערעדט כמ״פ¹ אז בסיום פון חודש תשרי הויבט זיך אן דער ענין פון „ויעקב הלך לדרכו”²,\nדעמולט גייט מען ארויס פון דעם חודש וואס איז „מרובה במועדות”³ — אין ימי המעשה פון חודש חשון, מ׳פארנעמט זיך מיט עובדין דחול אין עוה״ז התחתון שאין למטה ממנו,\nוואס די כוונה שבזה איז — דורכפירן דעם אויבערשטנ׳ס רצון, וואס נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים⁴.\nב. דער כללות הענין פון „ויעקב הלך לדרכו” הויבט זיך שוין אן אין חודש תשרי (כדלקמן), נאר אין דערויף גופא זיינען דא כמה דרגות⁵, און תכלית השלימות פון „ויעקב הלך לדרכו” איז — ווען מ׳גייט ארויס פון חודש תשרי און מ׳גייט אריין אין חודש חשון.\nוהביאור בזה:\nדי התחלה פון „ויעקב הלך לדרכו” איז במוצאי יוהכ״פ⁶, דעמולט הויבט זיך אן די המשכת אלקות מלמעלה למטה⁷, וואס דאס איז דער ענין פון „ויעקב — דלמעלה⁸ — הלך לדרכו”,\nאון וויבאלד אז „נשתלשלו מהן”⁹ — קומט דאס אויך אראפ אין „יעקב” דלמטה, א נשמה בגוף, אז ביי אים ווערט „ויעקב הלך לדרכו”.\nג. די צווייטע דרגא אין „ויעקב הלך לדרכו” איז — במוצאי שמח״ת:\nבמוצאי יוהכ״פ שטייט א איד אין א מעמד ומצב נעלה ביותר, ווארום ער קומט ערשט פון אמירת „ה׳ הוא האלקים” ז״פ, (ולפנ״ז) „ברוך שם כבוד מלכותו לעולם ועד” ג״פ, און „שמע ישראל ה׳ אלקינו ה׳ אחד” פ״א, וואס דאס איז דער ענין פון מס״נ (בכח, וואס ווערט פארערכנט אזוי ווי מס״נ בפועל), וואס מס״נ איז תכלית השלימות אין עבודת האדם (מלמטלמ״ע).\nאון תיכף לאח״ז זיינען „כל ישראל עסוקין במצוות”, „זה עוסק בסוכתו וזה בלולבו וכו׳”¹⁰ — איז בפועל האט מען דעמולט קיין שייכות ניט מיט עובדין דחול און דברים תחתונים (וואס אין דערויף באשטייט דער עיקר החידוש פון „ויעקב הלך לדרכו”, אין זיין וועג, אין עניני הרשות און עובדין דחול)¹¹.\nאון ערשט במוצאי שמח״ת, וואס דעמולט איז דער סיום פון די „ימים טובים” פון חודש תשרי — הויבט זיך אן (בפרטיות יותר) דער ענין פון „ויעקב הלך לדרכו”, אז מ׳גייט אויפטאן אין",[["1","1","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151272\" data-slug=\"likkutei-sichot\" data-id=\"1300151272\">לקו״ש חט״ו ע׳ 259</a>. וש״נ."],["2","2","ל׳ הכתוב — ויצא לב, ב."],["3","3","ב״י או״ח סתצ״ב. השלמה לשו״ע רז״ל סקל״א ס״ח. שו״ע אדה״ז שם ס״ב."],["4","4","תנחומא נשא טז. במדב״ר פי״ג, ו. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>."],["5","5","ראה שיחת מוצאי שבת בראשית תשל״ח ס״ב (לעיל ע׳ 266) ואילך."],["6","6","ראה המשך וככה תרל״ז רפצ״ז."],["7","7","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381049\" data-slug=\"likkutei-torah\" data-id=\"4001381049\">לקו״ת סוכות פא, ב</a>. אוה״ת אמור ריש ע׳ קפא. ועוד."],["8","8","ראה ב״ר פס״ח, יב: את (יעקב) הוא שאיקונין שלך חקוקה למעלה, עולים למעלה ורואים איקונין שלו כו׳. מארא בערכו. ובכ״מ."],["9","9","ל׳ התניא רפ״ג."],["10","10","ויק״ר פ״ל, ז."],["11","11","והעבודה ד„ויעקב הלך לדרכו” שלאחרי יוהכ״פ היא בעניני תומ״צ, כמפורש בהמשך וככה שם: שהלך לדרכו בדרך התורה והמצוות להיות בבחי׳ סו״מ ועש״ט שזהו דרך ה׳. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151277\" data-slug=\"likkutei-sichot\" data-id=\"1300151277\">לקו״ש חט״ו ע׳ 264</a> הערה 35."]]],[1300201381,"עניני הרשות און עובדין דחול, אז דארטן זאל ווערן א דירה לו ית׳.\nד. און תכלית השלימות פון „ויעקב הלך לדרכו” איז — ווען עס ענדיקט זיך חודש תשרי און עס הויבט זיך אן חודש חשון, און אין דערויף גופא — נאך ר״ח חשון:\nגלייך אויף מארגן פון שמח״ת איז „אסרו חג”¹², און אויך לאח״ז איז דאך דער „מנהג ישראל” אז מען זאגט ניט קיין תחנון „עד סוף תשרי”¹³ — וואס תחנון איז פארבונדן מיט עניני חול [וואס דארטן קענען זיין פעולות אויף וועלכע מ׳דארף אנקומען צו דעם ענין פון תחנון], איז דערפון פארשטאנדיק, אז חודש תשרי¹⁴ האט מען מצ״ע קיין שייכות ניט מיט עניני חול.\nאון בר״ח חשון — דער ערשטער טאג ר״ח איז דאך דער יום השלושים פון חודש תשרי, און דער צווייטער טאג ר״ח (וואס ער איז דער ערשטער טאג פון חודש חשון) האט אויך ניט קיין שייכות מיט עניני חול, ווארום ר״ח איז ניט קיין „יום המעשה”¹⁵.\nאון דערפאר איז תכלית השלימות פון „ויעקב הלך לדרכו” — נאך ר״ח חשון, וויבאלד אז דעמולט הויבן זיך אן ימי המעשה, אין וועלכע מ׳פארנעמט זיך מיט עובדין דחול וואס געפינען זיך אין עוה״ז הגשמי והחומרי שאין למטה ממנו, און דארטן פירט מען דורך דעם נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים.\nאון דאס איז איינע פון די סיבות אויף דער התוועדות — מעורר זיין נאכאמאל וועגן דעם ענין פון „ויעקב הלך לדרכו”, ווען מ׳האלט אין דעם זמן וואס איז דער תכלית השלימות פון „ויעקב הלך לדרכו” — לאחרי שקיעת החמה פון בדר״ח חשון און צאת הכוכבים, וואס דעמולט הויבט זיך שוין אן דער טאג פון ב׳ חשון.\n• • •\nה. אין דערויף קומט צו נאך א הוראה נוספת וואס מ׳לערנט איר אפ פון דער קביעות פון ב׳ חשון אין ימי השבוע בשנה זו:\nלויט קביעות שנה זו [וואס יו״ט של ר״ה, דער ערשטער טאג פון חגה״ס, און שמע״צ, זיינען געווען „ביום שמחתכם אלו השבתות”¹⁶] קומט אויס ב׳ חשון אין יום השלישי בשבוע, וואס ענינו פון יום השלישי איז — „הוכפל בו כי טוב”¹⁷, „טוב¹⁸ לשמים וטוב לבריות”¹⁹.\nוכמדובר כמ״פ אז ס׳איז ניט דער טייטש אז א משך זמן פון יום השלישי",[["12","12","ראה שו״ע אדה״ז או״ח סתכ״ט סי״ז."],["13","13","סידור אדה״ז לפני ובא לציון. מג״א או״ח סו״ס תרס״ט. השלמה לשו״ע ר״ל שם."],["14","14","שהרי גם בימים שבין ר״ה ליוהכ״פ שאומרים בהם תחנון, ה״ז (בעיקר) על העבר (וכמו ביוהכ״פ, שאין השטן שולט (יומא כ, א)), והוי הוא בהמצאו, קירוב המאור אל הניצוץ (ד״ח יג, ריש ע״ד. כא, סע״ב. צא, א. קונטרס העבודה ספ״ה (ע׳ 35)) — וכמים הפנים אה״פ הניצוץ אל המאור."],["15","15","ראה ש״א ב, יח ובמפרשים שם. לקו״ת ברכה ד״ה והי׳ מדי חודש בחדשו."],["16","16","בהעלותך י, י. ספרי עה״פ."],["17","17","ראה פרש״י בראשית א, ז."],["18","18","קידושין מ, א. ובאוה״ת (בראשית לג, ב. משפטים ע׳ איקנז. ועוד) מקשר זה עם יום השלישי שהוכפל בו כי טוב."],["19","19","להעיר מהשייכות ד„ביום שמחתכם” להענין ד„טוב לשמים וטוב לבריות” — ע״פ המבואר בכ״מ (ראה רמב״ם הל׳ יו״ט פ״ו הי״ח. שו״ע אדה״ז או״ח סתקכ״ט סי״א. וראה סידור שער הסוכות רנז, רע״ג) שבשעה שהשמחה היא כדבעי, ה״ה משתף בה גם אחרים, ואפילו בריות (ראה המשך שמח תשמח תרנ״ז ע׳ 50 ואילך)."]]],[1300201382,"איז ענינו „טוב לשמים”, און א משך זמן פון יום השלישי איז — „טוב לבריות”, נאר יעדער רגע פון יום השלישי איז א רגע פון א טאג וואס ענינו איז „טוב לשמים וטוב לבריות”,\nוואס „טוב לשמים” איז כולל אויך דעם העכסטן אפטייטש אין „שמים”, און „טוב לבריות” איז כולל אויך די דרגא הכי תחתונה אין „בריות”²⁰ — איז דער אויפטו פון יום השלישי אז אין יעדער רגע שבו שטייען ביידע ענינים („טוב לשמים” און „טוב לבריות”) צוזאמען, אזוי אז מ׳קען גארניט פאנאנדערטיילן צווישן זיי.\nועד״ז בנוגע צו די פעולות וואס זמנם ביום השלישי — אז יעדע פעולה וואס ווערט געטאן ביום השלישי, איז א פעולה וואס ענינה (דארף זיין ובמילא —) איז „טוב לשמים וטוב לבריות”.\n[אע״פ אז בחיצוניות איז עס אן ענין שבין אדם למקום, „טוב לשמים”, אדער אן ענין שבין אדם לחבירו, „טוב לבריות” — אעפ״כ, מצד פנימיות הענינים [וואס די פנימיות געוועלטיגט און נעמט דורך די חיצוניות] קען מען ניט מבדיל זיין און מפריד זיין צווישן דעם „טוב לשמים” מיטן „טוב לבריות”].\nו. האמור לעיל (אז ענינו פון יום השלישי איז „טוב לשמים וטוב לבריות”) איז שייך אין יעדן יום שלישי פון ימי השבוע — עס קומט אבער צו די הוראה דערפון וואס ב׳ חשון (התחלת ימי המעשה דכל השנה כולה — תכלית השלימות פון „ויעקב הלך לדרכו”) קומט אויס ביום השלישי שהוכפל בו כי טוב, „טוב לשמים וטוב לבריות”.\nוהביאור בזה י״ל:\nדער סיום וחותם פון די ימים טובים פון חודש תשרי איז — „שמחת תורה”.\nדער אפטייטש פון „שמחת תורה” איז²¹ (אויך) — אז די תורה עצמה פרייט זיך, וכידוע דער פתגם פון כ״ק מו״ח אדמו״ר וועגן די ריקודים פון שמח״ת, אז די תורה טאנצט און זינגט, נאר כדי אז ס׳זאל ארויסקומען בפועל, דארף מען האבן דעם אידן [וואס „אתם קרויין אדם”²², „ע״ש אדמה לעליון”²³] וואס ער ווערט די פיס פון דער תורה²⁴, און דער פה (וואס איז מנגן דעם ניגון) פון תורה.\nד.ה. אז אע״פ וואס ענינה פון תורה איז הבנה והשגה, ווארום זי איז חכמתו של הקב״ה, אעפ״כ, ווען עס קומט שמח״ת, שטייט די תורה למעלה מכל מדידה והגבלה (שמחת תורה), העכער פון איר דרגא אלס חכמתו של הקב״ה, נאר „ואהי׳ שעשועים גו׳ לפניו”²⁵, ביז „שעשוע המלך בעצמותו”²⁶,\nאון וויבאלד אז בשמח״ת שטייט די תורה אין אן אופן פון „שעשוע המלך בעצמותו”, גיסט זי זיך אריבער כביכול איבער אירע כלים און מדידה והגבלה, און דאס ברענגט ארויס די שמחה און ריקודים פון תורה.\nז. עד״ז בנוגע צום מעמד ומצב פון אידן, אז בשמח״ת שטייט א איד למעלה מכל מדידה והגבלה:",[["20","20","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פל״ב</a>."],["21","21","בהבא לקמן — ראה גם בשיחות דשמח״ת ש.ז."],["22","22","יבמות סא, א."],["23","23","של״ה כ, ב. שא, ב. ובכ״מ."],["24","24","סה״ש תש״ד ע׳ 36."],["25","25","משלי ח, ל."],["26","26","עמה״מ — הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381237\" data-slug=\"likkutei-torah\" data-id=\"4001381237\">לקו״ת שה״ש כז, א</a>."]]],[1300201383,"עס איז ידוע דער פתגם פון רבותינו נשיאינו²⁷ אז בשמח״ת באשטייט עבודת היום (ניט אין דער הבנה והשגה פון ענינים (עמוקים) שבתורה, נאר) אין שמחה וריקודים.\nוואס אין דעם ענין הריקודים גלייכן זיך אויס אלע אידן, פון „ראשיכם שבטיכם” ביז „חוטב עציך ושואב מימיך”²⁸.\nדערפון איז פארשטאנדיק, אז בשמח״ת שטייט א איד העכער פון זיינע מדידות והגבלות (וואס אין דערויף זיינען די חילוקים צווישן „ראשיכם שבטיכם” און „חוטב עציך ושואב מימיך”), און דערפאר שטייען דעמולט אלע אידן בהשוואה.\nבסגנון אחר:\nבשמח״ת שטייט א איד בגלוי אין דעם אופן ווי ער שטייט בשרשו ומקורו, וואס דער שורש ומקור פון א אידן איז העכער פון תורה, ווי עס שטייט אין תדבא״ר²⁹ „שני דברים קדמו לעולם תורה וישראל, ואיני יודע איזה מהם קודם, כשהוא אומר צו את בנ״י דבר אל בנ״י, אומר אני ישראל קדמו”, ד.ה. אז נש״י זיינען מושרש נאך העכער פון תורה.\nאון ווי ס׳איז אויך פארשטאנדיק דערפון וואס דער מגיד³⁰ איז מבאר דעם ענין פון „ישראל עלו במחשבה”³¹, אז „קודם שנבראו ישראל הי׳ נחקק צורתם במחשבה”, בדוגמת האב וואס איז מצייר במחשבתו צורת בנו (נאר „אצל השי״ת שייך זה לומר אף קודם שנבראו”), און וויבאלד אז עלה לפניו ית׳ דער תענוג וואס ער וועט האבן פון עבודת הצדיקים (כמרז״ל³² „במי נמלך בנשמותיהן של צדיקים”³³), האט ער זיך מצמצם געווען „כדמיון אב המצמצם את שכלו ומדבר דברי קטנות בשביל בנו הקטן”³⁴ —\nד.ה. אז אויך אין דער דרגא וואו עס איז נאך ניט שייך דער ענין פון בריאה („קודם שנבראו”), איז שוין דארטן דא די מציאות פון אידן.\n[וואס דאס איז ניט פארבונדן מיט א מעלה מסוימת וואס איז דא ביי א אידן (אז ער האט אן אות בתורה³⁵ וכיו״ב), נאר ס׳איז פארבונדן מיטן עצם המציאות פון א אידן,\n[ווי ס׳איז אויך מודגש אין דעם משל פון מגיד³⁴ אז אידן זיינען בדוגמת בן קטן — וואס אויב עס רעדט זיך וועגן א מעלה מסוימת, איז ער שוין ניט קיין קטן (בכל, באמת), ווארום ס׳איז דא איינער וואס האט ניט די מעלה, איז דאך יענער קלענער פון דעם וואס האט די מעלה],\nאון דערפאר זיינען אלע אידן גלייך אין דערויף].\nביז אז בשמח״ת שטייען אידן אין אן אופן פון „ישראל ומלכא בלחודוהי”³⁶,",[["27","27","סה״ש תש״ה ע׳ 58."],["28","28","ואדרבה: בענין הריקוד מודגשת מעלת הרגל דוקא, כי ע״י הריקוד ברגלים מתעלה גם הראש — (שיחת מוצאי שבת בראשית תשל״ח ס״ג — לעיל ע׳ 267)."],["29","29","כ״ה בכ״מ בדא״ח (סה״מ ה׳ש״ת ע׳ 61. ובכ״מ). וראה תדבא״ר פי״ד ופל״א. ב״ר פ״א, ד."],["30","30","או״ת ב, ג."],["31","31","ב״ר שם."],["32","32","ב״ר פ״ח, ז. רות רבה פ״ב, ג. וראה המשך ר״ה תש״ג פ״ג. ובכ״מ."],["33","33","ראה ד״ה מים רבים תשל״ח (לעיל ע׳ 278) הערה 44."],["34","34","לקו״א ואו״ת בתחלתן."],["35","35","מג״ע אופן קפו."],["36","36","ראה זח״ג לב, א."]]],[1300201384,"כביכול, מ׳קען גארניט פאנאנדערטיילן וואס איז עצמות און וואס איז ישראל, ווארום דאס איז „בלחודוהי”, עס ווערט איין זאך, כולא חד ממש.\n[עס איז דא דער ארט פון „הי׳ הוא ושמו בלבד”³⁷ — וואס אין דערויף זיינען דא חילוקי דרגות פון „הוא” און „שמו”, און דערנאך (דארף זיין —) איז דא די באוארעניש פון „בלבד”: אבער „ישראל ומלכא בלחודוהי” איז אין אן אופן אז עס ווערט איין זאך ממש].\nח. וויבאלד אז בשמח״ת שטייט א איד אין א שמחה וואס איז למעלה מכל מדידה והגבלה, דערפאר וואס דעמולט שטייט ער אין דעם אופן ווי ער איז מושרש למעלה — איז פארשטאנדיק, אז דעמולט איז ניט שייך צו מחלק זיין צווישן די צוויי ענינים פון „טוב לשמים” און „טוב לבריות”³⁸, ווארום וויבאלד ער שטייט אין א שמחה שלמעלה ממדידה והגבלה, זיינען ביי אים אלע ענינים בהשוואה, ובמילא זיינען „שמים” און „בריות” ניט קיין צוויי באזונדערע זאכן.\nדי כוונה איז דאך אבער אז דער „טוב לשמים” מיטן „טוב לבריות” זאלן ביי אים שטיין צוזאמען (ניט נאר ווען ער שטייט אין א תנועה שלמעלה ממדידה והגבלה, אזוי ווי דאס איז בשמח״ת, נאר) אויך אין דעם זמן ומצב פון „ויעקב הלך לדרכו”, ווען ער דארף אויפטאן אין עוה״ז התחתון שאין למטה ממנו — אז דארטן זאל עבודתו בפועל זיין לויטן אויפטו פון יום השלישי, „טוב לשמים וטוב לבריות” צוזאמען.\nאון צוליב דערויף דארף זיין דער ענין פון „עיניו למטה ולבו למעלה”³⁹:\nווען ער שטייט למעלה ביז אין תכלית השלימות, ווי דער מעמד ומצב פון שמח״ת אז ער שטייט למעלה מכל מדידה והגבלה — איז אויב ער וועט דעמולט ניט האבן קיין פארבונד מיטן מטה, ווייסט מען ניט ווי ער וועט זיך פירן ווען ער וועט אראפקומען אין מטה,\nאון דערפאר איז זייענדיק למעלה דארף זיין „עיניו למטה”, ד.ה. אז די אורות דארפן זיין פארבונדן מיט די כלים, און דער מטה דארף ניט זיין מושלל בא אים — וואס דעמולט נעמט ער מיט די תנועה שלמעלה ממדידה והגבלה אין דער עבודה פון „ויעקב הלך לדרכו”, אז אויך ווען ער פארנעמט זיך מיט עניני עוה״ז הגשמי והחומרי, זאל ער שטיין אין אן אופן שלמעלה ממדידה והגבלה.\nט. און דאס איז מודגש אין קביעות שנה זו, אז דער (עיקר ושלימות ה)ענין פון „ויעקב הלך לדרכו” הויבט זיך אן ביום השלישי:\nדער ענין פון „ויעקב הלך לדרכו” קומט אלס המשך צו שמח״ת (דער סיום וחותם פון די ימים טובים פון חודש תשרי), ד.ה. אז פון שמח״ת גייט מען",[["37","37","פדר״א פ״ג."],["38","38","הענין ד„שמים” ו„בריות” ישנו גם [?] כפי שנש״י נמצאים במעמד ומצב ד„ישראל ומלכא בלחודוהי”: „שמים” — עצמותו ומהותו ית׳ [והרי „שמים” הוא לשון שבועה (ראה ברכות נג, ב. ובכ״מ), ושבועה קשורה עם עצמותו ומהותו ית׳ (ראה לקו״ת שמע״צ פג, ג. ובכ״מ)], ו„בריות” — ישראל. אבל אז א״א לחלק בין „שמים” ו„בריות”, כי „ישראל ומלכא בלחודוהי”. וענין זה הוא מצד „נמנע הנמנעות” — שישנה מציאותם של ישראל, ואעפ״כ „ישראל ומלכא בלחודוהי”, (ר״ל) כולא חד ממש."],["39","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380812\" data-slug=\"likkutei-torah\" data-id=\"4001380812\">יבמות קה, ב</a>. וראה לקו״ת ראה כד, א."]]],[1300201385,"אריין אין אזוינע ימי המעשה וואס התחלתם איז ביום השלישי שהוכפל בו כי טוב, „טוב לשמים וטוב לבריות”.\nוואס אין דערויף איז מודגש אז מ׳נעמט מיט פון שמח״ת די תנועה פון שטיין למעלה ממדידה והגבלה — אין דער עבודה פון „ויעקב הלך לדרכו”,\nאויך ווען ער פארנעמט זיך מיט עניני עוה״ז זאל ער שטיין למעלה ממדידה והגבלה, (ביז) ווי עס דריקט זיך אויס אין דעם ענין פון יום השלישי, אז „טוב לשמים” און „טוב לבריות” ווערן איין זאך.\nאון דורך דעם וואס די עבודה פון אידן איז למעלה ממדידה והגבלה, ווערט די גאולה האמיתית פון אלע מדידות והגבלות,\nביז צו דער גאולה האמיתית והשלימה ע״י משיח צדקנו, אז עס ווערט דער „קץ שם לחושך”⁴⁰, און „שמחת עולם על ראשם”⁴¹, בביאת משיח צדקנו בקרוב ממש.\n• • •\nי. האמור לעיל וועגן דעם ענין פון „טוב לשמים וטוב לבריות” איז אויך פארבונדן מיט דעם שיעור חומש פון היינטיקן טאג — יום ג׳ דפ׳ נח:\nאין דעם שיעור חומש פון היינטיקן טאג שטייט⁴²: „ויזכור אלקים את נח ואת כל החי׳ ואת כל הבהמה אשר אתו בתיבה וגו׳”.\nשטייט אויף דערויף אין מדרש⁴³, אז דער „ויזכור אלקים את נח ואת כל החי׳ ואת כל הבהמה”, איז פארבונדן מיטן פסוק⁴⁴ „אדם ובהמה תושיע ה׳”, אז „תשועת השי״ת הי׳ בשביל כולם”⁴⁵ — הדגשת הענין פון „טוב לשמים וטוב לבריות”:\n„נח איש צדיק”⁴⁶ איז פארבונדן מיט „שמים”, און „כל החי׳ גו׳ כל הבהמה” זיינען „בריות”, און מ׳פארגלייכט ביידן זאגנדיק „ויזכור אלקים את נח ואת כל החי׳ ואת כל הבהמה”, „אדם ובהמה (בשוה⁴⁷) תושיע ה׳”.\nיא. והביאור בזה:\nדער ענין פון „ויזכור אלקים את נח גו׳”, איז געווען א הקדמה צו דעם כריתת ברית פון דעם אויבערשטן מיט נח אז „לא יהי׳ עוד מבול לשחת הארץ”⁴⁸.\nבנוגע צו כללות הענין פון דעם כריתת ברית, איז מבואר בכ״מ⁴⁹ אז עס איז דא דער כריתת ברית מיט נח, דער כריתת ברית מיט אברהם אבינו⁵⁰, און דער כריתת ברית מיט משה רבינו⁵¹:\nדער כריתת ברית מיט נח איז „על השפעת חיות העולמות שלא יופסק ולא יתבטל לעולם”⁵², „לא ישבותו”⁵³, וואס דאס (נעמט זיך פון יחוד חיצוני דאו״א, וואס) איז פארבונדן מיט חיצוניות העולם;",[["40","40","איוב כח, ג."],["41","41","ישעי׳ לה, י. נא, יא."],["42","42","פרשתנו ח, א."],["43","43","פל״ג, א."],["44","44","תהלים לו, ז."],["45","45","מת״כ שם (בסופו)."],["46","46","פרשתנו ו, ט."],["47","47","ראה לקמן הערה 65."],["48","48","פרשתנו ט, יא."],["49","49","אוה״ת תשא ע׳ ב״ז ואילך. ד״ה הנה אנכי כורת ברית תרנ״ד. המשך תער״ב פרק רא (ח״א ע׳ תז ואילך)."],["50","50","לך לך טו, יח."],["51","51","תשא לד, י."],["52","52","אוה״ת שם ע׳ ב״ח."],["53","53","פרשתנו ח, כב."]]],[1300201386,"דער כריתת ברית מיט אברהם אבינו איז פארבונדן מיט תומ״צ⁵⁴ [ביי אברהם אבינו איז שוין געווען דער ענין פון מצות מילה, וואס דאס האט אויפגעטאן דער חיבור פון מעלה מיטן מטה, אז ס׳זאל זיין קדושת חפצא אין א דבר גשמי⁵⁵], וואס דאס איז (און נעמט זיך פון יחוד פנימי דאו״א) המשכת אלקות בעולם:\nאון דער כריתת ברית מיט משה רבינו איז אויף דעם ענין התשובה, (כמובן גם מפשטות הענין — תיקון חטא העגל), וואס תשובה איז „העכער” פון תומ״צ, ביז אז זי איז ממלא דעם חסרון וואס איז געווען אין די ענינים פון תומ״צ⁵⁶, און דאס איז פארבונדן מיט די י״ג מדה״ר וועלכע זיינען „העכער” פון תומ״צ⁵⁷.\nיב. אין דערויף איז אבער צריך ביאור:\nעס איז מבואר אין לקו״ת⁵⁸ אז דער ענין פון כריתת ברית איז „כמו למשל שני אוהבים שכורתים ברית ביניהם שלא תפסוק אהבתם .. שעושין ביניהם קשר אמיץ וחזק שיתייחדו ויתקשרו באהבתם בקשר נפלא ולמעלה מן הטעם והדעת .. כאילו נעשו לבשר אחד .. כמ״ש⁵⁹ אשר כרתו את העגל ויעברו בין בתריו כלומר להיות שניהם עוברים בתוך גוף אחד להיות לאחדים”.\nאיז לכאורה ניט פארשטאנדיק — ווי האט געקענט זיין דער ענין פון כריתת ברית מיט נח:\nעס איז דאך געווען קודם מ״ת, ווען ס׳איז נאך געווען די גזירה פון „עליונים לא ירדו לתחתונים וכו׳”⁶⁰, און עס איז נאך אפילו ניט געווען דער חיבור פון מעלה מיטן מטה אין דעם אופן ווי עס האט זיך אויפגעטאן דורך מצות מילה⁶¹ —\nאיז ווי האט דעמולט געקענט זיין דער ענין פון כריתת ברית מיטן אויבערשטן אין אן אופן „שיתייחדו ויתקשרו באהבתם בקשר נפלא .. להיות שניהם עוברים בתוך גוף אחד להיות לאחדים”?\nנאכמער: דער פסוק „ויזכור אלקים את נח וגו׳” (וואס דאס האט דערנאך געבראכט דעם כריתת ברית מיט נח) זאגט מען בר״ה אין די פסוקי זכרונות, און אין דערויף הענגט אפ די המשכה פון עצמות ומהות⁶² אין פנימיות העולמות (און דורך דערויף אויך אין חיצוניות העולמות)?!",[["54","54","ראה אוה״ת שם: שיכולו להמשיך גילוי אלקות למטה. וראה המשך תער״ב שם (ע׳ תח): שזה (קיום התומ״צ) יהי׳ תופס מקום. ולכן הכרי״ב דאברהם היא „לזרעך נתתי את הארץ הזאת” — שבנ״י יהיו בבחי׳ ארץ, כמ״ש (מלאכי ג, יב) כי תהיו אתם ארץ חפץ .. כ׳ מצוות נקראים בשם זריעה .. צריך לזה ארץ .. וכבו״כ נש״י נקראים ארץ .. שע״י יצמח החפץ ורצון העליון” (אוה״ת שם)."],["55","55","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011041\" data-slug=\"likkutei-sichot\" data-id=\"1300011041\">לקו״ש ח״א ע׳ 41</a>. ח״ג ע׳ 758 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051091\" data-slug=\"likkutei-sichot\" data-id=\"1300051091\">ח״ה ע׳ 79</a> ואילך. ע׳ 88 ואילך."],["56","56","ראה לקו״ת אחרי כו, ריש ע״ד. דרמ״צ מצות וידוי ותשובה."],["57","57","ראה אוה״ת שם (ע׳ ב״ס): וזה נמשך ממקום עליון יותר דהיינו מבחי׳ יגמהי״ר שהם מעק״ר. וראה המשך תער״ב שם: שיעורר בבחי׳ פנימיות ועצמות א״ס ב״ה."],["58","58","נצבים מד, ב. וראה גם מקומות שנסמנו בהערה 49."],["59","59","ירמי׳ לד, יח (בשינוי לשון)."],["60","60","שמו״ר פי״ב, ג. תנחומא וארא טו."],["61","61","דהרי גם הקדושה דמצות מילה לא נקבעה בהגשמי (בבשרכם של גוף האדם הנימול) ממש כמו לאחרי מ״ת (ראה פיה״מ להרמב״ם חולין ספ״ז. — נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051092\" data-slug=\"likkutei-sichot\" data-id=\"1300051092\">לקו״ש ח״ה ע׳ 80</a> הע׳ 26. ע׳ 89 הע׳ 22־24)."],["62","62","ראה סידור ד״ה להבין ענין תק״ש ע״פ כוונת הבעש״ט ז״ל (רמו, ג)."]]],[1300201387,"יג. איז דער ביאור בזה — אז היא הנותנת:\nוויבאלד אז דעמולט איז נאך ניט געווען דער ענין פון תומ״צ, איז פארשטאנדיק אז דער ענין פון „ויזכור אלקים את נח וגו׳” איז געווען פון ארט וואס איז העכער פון תומ״צ.\nד.ה. אז דער „ויזכור אלקים את נח וגו׳” איז געווען „מצד האהבה פנימית והעצמית .. מצד עצם מעלת נש״י”⁶³, וואס נש״י זיינען נאך העכער פון תומ״צ, ווי ער זאגט אין תנא דבי אליהו⁶⁴,\nאון פון דארטן קומט דאס אראפ למטה מטה ביותר — אז ס׳זאל זיין דער כריתת ברית אויפן קיום פון חיצוניות העולם,\nבדוגמא ווי דאס איז בנוגע צו דער המשכה פון ר״ה, אז מ׳איז ממשיך פון עצמות ומהות אין (פנימיות העולמות, און דורך דערויף קומט דאס אויך אראפ אין) חיצוניות העולמות⁶².\nיד. עפ״ז איז פארשטאנדיק דער קשר פון „ויזכור אלקים את נח וגו׳”, מיט דעם ענין פון „טוב לשמים וטוב לבריות”:\nדער ענין פון „ויזכור אלקים את נח וגו׳” איז מצד די אהבה פנימית ועצמית וואס איז פארבונדן מיט עצם מעלת נש״י, ווי זיי שטייען העכער פון תומ״צ.\nוואס די אהבה פנימית ועצמית צו נש״י דערגרייכט אין אן ארט וואס איז העכער פון די חילוקי דרגות פון „אדם” און „בהמה”⁶⁵,\n[און אין עבודת האדם איז עס דער ענין פון עבודת התשובה⁶³, כמרז״ל⁶⁶ „בני אדם שהן ערומין בדעת ומשימין עצמן כבהמה”, וואס עבודת התשובה איז העכער פון תומ״צ⁶⁷],\nאון פון דארטן ווערט נמשך דער ענין פון „אדם ובהמה תושיע ה׳” — אז פון די פנימיות שבפנימיות זאל עס אראפקומען למטה מטה, אז ס׳זאל זיין דער „ויזכור אלקים את נח ואת כל החי׳ ואת כל הבהמה”, „טוב לשמים וטוב לבריות” בהשוואה.\nטו. דער ענין פון „ויזכור אלקים את נח וגו׳”, איז אויך פארבונדן מיט שמח״ת. והביאור בזה:\nעס שטייט אין מדרש⁶⁸ אויפן פסוק „ויזכור אלקים את נח וגו׳” — „ומה זכירה היתה שם, ביאת ישראל להר סיני לקבל התורה, לפי שבסוף חודש אייר שלמו ארבעים יום של ירידת גשמים וק״נ של תגבורת המים”.\nאון לויט דעם קס״ד וואס ווערט געבראכט בכ״מ אויך אין תורת החסידות⁶⁹ אז שמח״ת האט געדארפט זיין אין „זמן מתן תורתנו” [וואס א קס״ד אין תורה איז אויך תורה⁷⁰], איז פארשטאנ־",[["63","63","המשך תער״ב שם."],["64","64","ראה לעיל הערה 29."],["65","65","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380259\" data-slug=\"likkutei-torah\" data-id=\"4001380259\">לקו״ת בהר מב, ד</a>: לגבי בחי׳ סוכ״ע שמקיף על כולן בהשוואה אז הרי כולן שוין כי בבחי׳ סובב נאמר אדם ובהמה תושיע ה׳ בהשוואה א׳. וראה אוה״ת נח (הוספות לכרך ב) תלט, ב."],["66","66","חולין ה, ב. וראה ויק״ר פכ״ז, א: אמרו ישראל רבש״ע כאדם אנחנו כבהמה תושיענו לפי שאנו נמשכין אחריך כבהמה."],["67","67","ראה אוה״ת נח שם: וזהו בחי׳ בהמה רבה שלמעלה מבחי׳ אדם. וראה המשך תער״ב שם: וידוע דאדם ובהמה זהו שלמעלה מתומ״צ שהן בחי׳ אדם כו׳."],["68","68","אגדת בראשית עה״פ."],["69","69","אוה״ת שמע״צ ע׳ א׳תשעט ואילך. רד״ה ביוהשמע״צ תרנ״ט, תרס״ז, תרפ״ז, תרצ״ט, תש״ו, תש״ס. ועוד."],["70","70","ראה פתגם כ״ק מו״ח אדמו״ר בנדר״ד — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011116\" data-slug=\"likkutei-sichot\" data-id=\"1300011116\">לקו״ש ח״א ע׳ 116</a>."]]],[1300201388,"דיק דער קשר צווישן דעם ענין פון „ויזכור אלקים את נח וגו׳” מיט דעם ענין פון שמח״ת.\nטז. והמעשה הוא העיקר⁷¹ — אז מ׳זאל מוסיף זיין אין לימוד התורה, נגלה און חסידות, בהתמדה ושקידה, ומתוך שמחה,\nוואס די שמחה וועט פורץ זיין⁷² די מדידות והגבלות וואס זיינען דא ביי אים, און אויך די מדידות והגבלות וואס זיינען דא אין וועלט, ביז אז ער וועט ווערן דער בעה״ב אויף וועלט,\nוכמרז״ל⁷³ „כל השונה הלכות בכל יום כו׳ הליכות עולם לו⁷⁴ א״ת הליכות אלא הלכות”, ד.ה. אז דורך דעם וואס ער איז „שונה הלכות” ווערט דער „הליכות עולם — לו”, די הנהגה פון וועלט („הליכות עולם”) געהערט צו אים („לו”), ער איז דארטן דער בעה״ב, „מאן מלכי רבנן”⁷⁵.\nאון דעמולט ווערט דער אמת׳ער שלום בעולם, ווארום „ה׳ עוז לעמו יתן („אין עוז אלא תורה”⁷⁶) ה׳ יברך את עמו בשלום”⁷⁷,\nאז „ונתתי שלום בארץ ושכבתם ואין מחריד”⁷⁸, דערפאר וואס „והייתי לכם לאלקים ואתם תהיו לי לעם”⁷⁹, ביז „ואולך אתכם קוממיות”⁸⁰.\nיז. די הוספה אין לימוד התורה, „מבצע תורה”, איז אויך פארבונדן מיט א הוספה אין אלע „מבצעים”, וויבאלד אז אלע „מבצעים” זיינען פארבונדן מיט „מבצע תורה”:\n„מבצע אהבת ישראל” — וואס אהבת ישראל איז א „כלל גדול בתורה”⁸¹,\n„מבצע חינוך” — (דעיקרו) „ושננתם לבניך”⁸², וואס דאס איז א מ״ע מה״ת וועלכע מ׳דערמאנט אין ק״ש⁸³ (סיי אין פרשה ראשונה און סיי אין פרשה שני׳⁸⁴) פעמיים בכל יום,\n„מבצע תפילין” — וואס „הוקשה כל התורה כולה לתפילין”⁸⁵, ווי מ׳לערנט אפ פון דעם פסוק⁸⁶ „למען תהי׳ תורת ה׳ בפיך”,\n„מבצע מזוזה” — ווי דער מיטעלער רבי בריינגט אראפ בסידורו⁸⁷ אז זי איז שקולה כנגד כל המצוות שבתורה — ל׳ הוראה,\n„מבצע צדקה” — וואס „שקולה כנגד כל המצוות”⁸⁸ שבתורה — ל׳ הוראה, און „מקרבת את הגאולה”⁸⁹,\n„בית מלא ספרים — יבנה וחכמי׳” — וואס איז פארבונדן מיט „מבצע תורה”,\n„מבצע נרות שבת קודש” — פארבונדן מיט „נר מצוה ותורה אור”⁹⁰,",[["71","71","אבות פ״א מי״ז."],["72","72","ראה בארוכה ד״ה שמח תשמח תרנ״ז ע׳ 49 ואילך."],["73","73","מסכת נדה בסופה."],["74","74","חבקוק ג, ו. וכידוע (של״ה תג, ב) דדרשות „אל תקרי” היינו ששתי ה„תקרי” קיימות."],["75","75","ראה גיטין סב, סע״א."],["76","76","שהש״ר פ״ב, ג [ג]. ועוד."],["77","77","תהלים כט, יא."],["78","78","בחוקותי כו, ו."],["79","79","שם, יב."],["80","80","שם, יג."],["81","81","תו״כ ופרש״י עה״פ קדושים יט, יח."],["82","82","ואתחנן ו, ז. וראה ספרי ופרש״י עה״פ. רמב״ם הל׳ ת״ת פ״א ה״ב. הל׳ ת״ת לאדה״ז פ״א ס״ח."],["83","83","דענינה גם ת״ת — „זה שינון וזה שינון” (ירושלמי ברכות פ״א סה״ב. שבת פ״א סה״ב)."],["84","84","עקב יא, יט: ולמדתם אותם את בניכם גו׳."],["85","85","קידושין לה, א."],["86","86","בא יג, ט."],["87","87","ערה, א."],["88","88","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">ב״ב ט, א</a>. וראה תניא פל״ז (מח, ב ואילך)."],["89","89","שם י, א. תניא שם."],["90","90","משלי ו, כג. פרש״י ד״ה בנים — שבת כג, ב."]]],[1300201389,"„מבצע כשרות האכילה ושתי׳” — וועלכע זיינען פארבונדן מיטן פנימית׳דיקן לחם און מזון פון א אידן — תורה, ווי עס שטייט⁹¹ „ותורתך בתוך מעי”,\nאון „מבצע טהרת המשפחה” — „מעין ובור מקוה, מים”⁹², וועלכע זיינען פארבונדן מיט „אין מים אלא תורה”⁹³, תורה איז מטהר ומזכך, עס דארף אבער אראפקומען אין א דבר גשמי (אזוי ווי אלע מצוות) — אין מים כפשוטם, און אין דער מדידה והגבלה פון ארבעים⁹⁴ סאה⁹⁵.\nובקרוב ממש וועט דאס בריינגען צום קיום היעוד⁹⁶ „וזרקתי עליכם מים טהורים וטהרתם”, בגאולה האמיתית והשלימה ע״י משיח צדקנו, בקרוב ממש, למטה מעשרה טפחים, ובעגלא דידן.\n• • •\nחי. אזוי ווי מ׳גייט ארויס פון חודש תשרי און פון די טעג פון ר״ח — אין ימי המעשה,\nוואס דעמולט איז דאך אויך דא דער ציווי פון „עבדו את ה׳ בשמחה”⁹⁷, און כולל אויך אין „כל מעשיך יהיו לשם שמים” און „בכל דרכיך דעהו”⁹⁸,\nהאט מען די נתינת כח און די הבטחה אז „בשמחה תצאו ובשלום תובלון ההרים והגבעות יפצחו לפניכם רינה וכל עצי השדה ימחאו כף”⁹⁹,\nכן תהי׳ לנו — א שנה של שמחה, שמחה גלוי׳ ונראית למטה מעשרה טפחים.",[["91","91","תהלים מ, ט. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ״ה</a>."],["92","92","לשון הכתוב — שמיני יא, לו."],["93","93","ב״ק יז, א."],["94","94","יום — שהתורה ניתנה למ׳ יום דוקא, תרומה — תורה מ׳ (זח״ג קעס, א)."],["95","95","להעיר מהמבואר בתו״א ריש פרשתנו ש„המבול בא בכדי לטהר את כל הארץ”, והוא „כדוגמת המקוה מ׳ סאה שהיא מטהרת כו׳”."],["96","96","יחזקאל לו, כה."],["97","97","תהלים ק, ב."],["98","98","אבות פ״ב מי״ב. משלי ג, ו. וראה רמב״ם הל׳ דעות ספ״ג. טושו״ע או״ח סרל״א. שו״ע אדה״ז או״ח סקנ״ו ס״ב."],["99","99","ישעי׳ נה, יב."]]],[1300201390,"משיחת מוצאי ש״פ נח, אור לז׳ מרחשון ה׳תש״מ\nא. בהמשך להמדובר לעיל¹ אז שלימות הענין פון „ויעקב הלך לדרכו״ איז ווען מ׳גייט אריין אין ימי המעשה פון חודש חשון,\n[וואַרום דער „ויעקב הלך לדרכו״ וואס הויבט זיך אן במוצאי יוהכ״פ איז (בעיקר) בנוגע צו המשכת אלקות מלמעלה למטה, און דערנאך זיינען „כל ישראל עסוקין במצוות״, לאחרי שמח״ת קומט דער טאג פון „אסרו חג״, און אויך דערנאך זאגט מען ניט קיין תחנון ביז סיום חודש תשרי — און ערשט לאחרי ר״ח חשון הויבן זיך אן די ימי המעשה אין פולן זין],\nקומט צו נאך א שלימות בזה — אין דער וואך (ובסיומה — מוצאי שבת) פ׳ נח:\nדי וואך פון פ׳ בראשית איז ניט קיין גאנצע וואך פון ימי המעשה, ווייל אלע־מאל² איז זי כולל דעם טאג שמח״ת עכ״פ (— ווי אין קביעות שנה זו — ביום הראשון),\nדער אויפטו פון דער וואך פון פ׳ נח איז — אז אלע טעג פון דער וואך זיינען ימי המעשה³, אין וועלכע מ׳פארנעמט זיך מיט „עובדין דחול״⁴.\nאון וויבאלד אז „כל יומא ויומא עביד עבידתי׳״⁵, איז פארשטאנדיק, אז תכלית השלימות פון „ויעקב הלך לדרכו״ איז — נאך דערויף וואס עס גייט דורך א גאנצע וואך⁶, וואס אלע טעג פון דער וואך זיינען געווען ימי המעשה — וואס דאס איז במוצאי ש״פ נח⁷.\nב. און אין דער עבודה פון „ויעקב הלך לדרכו״ האט מען אויך (כההמשך בכתוב) דעם ענין פון „ויפגעו בו מלאכי אלקים״⁸, וואס דאס איז דער כללות הענין אז „הקב״ה עוזרו״⁹,\nאון אין אן אופן פון „מחניים״¹⁰, ווי רש״י טייטשט אפ „שתי מחנות, של חוצה לארץ .. ושל ארץ ישראל״:\nאין עבודת האדם זיינען דא צוויי אופנים: א) אן עבודה פון תורה ומצוות — אין וועלכע עס איז קדושה (וואס איר מקור איז — אלקות) בגלוי, בדוגמת ארץ ישראל, „ארץ אשר גו׳ תמיד עיני ה׳ אלקיך בה מרשית השנה ועד אחרית שנה״¹¹, ב) אן עבודה פון כל מעשיך לשם שמים ובכל דרכיך דעהו — אין וועלכע די קדושה (אלקות) איז ניט בגלוי — בדוגמת חוץ לארץ (עס איז ניט",[["1","1","בשיחת אור ליום ג׳, ב׳ מרחשון שנה זו (לעיל ע׳ 367 ואילך). וש״נ."],["2","2","בחו״ל, משא״כ באה״ק שבקביעות כבשנה זו — שבוע דפ׳ בראשית הוא בן ז׳ ימים שלימים."],["3","3","ואף שר״ח חשון (שהוא בשבוע דפ׳ נח) אינו „יום המעשה״ (ראה לעיל שם ע׳ 368 ובהערה 15) — הרי מותר הוא בעשיית מלאכה, ואינו בדרגת יום טוב."],["4","4","ראה גם שיחת מוצאי ש״פ נח תשל״ח (לעיל ע׳ 282) ס״ב."],["5","5","זח״ג צד, ב."],["6","6","דההיקף של שבעת ימי השבוע כולל כל משך הזמן (ד״ה ויהי ביום השמיני תש״ד פ״י. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו״ת שה״ש כה, א</a>)."],["7","7","ולהעיר שהענין ד„מים רבים לא יוכלו לכבות את האהבה״ — ש„מים רבים״ קאי על „טרדות הפרנסה״, עובדין דחול — מבואר בדרושי רבותינו נשיאינו (בעיקר) דפ׳ נח."],["8","8","וישלח לב, ב."],["9","9","קידושין ל, ב. וראה סוכה נב, ריש ע״ב."],["10","10","ויצא שם, ג."],["11","11","עקב יא, יב."]]],[1300201391,"חוץ פון דעם „ארט״ וואו מ׳זעט בגלוי אז „עיני ה׳ אלקיך בה מרשית השנה ועד אחרית שנה״).\nאון א איד האט דעם „ויפגעו בו מלאכי אלקים״, „מחניים״, סיי די מלאכים „של חוצה לארץ״ און סיי די מלאכים „של ארץ ישראל״ — „הקב״ה עוזרו״ אין ביידע אופני עבודה הנ״ל.\nאון דורך דעם פירט ער אויס שליחותו של הקב״ה — לעשות לו ית׳ דירה בתחתונים.\nג. האמור לעיל איז נרמז במוצאי ש״פ נח בכל שנה ושנה, עס קומט אבער צו א הוראה נוספת וואס מ׳לערנט אפ פון דער קביעות פון מוצאי ש״פ נח אין ימי החודש בשנה זו:\nדי קביעות פון מוצאי ש״פ נח בשנה זו איז — אין שבעה בחשון.\nדער ענין המיוחד פון שבעה בחשון איז — ווי די משנה¹² זאגט אז „שואלין את הגשמים״ פון שבעה בחשון אן, „ט״ו יום אחר החג, כדי שיגיע אחרון שבישראל לנהר פרת״.\nדערפון איז פארשטאנדיק¹³, אז ביז שבעה בחשון איז עס נאך אלץ דער המשך פון (דער עלי׳ ל)רגל דחגה״ס, וואַרום ערשט דעמולט איז דער „אחרון שבישראל״ צוריקגעקומען פון ירושלים לביתו באַ „נהר פרת״, קצה ארץ ישראל.\nועפ״ז קומט אויס אז תכלית השלימות פון „ויעקב הלך לדרכו״ איז בשבעה בחשון — דעמולט ענדיקט זיך דער ענין פון עלי׳ לרגל¹⁴, און עס הויבט זיך\nאן די עבודה מסודרת פון „ויעקב הלך לדרכו״, אין עובדין דחול.\nד. אין דעם וואס מ׳ווארט מיט שאילת גשמים ביז שבעה בחשון, „כדי שיגיע אחרון שבישראל לנהר פרת״ — איז מודגש דער גודל הענין פון אהבת ישראל:\nאלע אידן וואס זיינען געווען אין גאנץ א״י האבן געדארפט האבן גשמים, און אעפ״כ האט מען אפגעהאלטן די שאילת גשמים פון כל עם ישראל ביז דער „אחרון שבישראל״ וועט אנקומען צו „נהר פרת״, כדי אז אין איינציקער איד, „אחרון שבישראל״, זאל דערפון (פון ירידת גשמים) ניט האבן קיין צער זייענדיק בדרך, אפי׳ מערניט ווי אין טאג צער, דער לעצטער טאג וואס ער איז בדרך.\nנאכמער: אויך דער איד וואס איז נאך געווען בדרך האט געדארפט האבן גשמים (צוליב די שדות וכרמים וואס ער האט געהאט במקומו), קען דאך זיין אז אים איז כדאי דער צער וואס ער וועט האבן פון די גשמים בשעת ער גע־פינט זיך בדרך, וויבאלד אז דורך דעם וועט ער באקומען אין דער ברכה פון גשמים¹⁵ כמ״פ ככה —\nאון אעפ״כ, וויבאלד אז באַ דעם „אחרון שבישראל״ וועט די ברכה פון גשמים זיין ניט בשלימותה (דערפאר וואס ער געפינט זיך בדרך), האבן אלע אידן געווארט מיט שאילת גשמים ביז דער „אחרון שבישראל״ וועט אנקומען לביתו באַ „נהר פרת״¹⁶.",[["12","12","תענית י, א. שו״ע (ואדה״ז) או״ח רסקי״ז."],["13","13","ראה גם שיחת יום שמח״ת ש.ז."],["14","14","ראה ש״ך חו״מ סמ״ג סקמ״ז (הובא לקמן בפנים ס״ה), שעד שבעה בחשון „הי׳ דומה להם כאילו הם עדיין בא״י עסוקים בעניני הרגל״."],["15","15","להעיר מס׳ הרמב״ן (עה״פ בחוקותי כו, ד) שהגשמים כוללים את כל הברכות."],["16","16","ראה שו״ע אדה״ז שם: ואף לאחר החורבן היו מתאספים ג״כ מכל הסביבות בירושלים לרגל כמו שעושים גם היום, לפיכך לא בטלו תקנת חכמים שתקנו השאלה בא״י בז׳ במרחשון."]]],[1300201392,"וואס אין דערויף איז מודגש דער ענין פון אהבת ישראל — דער חיבור ואחדות פון איין אידן מיטן צווייטן, ביז אז אלע אידן שטייען „נצבים היום כולכם״¹⁷, „לאחדים כאחד״¹⁸.\nדערפון קומט ארויס די הוראה אין דעם ענין פון „ויעקב הלך לדרכו״, אויף וויפל די עבודה פון א אידן במשך דער גאנצער הליכה — כל השנה כולה, דארף זיין דורכגענומען מיט אהבת ישראל.\nה. די הדגשה בגודל הענין פון אהבת ישראל קומט אויך אראפ אין עובדין דחול (ניט נאר אין דעם ענין התפלה — שאילת גשמים):\nדער ש״ך ברענגט אראפ אין שו״ע חו״מ¹⁹ אז אויב מ׳האט געשריבן אין א שטר (שטר הלואה וכיו״ב — עובדין דחול) „אחר הרגל״, איז די כוונה בזה — „ט״ו יום אחר הרגל״.\nאון דער מקור לזה זאגט ער איז דער־פון וואס די משנה זאגט אז שאילת גשמים הויבט זיך אן „ט״ו יום אחר החג, כדי שיגיע אחרון שבישראל לנהר פרת״, וואס דערפון איז פארשטאנדיק, אז „כל פעם שהיו ישראל עולים לרגל לא היו יכולין להגיע לבתיהם אחר הרגל אלא בט״ו יום, והי׳ דומה להם כאילו הם עדיין בא״י עסוקים בעניני הרגל, כל זמן שלא היו עוברים הנהר הגדול נהר פרת״.\nו. די הוראה דערפון אין דער עבודה פון „ויעקב הלך לדרכו״:\nדער ענין פון אהבת ישראל, וואס איז מודגש אין דעם וואס שאילת גשמים הויבט זיך אן פון שבעה בחשון, „כדי שיגיע אחרון שבישראל לנהר פרת״, דארף אראפקומען אויך אין עובדין דחול, אין שטרות וכיו״ב.\nדער קירוב הלבבות און די אחדות צווישן אידן דארף זיין ניט נאר ווען מ׳געפינט זיך אין בית הכנסת און בית המדרש, אדער ווען מ׳איז בכלל פאר־נומען מיט ענינים פון תומ״צ (וואס דעמולט איז — מאי קמ״ל),\nנאר אויך ווען מ׳פארנעמט זיך בעוב־דין דחול, אין שטרות וכיו״ב, דארף עס זיין דורכגענומען מיט קירוב הלבבות און אחדות צווישן איין אידן מיטן צווייטן, ביז אז אלע אידן שטייען אין אן אופן פון „לאחדים כאחד״²⁰.\nז. און בשעת אידן שטייען אין אן אופן פון אחדות, „לא שניתי״ צווישן איין אידן און א צווייטן, פארבינדט מען זיך מיט „אני ה׳ לא שניתי״²¹, ביז אין אן אופן פון „ישראל ומלכא בלחודוהי״.\nאון דאס קומט אראפ אויך אין חיצוניות העולם, אז „לכל בנ״י הי׳ אור במושבותם״²², נאר זייענדיק אין „מצרים״, אין ענינים פון עוה״ז הגשמי והחומרי.\nאון שטייענדיק במוצאי ש״פ נח, וועט זיין דער ענין פון „נייחא לעליונים״ און „נייחא לתחתונים״²³.",[["17","17","נצבים כט, ט."],["18","18","לקו״ת ר״פ נצבים. וראה לקו״ש ח״ד ע׳ 1141 ואילך."],["19","19","ראה לעיל בהע׳ 14."],["20","20","להעיר מירושלמי נדרים פ״ט ה״ד: הוה מקטע קופד ומחת סכינא לידוי תחזור ותמחי לידי׳ (בתמי׳). וראה סהמ״צ להצ״צ מצות אהבת ישראל פ״א: עצמו ובשרו הוא."],["21","21","מלאכי ג, ו."],["22","22","בא י, כג."],["23","23","ב״ר פ״ל, ה."]]],[1300201393,"און אזוי ווי מוצאי שבת קודש איז דאך פארבונדן מיט דוד מלכא משיחא²⁴, וואס „דוד מלך ישראל חי וקיים״²⁵ אויך אין זמן הגלות, ווי מ׳זאגט דאס (אויך אין זמן הגלות) באַ קידוש לבנה בכל חודש,\nאון מוצאי שבת קודש איז אויך פאר־בונדן מיט אלי׳ הנביא אלי׳ התשבי אלי׳ הגלעדי —\nוועט קומען אלי׳ הנביא און וועט מבשר זיין ביאת משיח צדקנו, צוזאמען דערמיט וואס „והשיב לב אבות על בנים ולב בנים על אבותם״²⁶.\nאון אויך לפנ״ז, ווען מ׳שטייט אין דעם מעמד ומצב פון „אכתי עבדי אחשורוש אנן״²⁷, וועט זיין „ליהודים היתה אורה ושמחה וששון ויקר״²⁸ כן תהי׳ לנו״, ווי מ׳האט ערשט געזאגט אין הבדלה.\nאון עס וועט גלייך זיין דער „מסמך גאולה לגאולה״²⁹, אין אן אופן פון „מיד הן נגאלין״³⁰ — גאולה האמיתית והשלימה ע״י דוד מלכא משיחא, משיח צדקנו, למטה מעשרה טפחים, ובפועל ממש.",[["24","24","כי סעודת „מלוה מלכה״ שעושים במוצאי שבת נקראת „סעודתא דדוד מלכא משיחא״ — סידור האריז״ל (להר״ש מרשקוב) במקומו. פע״ח סוף שער השבת."],["25","25","ר״ה כה, א."],["26","26","מלאכי שם, כד. עדיות בסופה. רמב״ם הל׳ מלכים רפי״ב. — נתבאר בארוכה בשיחת וא״ו תשרי וש״פ האזינו, שבת שובה, שנה זו."],["27","27","מגילה יד, א."],["28","28","אסתר ח, טז."],["29","29","מגילה ו, סע״ב."],["30","30","רמב״ם הל׳ תשובה פ״ז ה״ה."]]],[1300201394,"משיחות ש\"פ לך לך, ח' מרחשון ה'תשמ\"א\nא. צווישן די ענינים המיוחדים וואס אין היינטיקן שבת, איז וואס ער איז אויף מארגן נאך שבעה בחשון — דער טאג אין וועלכן עס האט זיך פארענדיקט דער אומקערן זיך פון דער עלי' לרגל דחג הסוכות¹, ווען יעדערער [אויך דער „אחרון שבישראל\"] האט זיך אומגע־קערט צו זיך א היים און צום געוויינט־ליכן טאג טעגליכן לעבן.\nוואס ניט קוקנדיק אויף דער ירידה — לגבי דעם מצב און מדריגה ווען זיי זיינען געווען אין בית המקדש — אין דעם מצב און מדריגה אין וועלכן אידן זיינען געווען בא זיך אין דער היים [ובפרט דער „אחרון שבישראל\" וואס זיין היים איז געווען באם ברעג פון ארץ ישראל (לעבן נהר פרת), וואס דאס ווייזט אז אויך זיין רוחניות'דיקער מצב איז געווען אין א נידעריקע מדריגה]\n— וואס יעדער מאל ווען א איד האט עולה געווען אין ירושלים, אפילו בימי החול, האט עס אים געברענגט צו א הע־כערע מדריגה². ומכש\"כ בעת די עלי' לרגל לראות „את פני ה' אלקיך\" שלש פעמים בשנה³. ובפרט בחג הסוכות זמן שמחתנו. ועאכו\"כ אין א שנת הקהל, ווען אלע אידן צוזאמען האבן געהערט פון מלך⁴ פרשיות פון תורה ובאופן „כאילו . . מפי הגבורה שומעה\"⁵ —\nאיז זייער גיין פון ביהמ\"ק צו זיך א היים געווען „בשמחה — „וילכו לאהליהם שמחים וטובי לב\"⁶.\nולכאורה איז ניט מובן: ווי קומט עס אז בשעת אידן גייען אוועק פון ביהמ\"ק צו זיך א היים — וואס דאס איז (כנ\"ל) א ירידה גדולה ביותר — זאלן זיי זיין „שמחים וטובי לב\"?\nב. דער ביאור אין דעם:\nדער צוועק פון דעם גיין א היים, וואו יעדערער האט זיך פארנומען מיט זיינע וואכעדיקע און גשמיות'דיקע זאכן, איז געווען בכדי צו מאכן (אויך) פון זיי א משכן און מקדש צום אויבערשטן.\nווי עס שטייט „ושכנתי בתוכם\" לשון רבים⁷, אז דער אויבערשטער רוט ניט נאר אין דעם ביהמ\"ק (כפשוטו), נאר אויך אין יעדער אידן, אין יעדער אידישע הויז און אין אלע גשמיות'דיקע וואכעדיקע זאכן מיט וועלכע א איד פארנעמט זיך אין אן אופן פון „כלי מעשיך יהיו לשם שמים\" און „בכל דרכיך דעהו\"⁸.\nאון אין דעם „ושכנתי בתוכם\" לשון רבים, אין דעם מקדש וואס אידן מאכן פון זייערע וואכעדיקע זאכן, איז דאך דא דער יתרון האור וואס קומט מן",[["6","6","מ\"א ח, סו."],["7","7","תרומה כה, ח. של\"ה (סט, א. ובכ\"מ). ר\"ח שער האהבה פ\"ו קרוב לתחלתו."],["8","8","אבות פ\"ב מי\"ב. משלי ג, ו. וראה רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א. שו\"ע אדה\"ז שם סקנ\"ב."],["9","9","אולי י\"ל דאפילו אם עשאן בסתם — מיד שחוזר ועושה כו' גם הנעשה בסתם מתחבר כו' מאחר שלא נתלבש בו כו' (עיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא ספל\"ט</a> ורפ\"מ)."],["1","1","תענית י, א. שו\"ע אדה\"ז או\"ח ר\"ס קיז."],["2","2","ראה תודה\"ש כי מציון — ב\"ב כא, א."],["3","3","ראה טז, טז."],["4","4","סוטה מא, א. הובא בפרש\"י עה\"פ וילך לא, יא. ובפרטיות — רמב\"ם הל' חגיגה פ\"ג ה\"ג."],["5","5","רמב\"ם שם ה\"י."]]],[1300201395,"החושך (דוקא)¹⁰ — דערפאר איז דער „וילכו לאהליהם\" געווען אין אן אופן פון „שמחים וטובי לב\".\nג. שוין גערעדט פיל מאל, אז ברוח־ניות — איז דער ביהמ\"ק און אלע זיינע ענינים, גאנץ אויך איצטער. דערפון איז מובן, אז האמור לעיל בנוגע צו שבעה בחשון — אז דעמולט האט זיך פאר־ענדיקט דער ענין פון עלי' לרגל (שכולל גם החזרה לביתו) דחג הסוכות — איז עס אויך איצטער בזמן הגלות, און אויך אין חוץ לארץ¹¹.\nא הוכחה אויף דעם: דער טעם אויף דעם וואס שאילת גשמים איצט הויבט מען אן (בא\"י) ערשט בז' חשון, „ט\"ו ימים אחר החג\" (און ניט „מיד אחר החג\") איז — „כדי שיגיע האחרון שבישראל שעלה לרגל לביתו לנהר פרת כו' ולא יעצרנו הגשם\"¹ — און וויבאלד אז אויך בזמן הגלות „מתחילין לשאול בא\"י מליל ז' במרחשון\", איז מוכח¹², אז אויך איצטער איז דא דער ענין העלי' לרגל (ברוחניות), און אז ער פארענדיקט זיך בז' חשון.\nביז אז דערפון קומט ארויס א דין אפילו אין שטרות¹³ — וואס אין שטרות איז נוגע „לשון בני אדם\" (אזוי ווי בא נדרים)¹⁴ — און אפילו אין חוץ לארץ, אז אויב מ'האט געשריבן אין א שטר „אחר הרגל\", איז די כוונה אין דעם — „ט\"ו יום אחר הרגל\", וויילע ביז דאן איז נאך „כאילו . . עסוקים בעניני הרגל\"¹⁵.\nוואס דערפאר איז (ווי גערעדט אמאל בארוכה¹⁶) די עבודה מסודרת פון „ויעקב הלך לדרכו\"¹⁷ — ווען דער איד גייט צו זיין וועג, צו זיינע וואכעדיקע ענינים, די עבודה פון „כל מעשיך יהיו לשם שמים\" און „בכל דרכיך דעהו\" — פאנגט זיך אן (בעיקר ובכל ההיקף) ערשט בשבעה בחשון.\nד. אע\"פ אז דער איבערגאנג פון די „עניני הרגל\" אין עניני חול איז א ירידה גדולה ביותר, איז אבער לויטן כלל אז יעדע ירידה איז צורך עלי', בכדי צוצו־קומען צו א נאך העכערע מדריגה ווי מ'איז געווען לפני הירידה — איז פאר־שטאנדיק, אז די ירידה אין עניני חול (במשך השנה) איז צורך עלי', ווארום דוקא דורך דעם וואס אויך פון עניני חול, נידעריקע ענינים, מאכט מען א דירה צום אויבערשטן, דוקא דורך דעם פירט מען אויס די כוונה פון „נתאוה הקב\"ה להיות לו ית' דירה בתחתו־",[["10","10","קהלת ב, יג. וראה ספר הערכים־חב\"ד ע' אור — ביחס לחושך ס\"ח. וש\"נ."],["11","11","שהרי בנדו\"ד השינוי דזמן שאילת גשמים — אינו נוגע כלל."],["12","12","ועד שגם בפועל, גם „לאחר החורבן היו מתאספים ג\"כ מכל הסביבות בירושלים לרגל, כמו שעושים גם היום\" (שו\"ע אדה\"ז שבהע' 1)."],["13","13","ומזה מוכח, דמה שעד ז' חשון „כאילו . . עסוקים בעניני הרגל\" הוא לא רק בעניני תפלה (שאילת גשמים) אלא גם בעובדין דחול (שטר הלוואה וכיו\"ב)."],["14","14","ראה שו\"ע חו\"מ סמ\"ג סכ\"ח: „כל זמן הכתוב בשטר . . דנים אותו כמו בנדרים\" — ובנדרים „הלך אחר לשון בני אדם\" (נדרים ל, סע\"ב. שו\"ע יו\"ד ר\"ס ריז). וראה גם רמ\"א חו\"מ סמ\"ב ס\"י ובסמ\"ע שם סקכ\"ח (אלא ששם אין זה בנוגע לזמן)."],["15","15","ש\"ך חו\"מ סמ\"ג סקמ\"ז. בש\"ך שם: ואע\"ג דהשתא כו' לשון כו'. אבל עפמ\"ש אדה\"ז בשו\"ע שם (נעתק לעיל הע' 12) — יש לומר, דאין זה רק לשון כו', אלא הענין דעסוקים בעניני הרגל. ומ\"ש בפנים השיחה שזהו גם ב(שטרות דאזלינן אחר) לשון בני אדם — הוא, דהעסק בעניני הרגל נמשך ופועל גם בענינים פשוטים (ראה לעיל הע' 13) ועד בלשון בני אדם."],["16","16","שיחת מוצאי ש\"פ נח, אור לד' מרחשון ה'תש\"מ (לעיל ע' 378)."],["17","17","ל' הכתוב — ויצא לב, ב. וראה שיחה הנ\"ל."]]],[1300201396,"נים\"¹⁸, ביז אין תחתון שאין תחתון למטה ממנו¹⁹.\nאון דעריבער, איז בשעת מען גייט ארויס פון חודש תשרי וואס איז „מרובה במועדות\"²⁰, ביז אז מען גייט ארויס אויך פון די „עניני הרגל\" וואס ציען זיך ביז ז' חשון, און מען גייט אריין אין די „ימי המעשה\" במשך כל השנה, פאר־נעמען זיך מיט עובדין דחול,\nאיז ניט נאר וואס עס דארף ניט גע־מינערט ווערן פון דער שמחה וואס איז געווען אין „זמן שמחתנו\" — און מען דארף מיטנעמען די שמחה של תורה ומצוה (דחג הסוכות שמע\"צ ושמח\"ת) אויף און אין כל השנה²¹ — נאר נאכ־מער: וויבאלד אז איצטער הויבט מען אן די עבודה פון מאכן פון די עניני חול א דירה צום אויבערשטן, דארף מען נאך מוסיף זיין אין שמחה, מצד דערויף וואס מען האט זוכה געווען צו ווערן א שליח פון אויבערשטן²² צו מאכן פאר אים א דירה בתחתונים — בדוגמת דער „וילכו לאהליהם\" (וואס האט זיך פארענדיקט בז' חשון) וואס איז געווען אין אן אופן פון „שמחים וטובי לב\".\nה. ענין הנ\"ל אז דער „ויעקב הלך לדרכו\" דארף זיין בשמחה²³ — איז פארבונדן אויך מיט דער הדגשה אין „ויעקב הלך לדרכו\"²⁴, אז א איד („יעקב\") דארף האלטן אין א שטענדיקן „גייך\" און עולה זיין העכער און העכער — „מעלין בקודש\"²⁵,\nאון נאכמער: דער „מעלין בקודש\" דארף זיין אין אן אופן חדש לגמרי, וואס איז העכער באין ערוך פון דעם אופן העבודה וואס איז געווען ביז איצטער (וואס דוקא דאן איז עס א הליכה אמיתית, כמבואר בכ\"מ²⁶).\nוואס דאס איז אויך מודגש במיוחד אין שבת פרשת לך לך, וואס ענינה פון דער סדרה איז כשמה — לך לך,\nאון ווי דער פסוק טייטשט גלייך אפ: דער „לך\" דארף זיין שלא בערך „מארצך וממולדתך ומבית אביך\" — אפילו ווי זיי זיינען אין קדושה²⁷,\nווארום וויבאלד אז ס'איז „ארצך\", „מולדתך\" און „בית אביך\" (פון דעם מענטשן), זיינען זיי במדידה והגבלה, און דעריבער דארף מען גיין פון זיי. און גיין „אל הארץ אשר אראך\", וואס דער אויבערשטער ווייזט אן — למעלה ממדידה והגבלה.\nאון דאס איז אויך די שייכות מיוחדת פון ענין השמחה מיט „ויעקב הלך לדרכו\": שמחה איז פורץ כל הגדרים²⁸, און דעריבער, ברענגט זי שמחה אין דעם „ויעקב הלך לדרכו\" — עבודה שלמעלה ממדידה והגבלה.",[["18","18","ראה תנחומא נשא טז. בחוקותי ג. במדב\"ר פ\"ג, ו. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["19","19","תניא שם."],["20","20","ב\"י לטור או\"ח סתצ\"ב. שו\"ע אדה\"ז או\"ח סתצ\"ב ס\"ב. וראה גם השלמה לשו\"ע אדה\"ז או\"ח סקל\"א ס\"ח."],["21","21","ראה אוה\"ת סוכות ע' איתסנו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450531\" data-slug=\"or-hatorah-hb\" data-id=\"8316450531\">ברכה ס\"ע איתסס</a> ואילך. ד\"ה צהר תעשה תש\"ב ס\"ג."],["22","22","שזה עצמו — מה שזוכה להיות שליח (עוד לפני שמקיים את השליחות) — הו\"ע נעלה ביותר, כמובן ובפשטות. וראה גם סה\"מ הש\"ת ע' 74."],["23","23","ועי\"ז נעשה „קל ללכת\" (ראה פרש\"י ויצא כט, א)."],["24","24","ראה לעיל ע' 266 ואילך."],["25","25","ברכות כח, א. וש\"נ."],["26","26","ד\"ה צאינה וראינה תר\"ס. המשך תרס\"ז ע' יח. ובכ\"מ."],["27","27","סד\"ה לך לך תש\"ה (סה\"מ תש\"ה ע' 95). וראה לעיל ע' 306־7."],["28","28","ראה המשך שמח תשמח תרנ\"ז ס\"ע 49 ואילך."]]],[1300201397,"ו. א הדגשה מיוחדת אין דער נוי־טיקייט פון „עבדו את ה' בשמחה\"²⁹ איז אין היינטיקער צייט, ווען „החושך יכסה ארץ וערפל לאומים\", אבער צו אידן האט עס ניט — ויתרה מזה „ועליך יזרח ה'\"³⁰, „ה' שומרך ה' צלך על יד ימינך יומם השמש לא יככה וירח בלילה\"³¹\nואדרבה: וויבאלד אז „מלכיות מתג־רות אלו באלו\" אין אזא ווילדן אופן וואס לא הי' לעולמים איז „צפה לרגלו של משיח\"³² —\nאיז דורך שמחה שטארקט מען ביותר דעם בטחון אין דעם אויבערשטן, אז „לא ינום ולא יישן שומר ישראל\"³³, און אין דעם „צפה לרגלו של משיח\" און „אחכה לו בכל יום שיבוא\".\nוואס דאס גופא, דער „אחכה לו בכל יום שיבוא\" — דער בטחון אין דעם אוי־בערשטן, אז גאר אינגיכן וועט ער ברענגען משיח'ן — פארגרעסערט נאכ־מער די שמחה, ביתר שאת וביתר עוז.\nז. אן ענין נוסף אין דעם:\nמען דערציילט אויף איינעם פון די צדיקי פולין ווען ער איז נאך געווען גאר בקטנותו — וואס „בוצין בוצין מקטפי' ידיע\"³⁴ — אז בעת מ'האט פון אים מונע געווען אן עפעל, האט ער געזאגט די ברכה „בורא פרי העץ\", און דורך דעם מכריח געווען צו געבן אים דעם עפעל.\nובנוגע לענינינו: דורך דעם גופא וואס אידן וועלן זיין שמח בשמחת הגאולה, מצד דעם בטחון אז דער אוי־בערשטער וועט ברענגען משיח'ן גאר אינגיכן — איז דאס גופא וועט כביכול ברענגען נאך גיכער (אחישנה) דעם אוי־בערשטן, אבינו שבשמים, צו ממלא זיין משאלות לבבם פון זיינע קינדער.\nח. פשוט אז דאס אלעס איז כלל וכלל ניט דער ענין פון דוחק זיין את הקץ — ווייל דא רעדט זיך ניט וועגן קבלה מעשית, השבעת מלאכים וכיו\"ב,\nנאר — וועגן לערנען תורה ומקיים זיין מצוות בשמחה ובהוספה, כולל אויך ופשיטא —\nטראכטן וועגן פירוש המילות כפשוטו, ווען ער שטייט פארן אוי־בערשטן און בעט ביי אים: ותחזינה עינינו בשובך לציון ברחמים און — את צמח דוד עבדך מהרה תצמיח — און מיינען עס מיט אן אמת.\nאון דאמאלס — וועט ער א פרעג טאן בא זיך אליין: וואס האב איך היינט געטאן אין דעם?\nט. בכדי צו פארבינדן דאס אויבנ־געזאגטע — בנוגע צו „ויעקב הלך לדרכו\" (און „לך לך\"), צו האלטן אין איין מוסיף זיין אין תורה ומצוות, און בנוגע צו „עבדו את ה' בשמחה\" — מיט אן ענין של פועל,\nאיז כאן המקום לעורר נאכאמאל אויף דער הצעה (וואס מען האט מציע געווען אין א פריערדיקער התוועדות³⁵): אז יעדער איינער זאל נעמען אויף זיך, בלי נדר, צו מוסיף זיין בכל יום ויום דימי השנה: אין לימוד התורה, און אין נתינת",[["29","29","תהלים ק, ב. וראה רמב\"ם סוף הל' לולב."],["30","30","ישעי' ס, ב."],["31","31","תהלים קכא, ה־ו."],["32","32","ב\"ר פמ\"ב, ד."],["33","33","תהלים שם, ד."],["34","34","ברכות מח, א."],["35","35","ש\"פ נח, בדר\"ח מרחשון. וראה גם מכ' דעש\"ק פ' לך לך, ד' מ\"ח שנה זו (נדפס לקמן ע' 551)."]]],[1300201398,"הצדקה, וואס זי איז כללות כל המצוות³⁶ [ובערב שבת ויו\"ט — געבן א סכום כפול, אויך פאר שבת ויו\"ט]\nוואס דאס איז פארבונדן אויך מיט שמחה, ווארום תורה איז דאך „פקודי ה' ישרים משמחי לב\"³⁷, און אויך צדקה — דארף זי דאך זיין בשמחה וטוב לבב³⁸.\nיו\"ד. אזוי ווי ס'איז א שנת הקהל, א יאר וועלכער איז מדגיש אז אלע אידן, „האנשים והנשים והטף\"³⁹, זיינען איין קהל — איז מה טוב, אז די הוספה אין לימוד התורה זאל זיין אין ענין פון פרשת השבוע, וואס דאס פאראייניקט אלע אידן,\nאון אז די הוספה אין נתינת הצדקה בכל יום זאל זיין א סכום אין א מספר פון צען — בהתאם צו די צען סוגים פון וועלכע עס שטעלט זיך צוזאמען דער קהל פון אידן⁴⁰.\nויהי רצון, אז די שמחה וואס וועט נתוסף ווערן דורך דער הוספה אין תורה ומצוות, זאל פורץ זיין אויך די גדרי הגלות כפשוטה, אז גאר אינגיכן וועט זיין די גאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.",[["36","36","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380810\" data-slug=\"likkutei-torah\" data-id=\"4001380810\">לקו\"ת ראה כג, ג</a>. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["37","37","תהלים יט, ט. טושו\"ע אורח ר\"ס תקנד."],["38","38","ראה סידור רפא, ד: ובצדקה ובגמ\"ח כתיב ג\"כ (ראה טו, י) לא ירע לבבך בתתך כו' כי צ\"ל השפע והחסד בשמחה וטוב לבב."],["39","39","וילך שם, יב."],["40","40","ר\"ס נצבים. לקו\"ת ר\"ס נצבים (מוח\"ב פב, א). וראה קידושין רפ\"ד „עשרה יוחסין\" ובחדא\"ג שם. ת\"ז בהקדמה: מעשר כו' אתקריאו ישראל מלכים כו' ראשי אלפי ישראל. זרח תיקונים צד, סע\"א."]]],[1300201399,"שיחת ש\"פ וירא, כ\"ף מרחשון – יום הולדת כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע – ה'תש\"מ – הנחה –\nא. די התוועדות איז פארבונדן מיט כ' מרחשון — דער יום ההולדת פון כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע, וואס כ\"ק מו\"ח אדמו\"ר נשיא דורנו איז געווען זיין ממלא מקום, און דערצו איז ער געווען זיין יורש, וואס ער (יורש) איז המוריש עצמו¹, און — בנו יחידו².\nוואס כללות הענין און די מעלה פון יום ההולדת איז נתגלה געווארן דורך כ\"ק מו\"ח אדמו\"ר³, און דערנאך האט ער געהייסן דאס אפדרוקן, כדי אז ס'זאל נתפרסם ווערן פאר אלעמען,\nוארום דער פרסום וואס ווערט אויפגעטאן דורך דפוס איז א פרסום הכי גדול — ניט נאר פאר יחידי סגולה, און ניט נאר פאר א באשטימטן חוג וואס האט באשטימטע מנהגים (צווישן זיי אויך דער מנהג), נאר פאר אלע אידן, און אויך אן ענין וואס בלייבט (און במילא — געהערט) לדורי דורות⁴.\nד.ה. אז במשך פון דער גאנצער צייט האט מען ניט געוואוסט וועגן דער מעלה פון יום ההולדת, ביז אז ס'איז געקומען דער זמן וואס כ\"ק מו\"ח אדמו\"ר האט דאס מגלה געווען.\nאון ווען דאס איז נתגלה געווארן דורך כ\"ק מו\"ח אדמו\"ר — איז עס געווען אין אן אופן פון — מן הקצה אל הקצה:\nאיידער דאס איז נתגלה געווארן, האבן וועגן דעם ניט געוואוסט אפילו יחידי סגולה, נאר — אחדים יחידים; און ווען דאס איז נתגלה געווארן, איז עס נתפרסם געווארן (ניט נאר פאר יחידי סגולה און הקרובים ביותר, נאר) פאר אלע אידן, און אויך — פאר דורות הבאים.\nב. עס זיינען אבער דא אזוינע וואס תואנה הם מבקשים — פרעגן זיי: וואו איז דער מקור אויף דעם ענין פון יום הולדת, לשמחה מה זה עושה⁵, און מה יום מיומים?!\nאויב דאס איז טאקע א דבר נכון וטוב ומוכרח — איז ווי קומט דאס אז במשך פון אלע פריערדיקע דורות האט מען וועגן דערויף ניט געוואוסט?!\nאיז די הסברה בזה — אז מ'געפינט כמה ענינים אין תורה וואס זיינען נתגלה געווארן אין זמנים מסוימים, ד.ה. אז ס'איז געווען א משך זמן וואס מ'האט ניט געוואוסט וועגן דעם ענין, און דערנאך איז געקומען דער זמן וואס דעמולט איז דער ענין נתגלה געווארן.\nוואס אפילו אין תושב\"כ געפינט מען אז ס'זיינען דא כמה ענינים וואס זיינען נתגלה געווארן לאחרי הזמן דמ\"ת, ועאכו\"כ אין תושבע\"פ — די ענינים וואס „תלמיד ותיק עתיד לחדש\"⁶, וואס",[["1","1","ראה ב\"ב קנט, א. שו\"ת צפע\"נ ח\"א סקי\"ח. מילואים יג, א. מהדו\"ת יט, א."],["2","2","יורש הכל, ובמלך — אין צריך משיחה (הוריות יא, ב), כי משיחת אביו היא משיחתו (ראה צפע\"נ להוריות שם)."],["3","3","היום יום ע' מד."],["4","4","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021246\" data-slug=\"likkutei-sichot\" data-id=\"1300021246\">לקו\"ש ח\"ב ע' 522</a>."],["5","5","ל' הכתוב — קהלת ב, ב."],["6","6","נסמן בלקו\"ש חי\"ד ע' 1088 הע' 11."]]],[1300201400,"איידער דער „תלמיד ותיק\" האט דאס מחדש געווען, האט מען דערפון ניט געוואוסט [וארום אע\"פ אז דאס איז טאקע „ניתן למשה מסיני\"⁶, איז עס אבער אן ענין וואס דער „תלמיד ותיק\" איז מגלה און מחדש].\nד.ה. אז ס'איז געווען א צייט וואס דער ענין איז נאך ניט נתגלה געווארן אין תורה, וואס דעמולט איז מען ניט געווען מחוייב בזה, און פשיטא אז אין דערויף איז ניט געווען דער עילוי פון „גדול המצווה⁷ ועושה\"⁸ — ביז אז ס'איז געקומען די צייט וואס דער ענין איז נתגלה געווארן.\nוואס דער ענין איז פארשטאנדיק אפילו בא א „בן חמש למקרא\"⁹, וארום ער זעט אין תושב\"כ אז עס זיינען דא ענינים וואס זיינען נתגלה געווארן לאחר זמן, ועאכו\"כ ווען ער ווערט דערנאך „בן עשר שנים למשנה\"⁹, וואס דעמולט זעט ער דאס בריבוי אין תושבע\"פ, און דערנאך ווען ער ווערט „בן שלש עשרה למצוות\"⁹, וואס דעמולט ווערט ער מחוייב במצוות, זעט ער דאס אויך בנוגע להלכה למעשה בפועל.\nג. עד\"ז געפינט מען אויך בנוגע לכללות כל התורה:\nעס שטייט אין מדרש¹⁰ אז „ראוי הי' אדה\"ר שתנתן תורה על ידו\", נאר „את הכל עשה יפה בעתו\"¹¹, און מ\"ת איז געווען לאחרי כ\"ו דורות.\nוואס לכאורה איז ניט פארשטאנדיק:\nוויבאלד אז „אסתכל באורייתא וברא עלמא\"¹², און די גאנצע וועלט איז באשאפן געווארן „בשביל התורה שנקראת ראשית\"¹³ — האט מ\"ת געדארפט זיין גלייך בתחלת בריאת העולם?\nאון אעפ\"כ זאגט מען אז „את הכל עשה יפה בעתו\", און דער עת פון מ\"ת איז געקומען ערשט לאחרי כ\"ו דורות.\nועד\"ז בנדו\"ד — בנוגע צו דעם ענין פון יום הולדת:\nעס איז געווען א זמן וואס דער ענין פון יום ההולדת איז ניט געווען בגלוי, און דערנאך ווען ס'איז געקומען די צייט אז ס'זאל נתגלה ווערן, האט כ\"ק מו\"ח אדמו\"ר מגלה געווען (ע\"ד ווי דער לשון פון כ\"ק מו\"ח אדמו\"ר בנוגע לכו\"כ ענינים, אז ווען ס'איז געקומען די צייט אז די ענינים זאלן נתגלה ווערן, האט מען זיי מגלה געווען¹⁴).\nוכאמור לעיל אז בכל התורה כולה זיינען דא ענינים וואס זיינען נתגלה געוואָרן ערשט ווען ס'איז געקומען א זמן מסוים, סיי ענינים וואס זיינען מן התורה, ועאכו\"כ ענינים וואס זיינען מדברי סופרים, ועאכו\"כ ענינים וואס זיינען פארבונדן מיט „מנהג ישראל\" —\nאון זכה דורנו זה אז אים איז זיינען נתגלה געווארן כו\"כ ענינים וועלכע מ'האט פריער ניט געוואוסט, וויבאלד אז ס'איז געקומען די צייט אז אלע ענינים דארפן נתגלה ווערן אין אן אופן פון „אחישנה\", ובמילא קען מען דאס ניט אפלייגן אויף אן אנדער זמן,\nעס איז אבער פארשטאנדיק, אז די אלע ענינים גייען אריין אין דעם כלל",[["7","7","הצוותא וחיבור עם ה' המצווה."],["8","8","קידושין לא, א. ושי\"נ."],["9","9","אבות פ\"ה מכ\"ב."],["10","10","ב\"ר פכ\"ד, ה. קה\"ר פ\"ג, יא [ב]."],["11","11","קהלת ג, יא."],["12","12","זח\"ב קסא, ריש ע\"ב."],["13","13","פרש\"י ר\"פ בראשית."],["14","14","ראה סה\"מ תש\"ה ע' 226. לקו\"ש חי\"ד ע' 347 ואילך."]]],[1300201401,"פון „כל מה שתלמיד ותיק עתיד לחדש ניתן למשה מסיני\".\nובפרט בנדו\"ד וואס דער כללות הענין פון יום ההולדת איז „יסודתו בהררי קודש\"¹⁵ — ווי עס שטייט אין ירושלמי¹⁶ אז דעמולט איז מזלו גובר, וואס ירושלמי איז דאך א חלק פון תושבע\"פ, א חלק פון „תורת אמת\", וואס אין איר זיינען ניטא קיין שינויים — ווערט עס א חלק פון „תורת אמת\" וואס נעמט זיך פון דעם אויבערשטן, ביז ווי תורה שטייט אין אן אופן פון „שעשוע המלך בעצמותו\"¹⁷.\n* * *\nד. פון יעדער ענין דארף זיין א הוראה אין עבודת ה' — ועד\"ז בנדו\"ד, אז עס דארף זיין א הוראה פון יום ההולדת פון כ\"ק אדמו\"ר נ\"ע, וכמובן אז די הוראה דארף זיין פארבונדן מיט אן ענין מיוחד השייך לבעל ההולדת.\nווען מ'הויבט אן זוכן ענינו המיוחד פון דעם רבי\"ן נ\"ע, זעט מען אז עס זיינען דא א ריבוי ענינים, ביז אין אן אופן פון אין סוף,\nובמכש\"כ וק\"ו: מה־דאך אז בא יעדער אידן זיינען דא א ריבוי ענינים עד א\"ס, וויבאלד אז יעדער איד איז א נצחי, כמרז\"ל¹⁸ „כל ישראל יש להם חלק לעוה\"ב, שנאמר¹⁹ ועמך כולם צדיקים גו' מעשה ידי להתפאר\", וואס דערפון איז פארשטאנדיק, אז אזוי ווי דער אויבערשטער איז א נצחי, אזוי איז אויך, כביכול, א איד א נצחי, וויבאלד אז ער איז „מעשה ידי\" פון דעם אויבערשטן —\nאיז עאכו\"כ ווען מ'רעדט וועגן איינעם וואס איז געווען א מורם מעם, און אזא וואס כל ימיו איז ער געשטאנען אין דעם מעמד ומצב ווי רשב\"י האט געזאגט „בחד קטירא אתקטרנא בי' בקוב\"ה .. בי' אחידא בי' להיטא בי' אתדבקת\" (כמבואר אין דער אידרא²⁰),\n[וואס ענינו פון רבי\"ן נ\"ע איז געווען — מפרסם זיין תורתו של רשב\"י, פנימיות התורה, ווי ס'איז פארשטאנדיק פון כמה שיחות²¹ אז עיקר הענין פון הפצת פנימיות התורה, האט זיך אנגעהויבן פון רבי\"ן נ\"ע],\nובפרט ווען ער איז געשטאנען אין דעם מעמד ומצב פון „הזית הזה כשכותשין אותו הוא מוציא שמנו\"²² (ע\"ד ווי דער בעל ההולדת שרייבט²³ בנוגע צום אלטן רבי\"ן) — זייענדיק א נשמה בגוף דא למטה, און אין זמן הגלות וואס דעמולט איז „החושך יכסה ארץ\"²⁴, ביז צום חושך כפול ומכופל פון עקבתא דמשיחא — וואס דעמולט האט זיך אויפגעטאן דעם ענין פון „מוציא שמנו\", און ס'איז געווארן דער ריבוי און הפצה פון פנימיות התורה, אין אן אופן פון „יתרון האור מן החושך\" און „יתרון החכמה מן הסכלות\"²⁵ —\nאיז דאך א זיכערע זאך אז ביי אים זיינען דא א ריבוי ענינים, ביז אין אן אופן פון אין סוף.",[["15","15","ל' הכתוב — תהלים פז, א."],["16","16","ר\"ה פ\"ג ה\"ח ובקה\"ע שם."],["17","17","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381237\" data-slug=\"likkutei-torah\" data-id=\"4001381237\">לקו\"ת שה\"ש כז, א</a>."],["18","18","סנהדרין צ, א."],["19","19","ישעי' ס, כא."],["20","20","זח\"ג רפח, א. רצב, א."],["21","21","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071221\" data-slug=\"likkutei-sichot\" data-id=\"1300071221\">לקו\"ש ח\"ז ע' 209</a>. ושי\"נ."],["22","22","ראה מנחות נג, סע\"ב. שמו\"ר ר\"פ תצוה."],["23","23","תו\"ש ע' 26."],["24","24","ישעי' שם, ב."],["25","25","קהלת ב, יג."]]],[1300201402,"ובפרט אז עס רעדט זיך וועגן א נשיא, וואס „הנשיא הוא הכל\"²⁶, און נאכמער — אין יום ההולדת שלו, ווען „מזלו גובר\", וואס דאס ווערט אויפגעטאן בכל שנה ושנה ווען עס קומט דער יום ההולדת, וויבאלד אז „הימים האלה נזכרים ונעשים\"²⁷ —\nאיז דאך פארשטאנדיק, אז ביי אים זיינען דא א ריבוי ענינים, ביז אין אן אופן פון אין סוף.\nאבער בשעת מ'דארף ארויסנעמען א הוראה אין עבודת ה', קען מען ניט ארויסנעמען א הוראה פון אלע ענינים בבת אחת, נאר עס מוז זיין א סדר פון קדימה ואיחור.\nוואס אע\"פ אז „מצוה הבאה לידך אל תחמיצנה\"²⁸, ובפרט לויטן פתגם הידוע פון בעל יום ההולדת²⁹ אז איצטער דארף זיין די עבודה אין אן אופן פון „חטוף ואכול חטוף ושתי\"³⁰, אז יעדער ענין וואס עס מאכט זיך צו טאן, דארף מען דאס גלייך טאן, און ניט טראכטן אפשר דארף דער סדר העבודה זיין באופן אחר, וואס עפ\"ז קומט אויס אז ס'איז ניטא קיין ענין של קדימה ואיחור —\nאיז עס אבער געזאגט געווארן בשעת עס מאכט זיך אים א געוויסער ענין (א סימן — אז מ'שטעלט אים צו דעם ענין) צו טאן, איז דעמולט דארף זיין „חטוף ואכול חטוף ושתי\"; אבער ווען עס זיינען דא כו\"כ ענינים וועלכע ער דארף טאן, ובפרט ווען מ'טראכט זיך אריין און מ'זוכט אויף וועלכן ענין אפצושטעלן זיך און אפלערנען דערפון א הוראה אין עבודת ה' — איז פארשטאנדיק, אז דעמולט קען מען ניט טראכטן וועגן אלע ענינים צוזאמען, נאר עס דארף אין דערויף זיין אן ענין של קדימה ואיחור.\nה. די הוראה וואס מ'דארף ארויסנעמען פון יום ההולדת פון רבי\"ן נ\"ע, דארף זיין פארשטאנדיק פאר יעדער אידן — ניט נאר פאר יחידי סגולה, נאר אויך פאר דעם פשוט שבפשוטים — וויבאלד אז כללות הענין פון יום ההולדת איז נתגלה און נתפרסם געווארן פאר אלע אידן.\nאון ווי דערמאנט פריער (ס\"א) אז כללות הענין פון יום ההולדת איז נתגלה געווארן דורך כ\"ק מו\"ח אדמו\"ר —\nוואס דורך אים האט זיך אנגעהויבן עיקר ההפצה פון תורת החסידות אין אן אופן אז ס'זאל אנקומען אויך אין „חוצה\", ביז אז מען זעט אז פריער האט מען זיך אויסגערעכנט מיט דער הדפסה פון תורת החסידות, מ'האט געטראכט וואס צו דרוקן, און ווי אזוי צו דרוקן — מיט אותיות פון רש\"י דוקא וכיו\"ב, וואס אזוי איז געווען ביז צום זמן פון כ\"ק מו\"ח אדמו\"ר, און אויך בהתחלת הנשיאות שלו,\nאון דערנאך האט כ\"ק מו\"ח אדמו\"ר אנגעהויבן מפרסם זיין תורת החסידות אין אן אופן אז ס'זאל אראפקומען בדפוס און אין אותיות מרובעות דוקא, כדי אז תורת החסידות זאל אנקומען אויך אין „חוצה\", וואס אויף דעם דארף מען האבן אותיות מרובעות דוקא — כידוע דער חילוק צווישן אותיות רש\"י",[["26","26","פרש\"י עה\"פ חקת כא, כא."],["27","27","ל' הכתוב — אסתר ט, כח. וע\"פ ביאור הרמ\"ז בספר תיקון שובבים. הובא ונתבאר בספר לב דוד להחיד\"א פכ\"ט. — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051098\" data-slug=\"likkutei-sichot\" data-id=\"1300051098\">לקו\"ש ח\"ה ע' 86</a> שוה\"ג הא' להע' 1 (בסופו)."],["28","28","ראה מכילתא ופרש\"י עה\"פ בא יב, יז."],["29","29","נדפס ב„מבוא\" לקונטרס ומעין ע' 22."],["30","30","עירובין נד, א."]]],[1300201403,"מיט אותיות מרובעות בנוגע צו הל' שבת³¹ און הל' ס\"ת וכו' (מיט אלע ענינים וואס זיינען דערמיט פארבונדן).\nועד\"ז בנוגע צו אנדערע ענינים וואס זיינען נתגלה געווארן דורך כ\"ק מו\"ח אדמו\"ר, ובנדו\"ד — כללות ענין יום ההולדת — אז דאס איז נתגלה און נתפרסם געווארן פאר אלע אידן.\nדערפון איז פארשטאנדיק, אז די הוראה וואס מ'דארף דערפון ארויסנעמען, דארף זיין פארשטאנדיק ניט נאר פאר די וואס ווייסן „סוד ה' ליראיו\"³², די וואס האבן א שייכות צו לימוד חלק הסוד והדרוש והרמז שבתורה, נאר אויך פאר די וואס האבן א שייכות מערניט ווי צו חלק הפשט שבתורה, ביז צו פשט שבפשט — וויבאלד אז אויך צו זיי איז נתפרסם געווארן דער ענין פון יום ההולדת.\nו. די הוראה פון יום ההולדת זה דארף זיין פארבונדן מיט אן ענין מיוחד אין וועלכן דער בעל יום ההולדת האט זיך געקאכט און געלייגט אויף דעם א הדגשה מיוחדת, מער פון די נשיאים שלפניו.\nוכמדובר כמ\"פ אז אע\"פ אז מי הוא זה ואיזהו³³ וואס קען זיך אריינלאזן און מאכן חילוקים צווישן דעם „מאור הגדול\" מיט דעם „מאור הגדול\", אבער אעפ\"כ, וויבאלד אז דער ענין איז נתפרסם געווארן צו אים כדי אז ער זאל דערפון ארויסנעמען א הוראה — דארף ער זיך אין דעם מתבונן זיין כפי עניות דעתו, אדער עשירות דעתו, לויט זיין דעת (דאס איז אבער אן ענין של דעתן),\nאון אויסגעפינען אין וואס באשטייט ענינו המיוחד פון דעם רבי\"ן נ\"ע, און דערפון דארף ער ארויסנעמען א הוראה בעבודתו.\nאון אויף דערויף זאגט מען „אדם רוצה בקב שלו מתשעה קבים של חבירו\"³⁴ — דער אויבערשטער האט איינגעשטעלט דעם טבע האדם אז ער האט תענוג פון „קב שלו\", אע\"פ אז דאס איז מערניט ווי איין קב, און פון חבירו זיינען דא „תשעה קבים\".\nועד\"ז בנדו\"ד — וויבאלד אז ער איז זיך מתבונן אין דעם, און לויט זיין התבוננות נעמט ער ארויס די הוראה בעבודתו, האט ער דערביי די מעלה פון „קב שלו\".\nומובן בפשטות אז די הוראה דארף זיין פארבונדן מיט מעשה בפועל, וויבאלד אז „המעשה הוא העיקר\"³⁵, און ווי דער פס\"ד (וואס ווערט געבראכט אויך אין תניא³⁶) אז אויב ער האט מכוין געווען אלע כוונות און האט ניט געטאן די מעשה בפועל, האט ער ניט מקיים געווען די מצוה.\nוואס דאס איז אויך פארבונדן מיט דעם ענין פון „בחד קטירא אתקטרנא\" (וואס מ'האט דערמאנט פריער (ס\"ד)) — אז מ'דערגרייכט ביז למעלה מעלה, ביז צו אן ארט וואס איז העכער פון דעם גאנצן גדר פון „מעלה\", און דערנאך איז מען דאס ממשיך למטה מטה, ביז אין אן ארט וואס איז נידעריקער פון דעם גדר פון „מטה\", אין מעשה בפועל, וכמבואר אין די שיחות פון דעם בעל יום ההולדת³⁷, אז דוקא דער ענין פון מעשה",[["31","31","שו\"ע אדה\"ז או\"ח סש\"מ ס\"ח."],["32","32","ל' הכתוב — תהלים כה, יד."],["33","33","ע\"ד הלשון ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד (סג, א</a>)."],["34","34","ב\"מ לח, א."],["35","35","אבות פ\"א מי\"ז."],["36","36","רפל\"ז."],["37","37","תו\"ש ע' 11-12. 120 ואילך."]]],[1300201404,"בפועל בגשמיות איז פארבונדן מיט עצמות.\nז. ענינו המיוחד פון רבי\"ן נ\"ע (בעל יום ההולדת) איז געווען דער ענין פון הפצת התורה, און לאו דוקא פנימיות התורה — נאר אויך נגלה דתורה — ווי ס'איז מודגש אין דעם וואס ער האט מייסד געווען ישיבת „תומכי תמימים\", כדי אז מ'זאל לערנען „תורת ה', תורה הנגלית ותורת החסידות, תמימה\"³⁸, אז ס'זאל ווערן „תורה אחת\", איין זאך, ובהקדמת עבודת התפלה.\nוואס דאס איז דער אויפטו פון רבי\"ן נ\"ע אין יסוד ישיבת „תומכי תמימים\" — דער ענין פון הפצת התורה:\nביים אלטן רבי\"ן זיינען געווען דריי חדרים³⁹, וואס דארטן האט מען געלערנט נגלה דתורה און פנימיות התורה,\nועד\"ז געפינט מען ביים צ\"צ אז ער האט געשיקט יונגע־לייט אין מקומות שונים אז זיי זאלן דארטן לערנען אונטער דער השגחה פון משפיעי חב\"ד⁴⁰.\nועד\"ז געפינט מען אז ביים רבי\"ן מהר\"ש זיינען געווען „יושבים\", יונגעלייט וועלכע זיינען געזעסן און געלערנט,\n[מיין זיידע⁴¹ איז געווען פון די „יושבים\" אין ליובאוויטש, נאך זיין חתונה איז ער אוועקגעפארן זיצן און לערנען אין ליובאוויטש ביים רבי\"ן מהר\"ש],\nאון דערנאך איז עס אויך נמשך געווארן אין התחלת זמן הנשיאות פון רבי\"ן נ\"ע.\nאון דערנאך ווען די נשיאות פון רבי\"ן נ\"ע איז נתגלה און נתפרסם געווארן נאכמער — איז צוגעקומען דער אויפטו פון התייסדות ישיבת „תומכי תמימים\", וואס דערמיט האט זיך אויפגעטאן דער ענין פון הפצת התורה,\nוארום די כוונה פון התייסדות ישיבת „תומכי תמימים\" איז — אויף צוציען אהינצו תלמידים פון כל קצוי תבל, ניט נאר די וואס געפינען זיך אין יענעם ארט, אדער בסמיכות צו יענעם ארט, נאר אויך די וואס געפינען זיך בריחוק מקום,\nועד\"ז בנוגע צו די וואס געפינען זיך בריחוק מקום ברוחניות — די וואס ווילן נאר ניט גיין לערנען אין דער ישיבה — אז מ'זאל זיי צוציען און אריינברענגען אין דער ישיבה, כדי אז זיי זאלן לערנען נגלה דתורה און פנימיות התורה גם יחד.\nועפ\"ז איז פארשטאנדיק אז דער אויפטו פון רבי\"ן נ\"ע איז געווען דער ענין פון הפצת התורה.\nאע\"פ אז בזמנו פון דעם אלטן רבי\"ן איז מען אויך ארומגעפארן ממקום למקום אויף מפיץ זיין תורה און יהדות — איז עס אבער ניט געווען אין דעם אופן ההפצה וואס עס האט זיך אויפגעטאן דורך התייסדות ישיבת „תומכי תמימים\".\nוי\"ל אז התייסדות ישיבת תומכי תמימים (וואס דערמיט האט זיך אויפגעטאן עיקר ענין הפצת התורה) איז געווען די כוונה פון רבותינו נשיאינו",[["38","38","שיחת כ\"ק אדמו\"ר נ\"ע שמח\"ת תרנ\"ט — נדפסה בסה\"מ תרנ\"ט ע' רכג. ועוד."],["39","39","לקו\"ד כרך א כט, ב. התמים ח\"ב ע' נ ואילך."],["40","40","קונטרס אדמו\"ר הצ\"צ ותנועת ההשכלה ע' 33 ואילך."],["41","41","הרה\"ג הרה\"ח ר' מאיר שלמה, רב בניקוליוב."]]],[1300201405,"שלפנ\"ז, נאר בפועל איז עס ארויסגעקומען דורך דעם רבי\"ן נ\"ע⁴².\nח. וי\"ל בדרך אפשר: די התייסדות פון ישיבת תומכי תמימים דורך דעם רבי\"ן נ\"ע, איז געווען פארבונדן מיט דעם ענין פון „עטרת זקנים בני בנים\"⁴³ — וואס דערפאר איז עס ניט געווען בתחלת נשיאותו, נאר כמה שנים לאח\"ז:\nהתייסדות ישיבת תומכי תמימים איז געווען בשנת תרנ\"ז, וואס דעמולט איז געווען די חתונה פון כ\"ק מו\"ח אדמו\"ר⁴⁴, און ס'איז געווארן די יכולת און די אפשריות אויף דעם ענין פון „בני בנים\" — און דאס האט אויפגעטאן ביים רבי\"ן נ\"ע דעם ענין פון „עטרת זקנים\", און דערפאר האט ער דעמולט מייסד געווען ישיבת תומכי תמימים, וואס ענינה איז אויפצושטעלן תלמידים (בנים) וואס זאלן זיין „נרות להאיר\"⁴⁵ (בני בנים).\nוואס י\"ל אז דאס איז פארבונדן מיטן מארז\"ל⁴⁶ אויפן פסוק⁴⁷ „לא ימושו מפיך ומפי זרעך ומפי זרע זרעך גו'\", אז בשעת עס זיינען דא דריי דורות⁴⁸, „זרע זרעך\", „בני בנים\", איז א זיכערע זאך אז דאס איז „מעתה ועד עולם\", „תורה מחזרת על אכסניה שלה\".\nובפרט אז דאס איז געווען אין א זמן פון שמחה (חתונת בנו יחידו) — וואס דעמולט ווערט דאס אויפגעטאן מיטן פרסום הכי גדול, און אין אן אופן שלמעלה ממדידה והגבלה⁴⁹.\nט. האמור לעיל אז התייסדות ישיבת תומכי תמימים איז געווען פארבונדן מיט דעם ענין פון „עטרת זקנים בני בנים\" — געפינט מען אויך בנוגע צו די אבות, „אבות העולם\"⁵⁰, אברהם יצחק ויעקב:\nדעם עיקר הענין פון לימוד התורה געפינט מען בא יעקב אבינו, כמ\"ש⁵¹ „ויקם עדות ביעקב ותורה שם בישראל\" (וואס „ישראל\" גייט אויף יעקב אבינו).\nוואס אע\"פ אז „אברהם אבינו זקן ויושב בישיבה הי'\"⁵², ביז ווי די גמרא⁵³ זאגט אז עס זיינען געווען שי\"ח תלמידים וואס האבן געלערנט תורה ביי אברהם אבינו (וואס דאס איז די גימטריא פון „אליעזר\"), ועד\"ז „יצחק אבינו זקן ויושב בישיבה הי'\"⁵² —\nאיז אבער עיקר ענין לימוד התורה אין אן אופן פון א „ישיבה\" געווען בא יעקב אבינו, וארום אויף יעקב'ן שטייט אויך בתושב\"כ⁵⁴ „ויעקב איש תם יושב אהלים\", וואס דאס גייט אויף „אהלו של",[["42","42","ראה סה\"ש תש\"א ע' 104: הוד כ\"ק אאמו\"ר הרה\"ק האט געהייסן מכריז זיין ברבים אז ביום ד' י\"ח אלול וועט ער מודיע זיין ברבים א דבר שליחות וואס ער דארף איבערגעבן חסידים בשם הוד כ\"ק אבותינו רבותינו הקדושים. ובעת הכרזתו אודות ישיבת תומכי תמימים אמר: היינט ביום הקדוש איז בציווי וברכת הוד כ\"ק אבותינו רבותינו הקדושים בין איך מייסד א ישיבה (שם ע' 105)."],["43","43","משלי יז, ו. וראה אבות פ\"ו מ\"ח. ב\"ר פס\"ג, ב."],["44","44","התמים ח\"א ע' כג ואילך. סה\"ש שם ע' 104."],["45","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121149\" data-slug=\"likkutei-sichot\" data-id=\"1300121149\">לקו\"ש חי\"ב ע' 149</a>."],["46","46","ב\"מ פה, א."],["47","47","ישעי' נט, כא."],["48","48","להעיר מתוספתא עדיות בסופה."],["49","49","שהרי שמחה פורצת כל הגדרים (ד\"ה שמח תשמח תרנ\"ז ע' 49 ואילך)."],["50","50","דגם האבות נקראו כך (ירושלמי סנהדרין פ\"י ה\"א)."],["51","51","תהלים עח, ה. וראה לקו\"ת חוקת סב, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">מטות פג, ג</a>."],["52","52","יומא כח, ב."],["53","53","נדרים לב, סע\"א."],["54","54","תולדות כה, כז."]]],[1300201406,"שם ואהלו של עבר\"⁵⁵, און ווי דער צ\"צ⁵⁶ טייטשט אפ אז „שם\" גייט אויף תושב\"כ, וויבאלד „כל התורה שמותיו של הקב\"ה\"⁵⁷, און „עבר\" גייט אויף תושבע\"פ — די העברה (אריבערגאנג) והמשכה למטה, דורך תושבע\"פ.\nוואס דערפון זעט מען אז ביי „אבות העולם\" איז דער עיקר ענין לימוד התורה אין אן אופן פון א „ישיבה\" געווארן דוקא ווען עס האט זיך אויפגעטאן דער ענין פון „עטרת זקנים בני בנים\" — וואס דערפאר ווערט דוקא יעקב („בני בנים\" פון אברהם⁵⁸) אנגערופן „יושב אהלים\".\nי. ע\"פ האמור לעיל, איז פארשטאנדיק, אז די הוראה וואס מ'דארף ארויסנעמען פון יום ההולדת פון רבי\"ן נ\"ע, דארף זיין פארבונדן מיט הפצת התורה (וויבאלד אז דאס איז געווען עיקר ענינו פון בעל יום ההולדת).\nאון די הוראה בנוגע צו הפצת התורה, איז א הוראה נצחית פאר אלע אידן — ובלשון פון דעם אלטן רבי\"ן אין אגה\"ק⁵⁹ „ונלכה באורחותיו נס\"ו\" —\nידוע אויף וויפל דער אלטער רבי האט מדייק געווען בלשונו הזהב אין זיינע אגרות קודש, ובפרט ווען עס רעדט זיך וועגן אזא אגה\"ק וואס בני הגאון המחבר האבן אפגעדרוקט, וואס דער ענין דפוס איז לדורות (ווי דערמאנט פריער (ס\"א)), און דא שרייבט נאך דער אלטער רבי „ונלכה באורחותיו נצח סלה ועד\".\nוואס דער לשון „נצח סלה ועד\" באווייזט אויף דעם ענין הנצחיות, ווי עס ווערט אפגעפסק'נט אין חלק האגדה שבתורה⁶⁰ אז „כל מקום שנאמר נצח סלה ועד אין לו הפסק\", וואס דאס איז אפילו ווען עס שטייט נאר איינער פון די דריי לשונות, ועאכו\"כ בנדו\"ד אז דער אלטער רבי שרייבט אלע דריי לשונות — „נצח סלה ועד\".\nאון אין דערויף קומט נאך צו אז די קביעות פון כ' מרחשון בשנה זו איז ביום השבת, ונוסף לזה היינטיקער יאר שנת השמיטה, „שבת לה'\"⁶¹, און א יאר וואס הויבט זיך אן מיט יו\"ט של ר\"ה שחל להיות בשבת, כפי שיתבאר לקמן, און נוסף לזה קומט צו נאך אן ענין מיוחד וואס איז דא בשנה זו, כפי שיתבאר לקמן.\nאון מ'האט די נתינת כח צו מחליט זיין די אלע החלטות טובות וואס זיינען פארבונדן מיטן יום ההולדת פון רבי\"ן נ\"ע, און די החלטות טובות זאלן אראפקומען בפועל ממש, למטה מעשרה טפחים.\n* * *\nיא. האמור לעיל (אז ענינו פון רבי\"ן נ\"ע איז געווען הפצת התורה) איז שייך צו כ' מרחשון בכל שנה ושנה — ונוסף לזה קומט נאך צו א הוראה מיוחדת וואס איז פארבונדן מיט קביעות שנה זו",[["55","55","פרש\"י עה\"פ — מב\"ר שם, י."],["56","56","אוה\"ת תולדות קמה, ב. וכ\"ה גם בלקו\"ת ואתחנן ה, א. ולהעיר מאוה\"ת שם, שב' אהלים אלו הם (גם) סתים וגליא דאורייתא — והרי זהו החידוש שבישיבת תו\"ת (כנ\"ל ס\"ח. לקמן סט\"ז)."],["57","57","רמב\"ן בהקדמתו עה\"ת. וראה זח\"ב פז, א."],["58","58","ראה ב\"ר שם: עטרת זקנים בני בנים . . אברהם לא ניצל כו' אלא בזכות של יעקב. ולהעיר מהמשך המדרש שם: „משל כו' שהוא עתיד להוליד בת והיא נשאת למלך\", שזהו ע\"ד ענין „ביום חתונתו\" זה מתן תורה\" (אוה\"ת ח\"ש קכו, א)."],["59","59","סכ\"ז."],["60","60","עירובין נד, א."],["61","61","בהר כה, ב־ד."]]],[1300201407,"(כמדובר כמ\"פ אז נוסף אויף דער הוראה וואס איז דא מידי שנה בשנה, קומט צו א הוראה מיוחדת וואס איז פארבונדן מיט קביעות שנה המיוחדת).\nאון די הוראה פון דער קביעות מיוחדת פון שנה זו, איז ניט נאר אויף דעם יאר ווען די קביעות איז באופן כזה, נאר על כל השנים כולם.\nיב. די קביעות מיוחדת פון שנה זו איז — אז כ' מרחשון קומט אויס ביום השבת, ונוסף לזה איז היינטיקער יאר שנת השמיטה, „שבת לה'\", ונוסף לזה איז עס א יאר וואס התחלתה וראשיתה איז געווען בשבת, יו\"ט של ר\"ה שחל להיות בשבת.\nוואס ס'איז דאך ניט מוכרח אז אלע דריי ענינים זאלן טרעפן צוזאמען, וארום עס קען זיין אז כ' מרחשון זאל אויספאלן בשבת און ס'זאל ניט זיין שנת השמיטה, און עס קען אויך זיין כ' מרחשון אין שנת השמיטה זאל ניט זיין בשבת —\nאון דא קומען אלע ענינים צוזאמען: כ' מרחשון, שבת, דער גאנצער יאר איז „שבת לה'\", און ר\"ה איז אויך געווען בשבת.\nוואס דערפון זעט מען אויף וויפל ס'איז מודגש דער ענין פון שבת⁶².\nיג. נוסף לזה קומט אויך צו אז די מועדים פון חודש כסלו זיינען אויך פארבונדן מיט יום השבת — ובהקדים:\nדי קביעות המועדים פון חודש תשרי, ועד\"ז די קביעות פון כ' מרחשון, איז תלוי אין דער קביעות פון ראש השנה:\nווען ר\"ה איז חל בשבת, איז דער ערשטער טאג סוכות בשבת, און שמע\"צ איז בשבת [סיידן בזמן שהיו מקדשין ע\"פ הראי', וואס דעמולט האט געקענט זיין א פאל אז ס'איז נתברר געווארן (דורך די עדים וואס האבן געזען דעם מולד הלבנה) אז ס'איז געווען א טעות אין דער קביעות פון ר\"ה, וואס דעמולט איז די קביעות פון א' סוכות און שמע\"צ ניט אין דעם זעלבן טאג ווי ר\"ה], ועד\"ז איז כ' מרחשון אויך חל בשבת.\nאבער די מועדים פון חודש כסלו — אנהויבנדיק פון ט' כסלו, יו\"ד כסלו, י\"ט כסלו, און חנוכה [וואס ער איז דער יו\"ט בהלל וכו'⁶³ פון חודש כסלו — א יו\"ט וואס איז במשך פון א גאנצע וואך ויותר, אכט טעג] — זיינען ניט תלוי אין דער קביעות פון ר\"ה, דאס איז תלוי אין דער קביעות פון חודש חשון, צי ער איז א מלא אדער א חסר, וואס אין דערויף זיינען דא שינויים.\nאון אין קביעות שנה זו (אז חודש מרחשון איז מלא) קומט אויס אז חנוכה (דער יו\"ט פון חודש כסלו) איז אויך בשבת — דער ערשטער טאג פון חנוכה, און דער לעצטער טאג פון חנוכה (וואס די צוויי טעג זיינען כולל כל ימי החנוכה⁶⁴) — זיינען בשבת.\nוכמבואר אין חסידות אז ס'איז דא א מעלה מיוחדת ביום הראשון דחנוכה⁶⁵, און א מעלה מיוחדת ביום השמיני דחנוכה⁶⁶, און יש בזה מה שאין בזה — און",[["62","62","ובפרט ע\"פ המדובר בהתוועדות דמוצאי ש\"פ בראשית ש.ז. — דבשנים כתיקונם כשהיו מקדשין ע\"פ הראי', אפשר שיהי' תשרי חסר, ואז כשחל ר\"ה בשבת — כ' מ\"ח הוא ביום הששי."],["63","63","שבת כא, ב."],["64","64","יום הא' — כולל „ימים היוצאין\", ויום הח' — „ימים הנכנסין\" (שבת שם)."],["65","65","ראה שערי אורה ד\"ה בכ\"ה בכסלו פמ\"ב (יז, ב): עיקר הנס ביום הא' . . והוא כולל ד' ימים."],["66","66","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480261\" data-slug=\"or-hatorah-hb\" data-id=\"8316480261\">אוה\"ת חנוכה (כרך ה) תתקסב, א</a>. שיחת זאת חנוכה תשל\"ט — במעלת יום ח' דחנוכה („זאת חנוכה\")."]]],[1300201408,"בקביעות שנה זו איז יום הראשון דחנוכה און (במילא) יום השמיני דחנוכה ביום השבת.\nיד. דער ביאור השייכות פון חנוכה צו די ימים טובים פון חודש תשרי, און צו כ' מרחשון (וואס דערפאר קומען זיי אלע איז (בשנה זו) אין דעם זעלבן טאג — ביום השבת):\nחנוכה (דער יו\"ט בהלל כו' פון חודש כסלו) קומט בהמשך צו די ימים טובים פון חודש תשרי, וואס סיומם וחותמם איז חגה\"ס און שמע\"צ.\nאון ס'איז פארשטאנדיק אז ס'איז דא א שייכות פנימית צווישן חנוכה מיט חגה\"ס⁶⁷ — לויט דעם וואס די גמרא⁶⁸ לערנט אפ פון חגה\"ס בנוגע צו די ענינים פון חנוכה (הדלקת נר חנוכה).\nוכמבואר אין חסידות⁶⁹ אז שמונת ימי חנוכה זיינען כנגד די שמונה ימים פון חגה\"ס און שמע\"צ — די ערשטע שבעה ימים דחנוכה זיינען כנגד שבעת ימי הסוכות, און יום השמיני דחנוכה איז כנגד שמיני עצרת.\nטו. אין דערויף קומט צו נאך אן ענין:\nחנוכת ביהמ\"ק הראשון איז געווען „שבעת ימים ושבעת ימים ארבעה עשר יום\"⁷⁰, וואס דאס האט זיך אריינגעצויגן אין חגה\"ס, ד.ה. אז בחגה\"ס איז געווען חנוכת ביהמ\"ק הראשון.\nאון חנוכת ביהמ\"ק איז פארבונדן מיט דעם ענין פון חנוכה: צווישן די טעמים עיקריים אויף דעם וואס דער יו\"ט ווערט אנגערופן „חנוכה\" איז⁷¹, דערפאר וואס דעמולט איז געווען דער „טהרו את מקדש כו'\"⁷², חנוכת בית המקדש.\nועפ\"ז איז נאכמער מודגש דער קשר צווישן חנוכה מיט חגה\"ס — וויבאלד אז אין ביידע איז געווען דער ענין פון חנוכת בית המקדש.\nטז. עד\"ז איז אויך דא א שייכות צווישן חנוכה מיט כ' מרחשון:\nדער עיקר הענין וואס אויף דעם איז נקבע געווארן דער יו\"ט פון חנוכה איז — דער נס השמן⁷³, וואס „שמן\" איז פארבונדן און איז מרמז אויף פנימיות התורה⁷⁴.\nאון דאס איז דער פארבונד מיט כ' מרחשון, דער יום ההולדת פון רבי\"ן נ\"ע, וואס ער האט מייסד געווען ישיבת תומכי תמימים, אז דארטן זאל מען לערנען נגלה דתורה און פנימיות התורה, אין אן אופן פון „תורה אחת\".\nוואס דאס איז דאך געווען דער אויפטו פון דעם רבי\"ן נ\"ע אין יסוד הישיבה, אז דער לימוד פון נגלה דתורה מיט פנימיות התורה זאל זיין אין אן אופן פון „תורה אחת\" —\nאע\"פ אז אין די דרושי חסידות פון דעם צ\"צ געפינט מען אז עס זיינען דא סיי ענינים אין נגלה דתורה, און סיי ענינים פון דרוש רמז און רזי תורה⁷⁵ — איז עס אבער אין אן אופן אז יעדער",[["67","67","ידועה ההערה מביכורים פ\"א מ\"ז: ועד החג . . ועד חנוכה."],["68","68","שבת שם."],["69","69","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370157\" data-slug=\"torah-or\" data-id=\"3901370157\">תו\"א מקץ לד, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480222\" data-slug=\"or-hatorah-hb\" data-id=\"8316480222\">אוה\"ת שם תתקמב, ב</a>. תתקסו, ב ואילך."],["70","70","מ\"א ח, סה."],["71","71","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101287\" data-slug=\"likkutei-sichot\" data-id=\"1300101287\">לקו\"ש ח\"י ע' 279</a> בהערה. ושי\"נ."],["72","72","הודאת „ועל הנסים\" דחנוכה."],["73","73","ראה פרש\"י שבת כא, ב ד\"ה מאי חנוכה: על איזה נס קבעוה."],["74","74","ראה אמ\"ב שער הק\"ש פנ\"ד ואילך. ועוד."],["75","75","ראה שיחת ערב ר\"ה תשל\"ט."]]],[1300201409,"ענין האט א באזונדער מדור, אין באזונדערע שורות, אין באזונדערע פסקאות, (חצע\"ג).\nדער אויפטו פון דעם רבי\"ן נ\"ע אין לימוד בישיבת תומכי תמימים איז — אז אין די זעלבע ד' אמות לערנט מען סיי נגלה דתורה און סיי פנימיות התורה, אין אן אופן פון „תורה אחת\", כמבואר בארוכה אין קונטרס עץ החיים.\nוואס דאס ווערט אויפגעטאן דורך הקדמת עבודת התפלה, וואס דאס איז אויך נוגע צום לימוד פון נגלה דתורה, כמבואר אין לקו\"ת⁷⁶ בנוגע צו דעם וואס די גמרא⁷⁷ דערציילט אויף אבא בנימין אז ער האט געזאגט „על תפלתי שתהא סמוכה למטתי\", אז די שלימות פון לימוד התורה איז ווען דאס איז לאחרי הקדמת עבודת התפלה.\nיז. די הוראה דערפון וואס כ' מרחשון קומט אויס בשבת — צוזאמען דערמיט וואס היינטיקער יאר איז „שבת לה'\", ר\"ה איז געווען בשבת, און חנוכה איז אויך בשבת:\nדער כללות הענין פון שבת איז — „אז תתענג על ה'\"⁷⁸, „וקראת לשבת עונג\"⁷⁹, און „כל מלאכתו עשוי\"⁸⁰, וואס דאס איז אן ענין וואס יעדערער פארשטייט, אפילו א בן חמש למקרא.\nאון דאס איז פארבונדן מיט דעם ענין פון לימוד התורה:\nס'איז ידוע דער ביאור אין דעם מארז\"ל⁸¹ „לא ניתנה תורה כו' אלא לאוכלי המן\", אז כדי דער לימוד התורה זאל זיין ווי עס דארף צו זיין, דארף מען שטיין אין דעם מעמד ומצב אין וועלכן עס זיינען געשטאנען „אוכלי המן\".\nוהביאור בזה:\nדי „אוכלי המן\" האבן ניט געהאט קיינע דאגות פון עניני העולם, וארום זיי האבן באקומען „לחם מן השמים\", און זיי האבן געוואוסט אז זיי וועלן באקומען וויפל זיי דארפן האבן, און זייער יגיעה וועט אין דערויף ניט העלפן, ווי מ'האט געזען אז „לא העדיף המרבה והממעיט לא החסיר\"⁸².\nועד\"ז האבן זיי געהאט מים מבארה של מרים, ועד\"ז האבן זיי געהאט זייערע לבושים כדבעי דורך די ענני הכבוד⁸³.\nאון וויבאלד אז זיי האבן געהאט אלץ וואס זיי דארפן האבן — האבן זיי ניט געהאט קיינע דאגות פון עניני העולם, ובמילא האבן זיי געקענט לערנען תורה כדבעי.\nאון אויף דערויף זאגט מען „לא ניתנה תורה כו' אלא לאוכלי המן\" — כדי דער לימוד התורה זאל זיין כדבעי, דארף מען שטיין אין דעם מעמד ומצב פון „אוכלי המן\", אז מ'זאל ניט האבן (טראכטן) קיינע דאגות פון עניני העולם, וואס דעמולט וועט מען קענען לערנען תורה כדבעי.\nעפ\"ז איז פארשטאנדיק, אז וויבאלד בשבת איז „כל מלאכתו עשוי\", דער אויבערשטער נעמט אויף זיך די מלאכה פון א אידן⁸⁴, ובמילא איז (מצד דעם",[["76","76","ברכה צו, ב."],["77","77","ברכות ה, ב."],["78","78","ישעי' נח, יד."],["79","79","שם, יג."],["80","80","מכילתא ופרש\"י עה\"פ יתרו כ, ט. טושו\"ע (ואדה\"ז) או\"ח סשצ\"ח (סכ\"א)."],["81","81","מכילתא ר\"פ בשלח. שם טז, ד."],["82","82","בשלח טז, יח."],["83","83","פרש\"י עה\"פ עקב ח, ד."],["84","84","כמרדכי (ביצה טו, סע\"ב. שו\"ע אדה\"ז או\"ח סרמ\"ב ס\"ג) לוו עלי ואני פורע."]]],[1300201410,"אידן) „כל מלאכתו עשוי\" — האט ניט דער איד קיינע דאגות פון עניני העולם, ובמילא קען ער לערנען תורה כדבעי⁸⁵, ביז אז ער זאל זיך אינגאנצן אריינלייגן אין תורה, אין אופן פון „כל עצמותי תאמרנה\"⁸⁶, וכמרז\"ל⁸⁷ „אם ערוכה ברמ\"ח אברים משתמרת\", ווי געבראכט אויך⁸⁸ אין תניא⁸⁹.\nיח. אין דערויף קומט נאך צו דער אויפטו פון „אז תתענג על ה'\", „וקראת לשבת עונג\" — דער ענין התענוג. והביאור בזה:\nעס קען זיין אז ער זאל זיך טאקע אריינלייגן אין לימוד התורה, דאס וועט אבער זיין אין אן אופן פון קב\"ע.\nוארום אזוי ווי א איד איז א קבלת־עול'ניק⁹⁰, און ער ווייסט אז דער אלטער רבי זאגט אין תניא⁹¹ אז קב\"ע איז „ראשית העבודה ועיקרה ושרשה\", ובלשון הידוע⁹² „אילו נצטוה לחטוב עצים\" — לייגט ער זיך אריין אין תורה מצד זיין קבלת עול.\nזאגט מען א אידן אז עס דארף טאקע זיין דער ענין פון קב\"ע (וויבאלד אז דאס איז „ראשית העבודה ועיקרה ושרשה\"), אבער צוזאמען דערמיט דארף דאס אויך זיין דורכגענומען מיט זיין רצון און תענוג.\nוכמרז\"ל⁹³ „לעולם ילמוד אדם במקום שלבו חפץ\" (ובמילא אויך — רוצה) — אין דערויף ליגט זיין רצון⁹⁴, ד.ה. ניט נאר אז פנימיות הרצון („חפץ\"⁹⁵) דארף ליגן אין דערויף, נאר דאס דארף אראפקומען אויך אין חיצוניות הרצון — „לעולם ילמוד אדם במקום שלבו רוצה\", ד.ה. אז דאס איז זיין רצון בגלוי⁹⁶.\nוארום נוסף אויפן כללות החיוב פון לימוד התורה, איז ער אויך מחוייב זיך משתדל זיין מצליח זיין אין לימוד התורה — און כדי ער זאל מצליח זיין אין לימוד התורה, דארף מען האבן אז דער לימוד התורה זאל זיין (ניט נאר מצד קב\"ע, נאר) „בכל לבבך ובכל נפשך\"⁹⁷, מיט אלע כחות הנפש⁹⁸, כולל אויך רצון און תענוג.\nיט. און דאס איז די הוראה וואס קומט צו דערפון וואס כ' מרחשון (בקביעות שנה זו) איז ביום השבת — אז דער ענין פון הפצת התורה (וואס דאס איז די הוראה וואס קומט ארויס פון כללות הענין פון כ' מרחשון, כנ\"ל בארוכה) דארף זיין אין אן אופן פון שבת, אז „כל מלאכתו עשוי\", און „וקראת לשבת עונג\", אין אן אופן פון תענוג.\nאון בשעת דאס ווערט געטאן מתוך תענוג — פועל'ט דאס א התרחבות און א התפשטות אין דעם גאנצן ענין,",[["85","85","בדוגמת אוכלי המן — ראה הל' ת\"ת לאדה\"ז פ\"ג ס\"ב, שהעושה תורתו קבע ומלאכתו עראי עוזר לו הקב\"ה (גם) „במעט עסק ומלאכה\"."],["86","86","תהלים לה, י."],["87","87","עירובין שם."],["88","88","נוסף על הל' ת\"ת שלו פ\"ד סוס\"ט."],["89","89","פל\"ז (מז, א)."],["90","90","ראה סה\"מ תש\"ד ע' 5."],["91","91","רפמ\"א."],["92","92","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. וראה גם המשך תרס\"ו ע' נד."],["93","93","ע\"ז יט, א. ולהעיר: הדין הנ\"ל לא מצאתיו (לע\"ע) בר\"יף כו' שו\"ע אדה\"ז וצע\"ג."],["94","94","כי ע\"י התענוג בדבר — רוצה בו."],["95","95","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש</a> ד\"ה לבבתני הא' ספ\"א (כח, ד). ושי\"נ."],["96","96","דאם חסר הרצון (בגלוי) — לא ילמוד, וחסר המעשה שהוא העיקר."],["97","97","ואתחנן ו, ה."],["98","98","נוסף על שערוכה בכל אברי הגוף — כבפנים לעיל סרס\"י יז."]]],[1300201411,"ווי ס'איז פארשטאנדיק פון סיפור הגמרא⁹⁹ אז דער ענין התענוג האט גע'פועל'ט א התרחבות אפילו אין אן „עצם\" — „שמועה טובה תדשן עצם\"¹⁰⁰:\nאן ענין של שינוי און גידול אין א משך זמן קצר ביותר (ברגע אחד כמימרא — דהשמועה טובה), איז לכאורה שייך נאר אין דעם עור און בשר, אבער ניט אין די עצמות.\nאון אפילו בנוגע צום עור און בשר, איז דא א גיל מסוים וואס ביז דעמולט איז דא דער ענין הגידול, און דערנאך ווען עס קומט דער גיל העמידה, איז ניטא דער גידול הבשר (מערניט ווי דער גידול השערות והצפרנים — וואס אין כאן המקום להאריך בזה).\nדערציילט אבער די גמרא א סיפור וועגן א גוי (וואס ער איז דאך ווייט פון „תורת אמת\"), אז זייענדיק שוין אין גיל העמידה [ווי ס'איז פארשטאנדיק דערפון וואס ער איז שוין דעמולט געווען א (ראוי ל)מלך, און ער האט שוין געהאט א זון, וואס איז געווען (ראוי להיות) ממלא מקומו, א שר צבא כמותו] — האט דער ענין התענוג גע'פועל'ט א התרחבות כפשוטה אין זיין עצם.\nאון דאס איז געווען אין אן אופן אז עס האט גע'פועל'ט און ס'איז געווען קענטיק אויך אין דעם נעל [וואס דאס איז דער לבוש (וואס איז מחוץ הימנו) פון דעם אבר הכי תחתון שבגוף האדם], אז פריער האט ער געקענט אנטאן דעם נעל, און נאך דעם וואס דער עצם איז נתרחב געווארן (מצד דעם ענין התענוג), האט ער שוין ניט געקענט אנטאן דעם נעל, וויבאלד אז ס'איז געווארן צו קליין.\nד.ה. אז אפילו ווען א מענטש איז אלט 119 יאר מיט שס\"ד ימים — קען דער ענין התענוג פועל'ן א התרחבות, ואפילו אין זיין עצם.\nוואס דערפון איז פארשטאנדיק דער גודל המעלה וואס קומט צו אין די פעולות וואס ווערן געטאן מתוך תענוג.\nכ. און אין דערויף קומט נאך צו דער ענין פון „וקראת לשבת עונג\":\nא איד קען לכאורה מאכן א חשבון, אז כל האמור לעיל איז ניט קיין ענין וואס איז (פארבונדן מיט) „קב שלו\", וארום דער ענין פון הפצת התורה איז אויפגעטאן געווארן דורך דעם רבי\"ן נ\"ע און כ\"ק מו\"ח אדמו\"ר, און די קביעות בשבת האט זיך אויפגעטאן מצד קביעות החדשים והשנים דורך הלל — פעלט אין דערויף דער (תוקף, עכ\"פ, פון) „שלו\", אויף וועלכן מ'זאגט „רוצה אדם בקב שלו כו'\".\nזאגט מען אים אז ס'איז דא בכהנ\"ל (נוסף אויף דעם ענין פון „אז תתענג על ה'\" —) דער ענין פון „וקראת לשבת עונג\" — דאס וואס ער איז קורא וממשיך דעם ענין התענוג,\nאון אין אן אופן ווי ער זאגט אין תניא¹⁰¹ „כאדם הקורא לחבירו שיבוא אליו, וכבן קטן הקורא לאביו לבוא אליו\", כמבואר אין לקוטי לוי\"צ¹⁰² די צוויי לשונות בזה,\nד.ה. אז יעדער איד (ובלשון פון תניא — אפילו א „בן קטן\") קען אויפטאן דעם ענין פון „וקראת לשבת עונג\", אז ע\"י עבודתו איז ער קורא און ממשיך א הוספה און אן ענין חדש אין דעם ענין",[["99","99","גיטין נו, ב."],["100","100","משלי טו, ל."],["101","101","ספל\"ז."],["102","102","לתניא — ע' יז. אגרות קודש ע' רכ ואילך."]]],[1300201412,"התענוג, וואס דעמולט ווערט דאס אין אן אופן פון „שלו\".\nכא. און דורך דעם וואס מ'טוט די אלע פעולות פון הפצת התורה אין אן אופן פון שבת, מתוך תענוג, פועל'ט דאס א התרחבות און א הצלחה אין די אלע פעולות.\nאון דורך דעם ווערט דער גאנצער יאר א שנה של תענוג, וואס דאס איז פארבונדן מיטן אות תי\"ו פון דעם אל\"ף־בי\"ת, ועד\"ז ווערן נמשך די אלע ברכות וואס זיינען פארבונדן מיט אלע אותיות פון אל\"ף־בי\"ת, וואס יעדערע פון די ברכות הויבט זיך אן מיט איינע פון די אותיות פון אל\"ף־בי\"ת,\nאנהויבנדיק פון שנת אורה און שנת ברכה — און ביז צו שנת גאולה — גאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n* * *\nכב. האמור לעיל וועגן דעם וואס בקביעות שנה זו איז כ' מרחשון ביום השבת, איז ניט אן ענין וואס איז פארבונדן במיוחד מיטן הולדת וגיל (— עלטער) פון רבי\"ן נ\"ע.\nעס איז אבער אויך דא אן ענין מיוחד אין ענין ההולדת פון שנה זו, בשינוי (ובהוספה) אויף יום ההולדת אין די שנים שלפני\"ז:\nאנהויבנדיק דערפון וואס בכל שנה ושנה איז „יורד אור חדש עליון יותר שלא הי' מאיר עדיין מימי עולם אור עליון כזה\"¹⁰³ [אין אן אופן פון „מעלין בקודש\"¹⁰⁴ — וארום „מגיד דבריו ליעקב חוקיו ומשפטיו לישראל\"¹⁰⁵, איז אזוי ווי ס'איז דא דער ציווי פון „מעלין בקודש\", איז פארשטאנדיק אז אזוי איז עס אויך למעלה, און דערפון קומט דאס אזוי אראפ אויך למטה].\nוואס דערפון איז פארשטאנדיק, אז יעדן יאר אין יום ההולדת (כולל פון שנה זו) קומט צו אן „אור חדש\" לגבי די שנים שלפני\"ז — ע\"ד ווי דאס איז בנוגע צו אלע ענינים (אז בכל שנה ושנה איז „יורד אור חדש עליון יותר\"), ובפרט ווען עס רעדט זיך וועגן אן ענין פון א נשיא בישראל.\nכג. נוסף אויף דעם וואס בכל שנה ושנה קומט צו אין יום ההולדת אן „אור חדש\" וואס איז ניט געווען אין די שנים שלפני\"ז — זיינען דא זמנים מיוחדים וואס דעמולט קומט צו אן ענין וואס איז גרעסער, אדער אפילו שלא בערך לגבי דער הוספה וואס קומט צו בכל שנה ושנה.\nובדוגמא ווי דאס איז בנוגע צו דעם ענין פון לימוד התורה, אז אע\"פ אז בכל שנה ושנה דארף מען מוסיף זיין אין לימוד התורה, מצד דעם ענין פון „מעלין בקודש\", איז אבער דא א הוספה מיוחדת בשנה זו, שנת השמיטה, אז דעמולט דארף מען מוסיף זיין אין לימוד התורה אין אן אופן וואס איז שלא בערך, וויבאלד אז דעמולט איז מען פנוי פון עבודת האדמה.\nוי\"ל — אז וויבאלד עס קומט א זמן מיוחד אין וועלכן מ'דארף מוסיף זיין אין לימוד התורה אין אן אופן וואס איז שלא בערך — איז דא דער ציווי פון „שדך לא תזרע וכרמך לא תזמור\"¹⁰⁶, כדי „שתהי' כל השנה הבטלה מעבודת האדמה מוכנת לעבודתו\"¹⁰⁷.",[["103","103","אגה\"ק סוסי\"ד."],["104","104","ברכות כח, א. ושי\"נ."],["105","105","תהלים קמז, יט. וראה שמו\"ר פ\"ל, ט."],["106","106","בהר כה, ד."],["107","107","ספורנו עה\"פ שם, ב."]]],[1300201413,"[ניט ווי מען לערנט בכלל אז אזוי ווי אין שנת השמיטה איז מען פנוי פון עבודת האדמה, און מ'האט צייט, במילא איז דער מסובב אז מען דארף דעמולט מוסיף זיין אין לימוד התורה — נאר (געשמאקער איז צו זאגן אז) אדרבה: וויבאלד אז מ'דארף בשנה זו מוסיף זיין אין לימוד התורה, טאר מען זיך ניט פארנעמען מיט עבודת האדמה].\nועד\"ז איז פארשטאנדיק בנוגע צו דעם ענין פון יום ההולדת: נוסף אויף דער הוספה וואס עס קומט צו בכל שנה ושנה, זיינען דא שנים ותקופות מיוחדות וואס אין זיי קומט צו א הוספה אין אן אופן וואס איז שלא ע\"ד הרגיל ביז — שלא בערך.\nולדוגמא: יעדער תקופה פון עשר שנים איז אן ענין מיוחד, און ווען עס גייען דורך עשר שנים קומט צו א הוספה מיוחדת — ווי ס'איז פארשטאנדיק דערפון וואס די משנה זאגט אין אבות¹⁰⁸ „בן עשרים לרדוף, בן שלשים לכח וכו'\",\nוואס דאס איז אזוי בגשמיות (אז אין יעדער תקופה פון עשר שנים קומט צו א נייער ענין) — דערפאר וואס „נשתלשלו מהן\"¹⁰⁹, וויבאלד אז אזוי איז עס אין פנימיות הענינים.\nכד. עד\"ז איז דא אן ענין מיוחד וואס קומט צו אין יום ההולדת הנ\"ל פון שנה זו:\nאין כ' מרחשון פון שנה זו הויבט זיך אן שנת המאה ועשרים פון יום ההולדת פון רבי\"ן נ\"ע, וואס די הולדת איז געווארן אין כ' מרחשון שנת כתר\"א (כידוע דער סימן בזה¹¹⁰), און אין כ' מרחשון שנת תש\"מ הויבט זיך אן שנת המאה ועשרים.\nידוע די שקו\"ט צי לאחרי ההסתלקות איז דא דער ענין פון זמן (און אויך ווען די נשמה געפינט זיך למעלה, רעכנט מען די הוספה ומספר השנים) — ובלשון הגמרא¹¹¹ „יש בגר בקבר\" (אז אויך לאחר מיתה איז דא דער ענין פון בגרות), כמבואר בארוכה באם ראגאטשאווער¹¹².\nוואס אין דערויף איז דא א רשימה (בירור) פון כ\"ק מו\"ח אדמו\"ר¹¹³, וואס דארטן שרייבט ער אז זיין פאטער האט אים דערציילט אז „במעל\"ע זה שנתמלאו שמונים וארבע שנים לירידת נשמתי בעולם התחתון .. הנה כל אחד מכ\"ק רבותינו ואבותינו הק' יאמר דרוש על פסוק דקאפיטל פ\"ד\", וואס דערפון איז פארשטאנדיק, אז אויך לאחרי ההסתלקות איז דא (און אויך למעלה) דער ענין פון מספר השנים — לויט דעם זמן פון ב\"ד של מטה¹¹⁴,\nנוסף אויף כללות הענין וואס „מה זרעו בחיים אף הוא בחיים\"¹¹⁵, אז מצד דערויף וואס עס זיינען דא תלמידיו און תלמידי תלמידיו, איז „אף הוא בחיים\" (בעוה\"ז ובזמן שלו) — קומט נאך צו אין דערויף אז אויך ווי די נשמה געפינט זיך פאר זיך למעלה, איז דא די הוספה פון שנים וכו'.",[["108","108","פ\"ה מכ\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021317\" data-slug=\"likkutei-sichot\" data-id=\"1300021317\">לקו\"ש ח\"ב ע' 593</a> ובהע' 13 שם."],["109","109","ל' התניא רפ\"ג."],["110","110","היום יום ע' קו."],["111","111","כתובות לט, א."],["112","112","צפע\"נ לרמב\"ם הל' תשובה פ\"ח ה\"ד."],["113","113","נדפסה בהקדמה לד\"ה סמוכים לעד פר\"ת (ברוקלין, תש\"ב). הוספות לסה\"מ פר\"ת ע' שנז."],["114","114","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051115\" data-slug=\"likkutei-sichot\" data-id=\"1300051115\">לקו\"ש ח\"ה ע' 103</a> ואילך והע' 45, דמ\"ש בפנים הוא גם להדעה דאין בגר בקבר, ע\"ש."],["115","115","תענית ה, ב."]]],[1300201414,"כה. דער ענין המיוחד וואס איז דא אין דעם מספר פון מאה ועשרים שנה — וויס אויך א בן חמש למקרא, וארום ער האט שוין געלערנט דעם פסוק¹¹⁶ „והיו ימיו מאה ועשרים שנה\", ד.ה. אז דעמולט איז תכלית השלימות פון חיי האדם¹¹⁷.\nאין דערויף קומט צו נאך אן ענין:\nאויפן פסוק „והיו ימיו מאה ועשרים שנה\", זאגט רש\"י: „עד ק\"כ שנה אאריך להם אפי, ואם לא ישובו אביא עליהם מבול\".\nד.ה. אז די „מאה ועשרים שנה\" זיינען געגעבן געווארן כדי אז מ'זאל תשובה טאן, און דורך דעם מבטל זיין גזירת המבול.\nאון ווי רש\"י¹¹⁸ זאגט אז בנוגע צו התחלת המבול שטייט „ויהי הגשם\", וויבאלד אז „כשהורידן הורידן ברחמים אם יחזרו יהיו גשמי ברכה, וכשלא חזרו היו למבול\".\nוואס דערפון איז פארשטאנדיק, אז אפילו ווען דער מבול האט זיך שוין אנגעהויבן, האט מען נאך אלץ געקענט תשובה טאן, און דעמולט איז אדרבא — דאס וואלט געווען „גשמי ברכה\", נאר אזוי ווי מ'האט ניט תשובה געטאן, איז קיין ברירה ניט געווען און עס איז געווען דער מבול.\nוואס עפ\"ז איז פארשטאנדיק דער גודל הענין פון „מאה ועשרים שנה\" — אז דאס איז אן ענין וואס קען מבטל זיין גזירת המבול, און נאכמער — ברענגען „גשמי ברכה\"¹¹⁹.\nכו. וויבאלד אז אין כ' מרחשון דשנה זו הויבט זיך אן שנת המאה ועשרים פון יום ההולדת, איז עס אויך פארבונדן מיטן קאפיטל ק\"כ פון תהלים [כידוע דער מנהג¹²⁰ „לאמר הקאפיטל תהלים המתאים למספר שנותיו\"] — וואס אין כ' מרחשון שנת כתר\"א האט זיך אנגעהויבן אמירת קאפיטל א', ועד\"ז אין די שנים שלאח\"ז, ביז צו כ' מרחשון שנה זו, וואס דעמולט הויבט זיך אן אמירת קאפיטל ק\"כ.\nאון ווי מ'געפינט אין ספר המאמרים תר\"פ¹²¹ (וואס איז געדרוקט געווארן לאחרונה) אז דארטן איז דא א מאמר¹²² אויף קאפיטל ס' פון תהלים (וויבאלד אז דעמולט איז געווען התחלת שנת הששים).\nועד\"ז געפינט מען אויך אין די מאמרים פון שנת עזר\"ת (ווי דער רבי נ\"ע רופט אן דעם יאר) וואס געפינט זיך בדפוס שוין א משך זמן, און מסתמא וועט דאס זיין פארטיק אין די ימים הקרובים,\n[מ'האט געוואלט אז ס'זאל זיין פארטיק צום יום ההולדת, אז מ'זאל שוין דעמולט קענען לערנען אין דעם — אבער בפועל איז עס ניט ארויסגעקומען.\nבנוגע צו הדפסת התניא דערציילט מען דאך¹²³ אז דער אלטער רבי האט געוואלט אז ס'זאל פארטיק ווערן בתחלת כסלו כדי אז מ'זאל קענען אין דערויף לערנען בי\"ט כסלו, און בפועל",[["116","116","בראשית ו, ג."],["117","117","ראה זח\"א נח, א (ובדרך אמת ובנצו\"א שם). ל\"ת להאריז\"ל עה\"פ."],["118","118","ע\"פ נח ז, יב."],["119","119","ועאכו\"כ לאחרי מ\"ת — ראה לקמן ע' 520."],["120","120","מכ' כ\"ק מו\"ח אדמו\"ר מט' טבת תש\"ט (נדפס בקובץ מכתבים לתהלים ע' 214. אגרות קודש שלו חי\"ד ע' נג)."],["121","121","ע' סד ואילך."],["122","122","ונאמר (חלקו) בכ' מ\"ח דשנה ההיא („היום יום\" כ' מ\"ח)."],["123","123","קצוה\"ע לתניא ע' קיט ואילך."]]],[1300201415,"האט זיך די הדפסה געענדיקט בכ' כסלו.\nעכ\"פ זאל מען זעהן אז ס'זאל ווערן פארטיק אין די ימים הסמוכים צו כ' מרחשון (ע\"ד ווי דער תניא איז אפגעדרוקט געווארן כ' כסלו) — צו כ\"א מרחשון אדער כ\"ב מרחשון וכו',\nאון וויבאלד אז דאס איז א נייע זאך, וועט מען זיך צוכאפן דערצו און מ'וועט דאס לערנען מיט א חיות נוסף וכו', ווי דער מיטעלער רבי שרייבט¹²⁴ אז דער דרך איז אז ווען עס קומט א נייע זאך, לערנט מען דאס מיט מער חיות כו'].\nוואס דארטן איז דא א מאמר אויפן פסוק „למנצח אל תשחת לדוד מכתם\" — דער ערשטער פסוק פון קאפיטל נ\"ז פון תהלים.\nוואס דערפון איז אויך פארשטאנדיק בנדו\"ד, אז דער יום ההולדת בשנה זו איז פארבונדן מיט קאפיטל ק\"כ פון תהלים.\nכז. אין קאפיטל ק\"כ הויבט זיך אן א נייער ענין אין תהלים — די ט\"ו קאפיטלעך פון „שיר המעלות\", וואס אלע ט\"ו קאפיטלעך זיינען איין המשך.\nדער ענין פון „שיר המעלות\" האט אויך א שייכות מיט כ' מרחשון — און אין דערויף זעט מען א דבר פלא, אז בשעת „מ'לעבט מיט דער צייט\", מיט די ענינים פון תורה וואס זיינען פארבונדן מיט דער צייט¹²⁵, זעט מען דעם קשר ושייכות צווישן די ענינים פון תורה מיט די ענינים וואס זיינען פארבונדן מיט דעם זמן:\nדער ענין פון כ' מרחשון איז פארבונדן מיט הפצת התורה (ווי גערעדט פריער בארוכה), וואס דאס האט א שייכות מיוחדת מיט יעקב אבינו, ווי דערמאנט פריער (ס\"ט) אז יעקב איז געווען „יושב אהלים\", ביז אז מ'זאגט „ויקם עדות ביעקב ותורה שם בישראל\".\nאון דאס האט א שייכות מיוחדת מיט דעם ענין פון „שיר המעלות\" — דער קאפיטל ק\"כ פון תהלים, וואס איז פארבונדן מיט דעם יום ההולדת פון שנה זו:\nאויפן פסוק¹²⁶ „וישכב במקום ההוא\" וואס שטייט אויף יעקב אבינו, שטייט אין מדרש¹²⁷ „כאן שכב, אבל כל י\"ד שנה שהי' טמון בבית עבר לא שכב\", און דערנאך ברענגט זיך א צווייטע דעה אז „כאן שכב, אבל כל כ' שנה שעמד בביתו של לבן לא שכב\", ווי עס שטייט¹²⁸ „ותדד שנתי מעיני\".\nדערנאך איז ער ממשיך אין מדרש¹²⁹ „ומה הי' אומר\" —\n[בנוגע צו די י\"ד שנה וואס ער איז געווען בבית עבר, איז קיין שאלה ניט „מה הי' אומר\", וארום דעמולט איז ער געזעצן און געלערנט תורה, אבער בנוגע צו די כ' שנה וואס ער איז געווען בבית לבן, איז די שאלה „ומה הי' אומר\"] —\n„ר' יהושע בן לוי אמר ט\"ו שיר המעלות שבספר תהלים, מאי טעמי', שיר המעלות לדוד לולי ה' שהי' לנו יאמר נא ישראל¹³⁰, ישראל סבא (יעקב אבינו). ר' שמואל בן נחמן אמר כל ספר",[["124","124","בהקדמתו לדרך חיים."],["125","125","ראה היום יום ע' קא. סה\"ש תש\"ב ע' 29 ואילך."],["126","126","ויצא כח, יא."],["127","127","ב\"ר פס\"ח, יא."],["128","128","ויצא לא, מ."],["129","129","וראה גם ב\"ר פע\"ד, יא."],["130","130","תהלים קכד, א."]]],[1300201416,"תהלים הי' אומר, מה טעם, ואתה קדוש יושב תהלות ישראל¹³¹, ישראל סבא\".\nועפ\"ז יש לומר ולבאר דער קשר ושייכות פון „שיר המעלות\" מיט יום ההולדת פון כ' מרחשון.\nכח. דער ביאור אין דעם מדרש הנ\"ל:\nזייענדיק בבית לבן איז דאך יעקב אבינו געווען אין א מעמד ומצב של גלות, ער איז אוועקגעגאנגען פון בית יצחק אביו, און געקומען אין בית לבן,\nאון דארטן האט ער זיך פארנומען מיט צאן לבן, וואס „צאן\" איז מלשון יציאה¹³², דאס איז מחוץ פון ענין הקדושה.\nביז אז זיין געפינען זיך אין בית לבן האט גע'פועל'ט בײ אים א ירידה כביכול ממדריגתו¹³³, ווי רש\"י¹³⁴ זאגט אז יעקב האט געזאגט „אם לרמאות הוא בא גם אני אחיו ברמאות\", ד.ה. אז בײ אים איז געווען דער ענין פון רמאות בדוגמת הרמאות פון לבן¹³⁵.\nאון ווי געזאגט פריער אז זייענדיק אין בית לבן האט ער זיך פארנומען מיט בירורים בענינים וואס זיינען מחוץ לענין הקדושה — ווי לבן האט געזאגט „הבנות בנותי והבנים בני והצאן צאני גו'\"¹³⁶, וואס וויבאלד אז די טענה ווערט געבראכט אין „תורת אמת\" איז עס אן ענין אמיתי, ווי דער מיטעלער רבי¹³⁷ איז מבאר, אז דאס זיינען געווען די בירורים וואס יעקב האט מברר געווען פון די ענינים פון לבן, און דערפאר זאגט מען „הבנות בנותי וגו'\", וויבאלד אז דאס זיינען די בירורים פון עולמו של לבן.\nאון ווי מ'זעט אויך בפשטות הענינים, אז יעקב האט געזאגט „הייתי ביום אכלני חורב וקרח בלילה ותדד שנתי מעיני\"¹²⁸, ער האט ניט געהאט ניט קיין טאג און ניט קיין נאכט, וואס דאס איז געווען פארבונדן מיט א צער גדול, ביז ווי דער אלטער רבי¹³⁸ זאגט אז „צע\"ג מיעקב אבינו שאכלו חורב וקרח\", ווי שטימט דאס מיט דער דעה וואס האלט אז אסור לצער גופו אפילו לצורך ממון.\nווערט דאך די שאלה: ווי אזוי איז ער דורכגעגאנגען און בייגעשטאנען דעם ענין הגלות — „ומה הי' אומר\"?\nאויף דערויף זאגט דער מדרש, אז דאס איז געווען דורך די „ט\"ו שיר המעלות שבספר תהלים\", אדער דורך „כל ספר תהלים\", וואס דאס האט אים געגעבן דעם כח אז ער זאל קענען דורכמאכן דעם ענין הגלות.\nכט. די הוראה דערפון אין עבודת האדם:\n[?] געפינען זיך אין גלות, ד.ה. אז בנו יחידו פון מלך מלכי המלכים הקב\"ה געפינט זיך אין גלות, און אין א חושך כפול ומכופל, ביז אין „צוק העתים\" (ווי דער אלטער רבי ברענגט דעם לשון אין אגה\"ק בכ\"מ¹³⁹), מ'גע־",[["131","131","שם כב, ד."],["132","132","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370109\" data-slug=\"torah-or\" data-id=\"3901370109\">תו\"א ויצא כג, ג</a>. תו\"ח שם לח, ב. וישלח לט, ג ואילך."],["133","133","ע\"ד מ\"ש באברהם (לך לך יב, יא) ויהי כאשר הקריב לבוא מצרימה (ראה תורת הבעש\"ט בזה — הובאה במאור עינים ס\"פ שמות)."],["134","134","עה\"פ ויצא כט, יב."],["135","135","ראה סה\"מ עטר\"ת ע' עג. ד\"ה פדה בשלום תרס\"ח, תש\"ג."],["136","136","ויצא לא, מג."],["137","137","ראה תו\"ח ויצא ד\"ה וישכם לבן. וישלח ד\"ה וישלח יעקב פ\"א־ד."],["138","138","שו\"ע חו\"מ הל' נזקי גוף ונפש ס\"ד בקו\"א. וראה לקו\"ש ח\"י ע' 328."],["139","139","רסט\"ז. ועוד."]]],[1300201417,"פינט זיך אין א מעמד ומצב של מצוקה — ווערט די שאלה: ווי אזוי וועט מען קענען דורכמאכן און ביישטיין דעם ענין הגלות?!\nביז אז עס ווערט די שאלה: „מאין יבוא עזרי\" (וואס דער פסוק שטייט אין איינע פון די „ט\"ו שיר המעלות שבספר תהלים\"¹⁴⁰)?!\nוואס דאס איז דאך א שאלה וואס ווערט געבראכט אין „תורת אמת\" — ע\"ד די שאלה וואס ווערט געבראכט אין תורה בנוגע צו שנת השמיטה, „וכי תאמרו מה נאכל בשנה השביעית\"¹⁴¹, וואס א שאלה געבראכט אין „תורת אמת\", איז א שאלה וואס האט אן ארט אין תורה¹⁴².\nמען איז ניט שולל אז עס איז ניטא וואס צו פרעגן די שאלה „מה נאכל\", דערפאר וואס מ'דארף פארלאזן זיך אויפן אויבערשטן — וארום „אין סומכין על הנס\"¹⁴³, ער גלויבט באמונה שלימה אין דעם אויבערשטן, אבער אעפ\"כ האט ער דעם ציווי אז ער דארף טאן ענינים ע\"פ דרך הטבע, און דערפאר איז דאס א שאלה וואס האט אן ארט אין תורה.\nאון תורה דארף ענטפערן אויף דער שאלה — „וצויתי את ברכתי לכם בשנה הששית ועשת את התבואה לשלש השנים\"¹⁴⁴, ניט קיין ענין פון „וצויתי את ברכתי לכם\" סתם, נאר „בשנה הששית\" דוקא, וואס דעמולט איז (דא דער ציווי פון) „שש שנים תזרע שדך ושש שנים תזמור כרמך\", וועט אין דערויף זיין די ברכה פון דעם אויבערשטן, ביז אז „ועשת את התבואה לשלש השנים\".\nועד\"ז בנדו\"ד — תורה פרעגט אין נאמען פון א אידן „מאין יבוא עזרי\"?!\nל. אויף דערויף זאגט מען א אידן, אז ווי אזוי קען מען דורכגיין און דורכמאכן דעם ענין הגלות — דורך די „ט\"ו שיר המעלות שבספר תהלים\", און דורך „כל ספר תהלים\", ע\"ד ווי ס'איז געווען בא יעקב אבינו¹⁴⁵.\nאון מ'ברענגט די ראי' אויף דערויף (אויך) דערפון וואס שטייט „ואתה קדוש יושב תהלות ישראל\" — כידוע תורת הבעש\"ט בזה¹⁴⁶, אז דער אויבערשטער מצ\"ע איז „ואתה קדוש\", קדוש ומובדל פון עולמות, און כדי אז ס'זאל זיין „יושב\", ער זאל נמשך ווערן למטה (די המשכה למטה ביז אין אן אופן אז זי ווערט אנגערופן „ישיבה\"¹⁴⁷) — ווערט דאס אויפגעטאן דורך „תהלות ישראל\", דורך דעם וואס אידן לויבן דעם אויבערשטן, זאגנדיק ברוך השם און געלויבט דער אויבערשטער¹⁴⁸,\n[וואס ווען מ'זאגט „ברוך השם\", איז „השם\" א כינוי בלה\"ק פון די שמות הקדושים, ווען מ'זאגט אבער „געלויבט דער אויבערשטער\", איז עס בכלל ניט בלה\"ק, ס'איז א ווארט אין לע\"ז, און אעפ\"כ זאגט מען אז דורך דעם וואס אידן זאגן „געלויבט דער אויבערשטער\", ווערט אויפגעטאן אז „ואתה קדוש יושב תהלות ישראל\"].\nאון דעמולט האט מען דעם ענטפער",[["140","140","תהלים קכא, א. וראה ב\"ר פס\"ח, ב."],["141","141","בהר כה, כ."],["142","142","ראה — בענינינו — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011107\" data-slug=\"likkutei-sichot\" data-id=\"1300011107\">לקו\"ש ח\"א ע' 107</a>."],["143","143","ראה פסחים סד, ב."],["144","144","בהר שם, כא."],["145","145","שבחי' האבות ישנה אצל כל אחד מישראל — תו\"א ר\"פ וארא."],["146","146","כש\"ט (הוצאת קה\"ת) הוספות אות מז. ושי\"נ."],["147","147","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380204\" data-slug=\"likkutei-torah\" data-id=\"4001380204\">לקו\"ת קדושים כט, ג</a>. ועוד."],["148","148","ראה גם כש\"ט שם אות קצז. ושי\"נ."]]],[1300201418,"אויף דער שאלה „מאין יבוא עזרי\" — דער עזר קומט פון (דער דרגא פון) „אין\", כמבואר בכ\"מ¹⁴⁹ אז „אין\" איז נאך העכער פון אלע שמות הקדושים,\nאון פון דארטן ווערט דאס נמשך און עס קומט אראפ למטה, ביז — אין „עזרי מעם ה' (עושה) שמים וארץ\"¹⁵⁰.\nלא. אין דערויף קומט צו נאך אן ענין:\nדי „ט\"ו שיר המעלות שבספר תהלים\" ווערן אנגערופן בשם „שיר\", וואס „שיר\" איז פארבונדן מיט אן ענין של שמחה גלוי', ווי ס'איז פארשטאנדיק פון דעם מאמרז\"ל¹⁵¹ „אין אומרים שירה אלא על היין\".\nאיז לכאורה ניט פארשטאנדיק: די „ט\"ו שיר המעלות שבספר תהלים\" האט יעקב אבינו געזאגט זייענדיק אין בית לבן, וואס דעמולט איז ער געווען אין א מעמד ומצב של גלות —\nאיז וויבאלד אז מדתו של יעקב איז מדת האמת¹⁵² [ובפרט אז נוסף לזה איז נאך דא דער ענין פון „תתן אמת ליעקב\"¹⁵³, כמבואר אין די דרושים פון צ\"צ¹⁵⁴ אז נוסף אויף דעם וואס יעקב מצ\"ע איז מדת האמת, קומט נאך צו דער ענין פון „תתן אמת ל'יעקב\", א העכערע דרגא אין מדת האמת], א\"ז ווי האט ער געקענט זאגן „שיר המעלות\", אן ענין של שירה, זייענדיק אין א מעמד ומצב של גלות?!\nאיז דער ביאור בזה: יעקב אבינו האט געזעהן אין כללות ענין הגלות דעם תכלית הכוונה שבזה, וואס די כוונה פון כללות הגלות איז, אז ס'זאל זיין דער „יתרון האור מן החושך\" און „יתרון החכמה מן הסכלות\", און דערפאר איז ביי אים געווען די אמירה פון „שיר המעלות\", אן ענין פון שירה, וואס איז פארבונדן מיט א שמחה גלוי'.\nח\"ו צו זאגן אז דער מעמד ומצב הגלות איז דער מעמד ומצב אין וועלכן אידן דארפן זיך געפינען — דער גלות איז אן ענין פון „חושך\" און אן ענין פון „סכלות\" וכו', נאר די כוונה אין דערויף איז, אז ס'זאל זיין דער „יתרון האור מן החושך\" און „יתרון החכמה מן הסכלות\".\nוואס דערפון האט מען די הוראה פאר יעדער אידן, אז ווען ער גיט א קוק אויף דעם ענין הגלות, זאל ער זעהן דעם תכלית המכוון שבזה — אז ס'זאל זיין דער „יתרון האור מן החושך\" און „יתרון החכמה מן הסכלות\", וואס דעמולט ווערט ער ניט נתפעל פון דעם חושך הגלות, ואדרבה, ער שטייט אין אן אופן פון שמחה, ביז אז בײ אים איז גאר דא אן ענין פון שירה, „שיר המעלות\".\nוואס אויף דערויף דארף זיין „אשא עיני\"¹⁵⁵ — מען דארף האבן „אויגן\", און די אויגן דארפן זיין אין „פנים\" (ניט אין „עורף\", און ניט אין „קעשענע\"¹⁵⁶) — און דעמולט קען מען זעהן אין דעם גלות דעם תכלית המכוון שבזה¹⁵⁷.",[["149","149","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">לקו\"ת שלח נא, א</a> (מזח\"ג קכט, א), דבחי' אין הוא למעלה משם הוי'. וראה לקו\"ת שמע\"צ צ, ב בענין מאין יבוא עזרי."],["150","150","תהלים שם, ב. וראה ב\"ר שם."],["151","151","ברכות לה, א."],["152","152","<a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג (יט, א</a>)."],["153","153","מיכה ז, כ."],["154","154","אוה\"ת תשא ע' א'תתקנו ואילך."],["155","155","תהלים שם, א."],["156","156","וכל' הכתוב (שופטים טז, יט) „השוחד יעור עיני\"."],["157","157","להעיר מתנחומא ס\"פ תולדות: אשא עיני אל ההרים .. זה משיח בן דוד."]]],[1300201419,"ובדוגמא ווי ר' יוסי האט געזאגט¹⁵⁸ „מימי לא קריתי לאשתי אשתי כו' אלא לאשתי ביתי\" — וואס לכאורה איז ניט פארשטאנדיק: וואס איז דער גודל המעלה אין דעם וואס ער האט אנגערופן אשתו „ביתו\" — יעדער איינער קען דאך אנרופן אשתו מיטן נאמען „ביתו\"?!\nאיז ידוע דער ביאור בזה¹⁵⁹, אז ר' יוסי איז געשטאנען אין א מעמד ומצב אז ער האט ניט געזעהן אין אשתו קיין אנדער זאך אויסער איר שלימות — דעם תכלית המכוון — דער ענין פון „ביתי\", און דערפאר ווען ער האט געדארפט איר אנרופן, האט ער געהאט נאר דעם נאמען „ביתי\".\nועד\"ז בנדו\"ד: ווען א איד גיט א קוק אויף כללות ענין הגלות, דארף ער זעהן אין דערויף דעם שלימות ותכלית המכוון שבזה, וואס דעמולט קען ער שטיין בשמחה, ביז אז ער זאגט „שיר המעלות\".\nוואס דאס ווערט אויפגעטאן דורך דעם וואס ביי אים איז „נפשו עיקר וגופו טפל\"¹⁶⁰, און ניט נאר אז דער גוף איז „טפל\", נאר ער איז בטל לגמרי, וואס דעמולט זעט ער ניט אין דעם ענין הגלות קיין אנדער זאך אויסער דעם תכלית המכוון שבזה — און דערפאר שטייט ער אין אן אופן פון שמחה, ביז אז ביי אים ווערט אן ענין של שירה — „שיר המעלות\".\nלב. האמור לעיל וועגן די „ט\"ו שיר המעלות שבספר תהלים\", איז אויך פארבונדן מיטן בית המקדש:\nדי משנה¹⁶¹ זאגט אז עס זיינען געווען „חמש עשרה מעלות היורדות מעזרת ישראל לעזרת נשים, כנגד חמש עשרה שיר המעלות שבתהלים, שעליהן לוים עומדין בכלי שיר ואומרים שירה\".\nוואס די „חמש עשרה מעלות\" פון ביהמ\"ק, באווייזן אויף אן ענין פון עלי' מדרגא לדרגא אין עבודת ה' גופא, אן אופן פון „מעלין בקודש\".\nויהי\"ר אז בקרוב ממש זאל מען זוכה זיין צום בנין ביהמ\"ק השלישי, וואס דארטן וועלן זיין די „חמש עשרה מעלות וכו'\",\nוואס דאס וועט זיין אין דער גאולה האמיתית והשלימה, אין אן אופן פון „מיד הן נגאלין\"¹⁶², וארום וויבאלד אז „דעתם קצרה\" (דערפאר וואס „מרובים צרכי עמך\"¹⁶³), דארף די גאולה זיין „מיד\" כפשוטו, אין דער מדידה פון זמן דא למטה,\nבביאת משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.\n* * *\nלג. בנוגע צו די ט\"ו שיר המעלות, ברענגט זיך אין חיד\"א¹⁶⁴ אז „ט\"ו שיר המעלות אמר דוד ע\"ה כנגד ט\"ו שנים שחיו האבות ביחד\",\n[וארום אברהם אבינו האט געלעבט „מאה שנה ושבעים שנה וחמש שנים\"¹⁶⁵,",[["158","158","שבת קיח, ב."],["159","159","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071187\" data-slug=\"likkutei-sichot\" data-id=\"1300071187\">לקו\"ש ח\"ז ע' 174</a> ואילך."],["160","160","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא רפל\"ב</a>."],["161","161","סוכה נא, ב."],["162","162","רמב\"ם הל' תשובה פ\"ז ה\"ה."],["163","163","פיוט בתפלת נעילה. ע\"ס ברכות כט, ב. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370123\" data-slug=\"torah-or\" data-id=\"3901370123\">תו\"א וישלח כו, רע\"ג</a>. ד\"ה מים רבים תרל\"ו בתחלתו."],["164","164","בפירושו „יוסף תהלות\" לתהלים קאפיטל ק\"כ."],["165","165","חיי שרה כה, ז."]]],[1300201420,"און יצחק איז געבארן געווארן ווען אברהם איז געווען „בן מאת שנה\"¹⁶⁶, און יעקב איז געבארן געווארן ווען יצחק איז געווען „בן ששים שנה\"¹⁶⁷ — קומט אויס אז עס זיינען געווען „ט\"ו שנים שחיו האבות ביחד\"].\nדערנאך ברענגט ער א צווייטן פירוש — אז די ט\"ו שיר המעלות זיינען „כנגד ט\"ו תיבות שבפ'¹⁶⁸ ויפגע במקום ויקח מאבני המקום, שמהאבן ההיא נעשו שיתין, והיא אבן השתי'\".\nאון ער זאגט דארטן אז די פירושים זיינען גענומען פון „רמזי רבני אשכנז הקדמונים\".\n[אין טור¹⁶⁹ ברענגט זיך פון „חסידי אשכנז\" אז „היו שוקלין וסופרין מספר מנין תיבות התפלות והברכות (פון שמו\"ע) וכנגד מה נתקנו\" — וצריך בירור צי דאס זיינען די זעלבע „רבני אשכנז\" וועלכע דער חיד\"א ברענגט בפירושו.\nאבער עכ\"פ, וויבאלד אז דער חיד\"א ברענגט דאס בשם „רבני אשכנז הקדמונים\", קען מען זיך אויף דערויף פארלאזן].\nלד. והביאור בזה — ובהקדים:\nעס ברענגט זיך אין חסידות¹⁷⁰ א ביאור אויף דעם ענין פון „ונאספו כל העדרים\"¹⁷¹, ע\"פ משל פון א מלחמה, וואס מ'האט אפגעלערנט פון דער מלחמה וואס איז געווען אין די צייטן פון דעם אלטן רבי\"ן:\nדער סדר פון „מערכות המלחמה\" איז, אז „מחלקים כל א' החיל שלו לג' חלקים, חלק א' באמצע .. ושתי ידות מימין ומשמאל, וכן מסדר גם הצד שכנגדו לג' חלקים כאלו, ונלחמים אלו מול אלו\".\nאון די הצלחה אין דער מלחמה ווערט דורך דעם וואס מ'שטעלט אוועק „כל ג' מחנות שלו נגד מחנה וחלק א' של השונא, וזהו הנק' אטאקירען, כיון שכל ג' מחנות שלו מסבבים מחנה א' של השונא, ועי\"ז יתגבר בודאי עלי', ואח\"כ יעשה כן למחנה ב' של השונא וכן לג', עד כלותם\".\nאון דערפון לערנט מען אפ בנוגע צו עבודת ה' [כתורת הבעש\"ט¹⁷² אז פון יעדן ענין וואס מ'זעט אדער מ'הערט, דארף מען ארויסנעמען א הוראה אין עבודת ה'] — ווי מ'דארף זיך פירן אין מלחמת היצר:\nכדי אז מ'זאל קענען מנצח זיין אין מלחמת היצר, דארף מען מעורר זיין „כל ג' מדות דקדושה (אהבה ויראה און רחמים) לעומת מדת אחת דקליפה, ועי\"ז בודאי יפילו וינצחו אותה, וזהו כמשל האטאקירען כו', וכמו\"כ אח\"כ יעירו ג' מדות דקדושה הנ\"ל נגד מדה השנית דקליפה, עד כלותם\".\nאון דערנאך איז ער מסיים אז דאס איז דער פירוש הפסוק „ונאספו כל העדרים, שהם אהוי\"ר ורחמנות דקדושה כו'\".\nלה. עפ\"ז וועט מען אויך פארשטיין אין דעם וואס דער חיד\"א ברענגט אז „ט\"ו שיר המעלות אמר דוד המלך ע\"ה כנגד ט\"ו שנים שחיו האבות ביחד\":",[["166","166","פרשתנו כא, ה."],["167","167","תולדות כה, כו."],["168","168","ויצא כח, יא."],["169","169","או\"ח סקי\"ג."],["170","170","דרוש הצ\"צ — נעתק בהתמים חו' ג ע' ז [קכ, א]."],["171","171","ויצא כט, ג."],["172","172","כש\"ט הוספות אות קכז־קכח."]]],[1300201421,"מ'האט גערעדט פריער בארוכה, אז די ט\"ו שיר המעלות האט יעקב אבינו געזאגט אין בית לבן, זייענדיק אין דעם מעמד ומצב פון גלות, און דורך דער אמירה פון די ט\"ו שיר המעלות איז ער דורכגעגאנגען און בייגעשטאנען די אלע ענינים פון גלות.\nוואס בנוגע צו כללות ענין הגלות, זיינען דאך דא די צוויי סוגים כלליים פון גלות: גלות ישמעאל, און גלות אדום, וואס אויף יעדן אופן פון גלות דארף מען האבן א באזונדער אופן עבודה¹⁷³.\nאון אויף דערויף זאגט מען אז כדי מ'זאל קענען דורכגיין און ביישטיין דעם ענין הגלות, דארף מען האבן די „ט\"ו שיר המעלות\" וועלכע זיינען „כנגד ט\"ו שנים שחיו האבות ביחד\":\nדי ג' אבות זיינען דאך כנגד די ג' מדות דקדושה, אהבה ויראה ורחמים¹⁷⁴, און בשעת מ'האט אלע ג' אבות ביחד, מ'קלייבט צוזאמען אלע ג' מדות דקדושה ביחד, דעמולט¹⁷⁵ האט מען די נתינת כח אז מ'זאל קענען ביישטיין די אלע נסיונות פון גלות און זיי מבטל זיין, ע\"ד ווי גערעדט פריער (סל\"ב) אז דורך דעם ענין פון „ונאספו כל העדרים, שהם אהוי\"ר ורחמנות דקדושה\", איז מען מנצח די ענינים פון לעו\"ז¹⁷⁶.\nלו. דער ענין פון צוזאמענקלייבן אלע ג' מדות דקדושה („ונאספו כל העדרים\") — וואס דורך דעם גייט מען דורך דעם ענין הגלות, און מ'איז מבטל די ענינים פון לעו\"ז — איז פארבונדן מיט מספר ט\"ו, „ט\"ו שיר המעלות\", און „ט\"ו שנים שחיו האבות ביחד\".\nוהביאור בזה:\nדער מספר ט\"ו ווייזט אויף די אותיות י\"ה פון שם הוי' (י\"ה איז בגימטריא ט\"ו)¹⁷⁷, וואס יו\"ד איז דער ענין פון חכמה, און ה\"א איז דער ענין פון בינה¹⁷⁸, וואס דאס זיינען „הנסתרות לה' אלקינו\"¹⁷⁹, דער ענין פון מוחין און התבוננות, עבודת התפלה¹⁸⁰.\nאון דערנאך איז דא דער „והנגלות לנו ולבנינו\"¹⁷⁹, ו\"ה נגלות¹⁸⁰, וואס דאס איז דער ענין פון מדות און מעשה¹⁸¹.\nאון אויף דערויף זאגט מען אז כדי ס'זאל זיין דער חיבור פון אלע ג' מדות דקדושה, אלע ג' קווין, דארף מען אנקומען צו דעם ענין פון י\"ה (ט\"ו), דער ענין פון מוחין.\nוהביאור בזה:\nדי מדות מצ\"ע זיינען דאך דריי באזונדערע מדות, ג' קווין, און אויף",[["173","173","ראה לקו\"ת ואתחנן ה, א: זה לעומת זה, אברהם חסד דקדושה וישמעאל חסד דלעומת זה . . יצחק גבורה דקדושה וכנגדו גבורה דקליפה (עשו — אדום)."],["174","174","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380228\" data-slug=\"likkutei-torah\" data-id=\"4001380228\">לקו\"ת אמור לה, ג</a>. ובכ\"מ."],["175","175","בלקו\"ת ואתחנן ה, סע\"א, שיעקב הוא ת\"ת שמחבר חו\"ג „ולכן הוא בלבדו גלל האבן מע\"פ הבאר\". אבל אין סתירה מזה למ\"ש בפנים, כי עיקר הנצחון הוא דוקא כשיש גם הקווין חו\"ג כמו שהם בפני עצמם (ולא רק כמו שהם כלולים בת\"ת), כדמוכח מדרוש הצ\"צ שבהע' 170 שגם התעוררות הרחמים אינו מספיק וצריך גם לאהבה ויראה."],["176","176","ראה לקו\"ת שם: ועי\"ז נאמר ונאספו שמה כל העדרים וגללו את האבן מע\"פ הבאר כו', כל העדרים דייקא, היינו התכללות המדות, ואזי וגללו את לב האבן המטמטם הלב כו' (וראה לקמן סל\"ז)."],["177","177","ראה אוה\"ת ואתחנן ע' קטז: ט\"ו שיר המעלות שאמר יעקב . . כדי להמשיך בחי' י\"ה."],["178","178","אגה\"ת פ\"ד (צד, ב ואילך)."],["179","179","ל' הכתוב — נצבים כט, כח."],["180","180","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת ראה כט, א</a>."],["181","181","לקו\"ת ואגה\"ת שם."]]],[1300201422,"דערויף זאגט מען אז „זמן תורה לחוד\" און „זמן תפלה לחוד\"¹⁸², און דערנאך איז דא דער ענין פון „הנהג בהן מנהג דרך ארץ\"¹⁸³.\nוואס דאס איז אלץ ווי די מדות זיינען שוין בגלוי, ועד\"ז ווען עס קומט דערנאך אראפ אין מעשה בפועל, וואס דעמולט ווערט דאס נחלק צו מ\"ע און מל\"ת וכו'; אבער ווי די מדות שטייען בשרשם, אין דער התבוננות אין מוחין, עבודת התפלה, דארטן שטייען זיי אלע צוזאמען¹⁸⁴.\n[ועד\"ז ווי מ'געפינט אין דעם ענין פון לימוד התורה, אז אע\"פ אז לימוד התורה איז איינע פון די רמ\"ח מ\"ע, איז אבער דא דער ענין פון לימוד התורה ווי דאס איז דער שורש ומקור פון קיום כל המצוות (כולל אויך — מצות ת\"ת), וויבאלד אז „תלמוד מביא לידי מעשה\"¹⁸⁵.\nועד\"ז בנוגע צו לימוד פנימיות התורה, אז אע\"פ אז דאס איז א מצוה פרטית פון ידיעת הבורא וכו', וואס דאס איז א „מצוה רבה ונשאה\"¹⁸⁶, גיט דאס אבער אריין א חיות וכו' אין כללות התורה ומצוות.\nועד\"ז בנוגע צו עבודת התפלה, אז אע\"פ אז דאס איז א מצוה פרטית, איז עס אבער אויך דער יסוד ושורש פון כללות התורה ומצוות¹⁸⁷.\nועד\"ז געפינט מען בנוגע צו בנין ביהמ\"ק [וואס דאס איז אויך פארבונדן מיט די „ט\"ו שיר המעלות\", ווי געבראכט פריער (ס\"ל) אז זיי זיינען „כנגד חמש עשרה מעלות היורדות מעזרת ישראל לעזרת נשים\"], אז אע\"פ אז דאס איז א מצוה פרטית, איז עס אבער אויך אן ענין כללי אין כללות התומ\"צ (והעולם), וארום „מציון תצא תורה ודבר ה' מירושלים\"¹⁸⁸, ביז אז דורך די „חלוני שקופים אטומים\"¹⁸⁹ האט דאס גע'פועל'ט בכל העולם כולו¹⁹⁰].\nועד\"ז בנדו\"ד — אז אע\"פ אז ווי די מדות שטייען בגלוי זיינען זיי דריי באזונדערע מדות, אעפ\"כ, ווי זיי שטייען בשרשם אין דער התבוננות (איידער זיי קומען אראפ בגלוי), שטייען זיי אלע צוזאמען].\nועפ\"ז איז פארשטאנדיק, אז כדי מ'זאל קענען צוזאמענקלייבן אלע ג' מדות דקדושה, דארף מען אנקומען צו דעם ענין פון מוחין, עבודת התפלה, און דאס איז דער פארבונד מיט מספר ט\"ו („ט\"ו שיר המעלות\", און „ט\"ו שנים שחיו האבות ביחד\") — די גימטריא פון י\"ה, דער ענין פון מוחין.\nלז. האמור לעיל איז אויך פארבונדן מיטן צווייטן פירוש וואס ברענגט זיך אין חיד\"א, אז די ט\"ו שיר המעלות זיינען „כנגד ט\"ו תיבות שבפ' ויפגע במקום ויקח מאבני המקום, שמהאבן ההיא נעשו שיתין, והיא אבן השתי'\".\nוהביאור בזה¹⁹¹:",[["182","182","שבת י, א."],["183","183","ברכות לה, ב."],["184","184","אע\"פ שבפרטיות — יש התבוננות (ותפלה) דאהבה, או דיראה כו'."],["185","185","קידושין מ, ב."],["186","186","קרא קנו, ב."],["187","187","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380601\" data-slug=\"likkutei-torah\" data-id=\"4001380601\">לקו\"ת בלק ע, ד</a>. ראה שם. ברכה צו, ב. ועוד."],["188","188","ישעי' ב, ג."],["189","189","מ\"א ו, ד."],["190","190","ראה פרש\"י ד\"ה שקופים — מנחות פו, ב. ירושלמי ברכות פ\"ד ה\"ה."],["191","191","בהבא לקמן עיי\"ג צפע\"נ עה\"ת בראשית ב, ז."]]],[1300201423,"אין דעם ענין פון „ונאספו כל העדרים\", איז אויך מבואר¹⁹² אז דורך דעם ענין פון „ונאספו כל העדרים\", וואס דאס זיינען די ג' מדות דקדושה, „אהוי\"ר ורחמנות דקדושה\", ווערט אויפגעטאן דער „וגללו את האבן מע\"פ הבאר\".\nוואס „אבן\" באווייזט אויף גשמיות וחומריות העולם¹⁹³, וארום צווישן די ד' סוגים פון דצח\"מ איז עס דער סוג הכי תחתון, סוג הדומם —\nאון דורך דעם ענין פון „ונאספו כל העדרים\", ווערט אויפגעטאן דער „וגללו את האבן\", אז מ'איז מברר די חומריות און די גשמיות פון וועלט, און מ'איז דאס מהפך לקדושה.\nאון דאס איז אויך דער ענין פון „ויפגע במקום גו'¹⁹⁴ ויקח מאבני המקום\":\n„אבני המקום\" באווייזן אויף עניני עוה\"ז, וואס יעדערער פון זיי איז תופס מקום לעצמו („אבני המקום\"), און „אבני המקום\" איז לשון רבים, אן ענין של פירוד —\nאון אויף דערויף זאגט מען „ויקח מאבני המקום וישם מראשותיו\", און דערפון ווערט דער „ויקח את האבן אשר שם מראשותיו\"¹⁹⁵, „אבן\" לשון יחיד¹⁹⁶, אז מ'איז מברר און מהפך די אלע ענינים פון עוה\"ז לקדושה¹⁹⁷.\nביז וואנעט אז „מהאבן ההיא נעשו שיתין, והיא אבן שתי'\", וואס דאס איז פארבונדן מיטן בית המקדש,\nאון דערפון ווערט דאס נמשך אין דער גאנצער וועלט — כמרז\"ל¹⁹⁸ בנוגע צו דער „אבן שתי'\" אז „ממנה הושתת העולם\", ועד\"ז בנוגע צו די „שיתין\" וואס „יורדין עד התהום\"¹⁹⁹, וואס דער „תהום\" איז דער יסוד פון כל העולם כולו.\nלח. ויש לקשר האמור לעיל וועגן די ט\"ו שיר המעלות, מיט דעם מספר פון ק\"כ (וואס די התחלה פון „שיר המעלות\" איז אין קאפיטל ק\"כ פון תהלים) — וואס דאס איז אויך דער פארבונד מיטן יום ההולדת דשנה זו:\nעס איז מבואר אין פע\"ח²⁰⁰ [בנוגע צו אמירת „א־ל עליון\" אין תפלת העמידה, סיי אין ימות החול, און סיי אין שבתות וימים טובים] אז דורך דער הכאה (הכפלה) פון דעם אות יו\"ד (חכמה) אין אות ה\"א (בינה) [ווי די אותיות י\"ה זיינען צוזאמען מיטן מילוי (מילוי אלפי\"ן), וואס כללות ענין המילוי איז פארבונדן מיט גילוי לזולת²⁰¹], ד.ה. צוואנציק (יו\"ד) מאל זעקס (ה\"א), קומט ארויס ק\"כ, וואס דאס זיינען די ק\"כ אורות.\nאון דער מספר ק\"כ איז פארבונדן מיט (די ק\"כ) צירופים פון שם אלקים²⁰²",[["192","192","דרוש הצ\"צ שבהערה 170. לקו\"ת שבהערה 176."],["193","193","ראה לקו\"ת שם: ש„אבן\" קאי על „לב האבן המטמטם הלב\"."],["194","194","נוסף על האמור לעיל (סל\"ו) שהצירוף והתכללות דהג' מדות דקדושה נעשה ע\"י ענין המוחין, עבודת התפלה — שעפ\"ז מובן הקשר שבין ה„ט\"ו שנים שחיו האבות ביחד\" לה„ט\"ו תיבות שבפ' ויפגע במקום\", מאחר ש„ויפגע במקום\" הוא התפלה (ברכות כו, ב. פרש\"י עה\"פ)."],["195","195","ויצא כח, יח."],["196","196","ראה פרש\"י עה\"פ שם, יא. תנחומא ויצא א."],["197","197","ראה תו\"א ויצא כא, א־ב. ועוד."],["198","198","יומא נד, ב."],["199","199","סוכה מט, א."],["200","200","שער העמידה פי\"ב."],["201","201","סידור קטו, ב. קנט, ב. ועוד."],["202","202","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380100\" data-slug=\"likkutei-torah\" data-id=\"4001380100\">לקו\"ת ויקרא ו, רע\"ג</a>. ועוד."]]],[1300201424,"— מען טוט אויף דעם „בראשית ברא אלקים\", מ'איז מגלה די כוונה הפנימית פון שם אלקים, כתורת הבעש\"ט²⁰³ בזה.\nלט. בנוגע צו דעם מספר פון ק\"כ, האט מען דערמאנט פריער (סכ\"ה) אז ס'שטייט „והיו ימיו מאה ועשרים שנה\", וואס דערפון איז פארשטאנדיק, אז דער מספר פון ק\"כ באווייזט אויף שלימות חיי האדם.\nדי שלימות פון ק\"כ שנה איז אויך פארבונדן מיט תורה:\nאויפן פסוק „לא ידון רוחי באדם לעולם בשגם הוא בשר והיו ימיו מאה ועשרים שנה\", זאגט די גמרא²⁰⁴ „משה מן התורה מנין בשגם הוא בשר\", וואס „בשגם\" איז בגימטריא „משה\"²⁰⁵ — און ענינו פון משה רבינו איז דער ענין פון תורה²⁰⁶.\nאון דאס איז אויך פארבונדן דערמיט וואס מספר שני חייו פון משה רבינו — איז אויך געווען מאה ועשרים שנה²⁰⁷.\nמ. אין דערויף קומט צו נאך אן ענין:\nדי שלימות פון ק\"כ שנה איז ניט נאר בנוגע צו חיי האדם עלי אדמות, נאר אויך לאחרי ההסתלקות איז דא די שלימות פון ק\"כ שנה. והביאור בזה:\nאויפן פסוק „והיו ימיו מאה ועשרים שנה\" פרעגט די גמרא אין ירושלמי²⁰⁸:\n„קרוב לאלף שנה חי' אדם הראשון, ואת אמר והיו ימיו מאה ועשרים שנה\"?!\n[און נאכמער: אפילו אין דעם דור פון פלג, וואס „בימיו נפלגה הארץ\"²⁰⁹, „שעד פלג היו בני אדם חיים ארבע מאות שנה, אלא פלג לא חי' אלא ר' שנה ומעט\"²¹⁰ — איז עס נאך אלץ געווען מער פון „מאה ועשרים שנה\"].\nאון די גמרא ענטפערט: „אלא לק\"כ שנה (אחר מותו) הוא חוזר למלוא תרווד אחד רקב\" — ווי די גמרא זאגט דארטן אז „מלא תרווד אחד²¹¹ נטל הקב\"ה ממקום המזבח וברא בו אדם הראשון\", און ווען עס גייען דורך ק\"כ שנה לאחר מותו, איז ער „חוזר למלוא תרווד אחד רקב\", ווי ער איז געווען בתחלת בריאתו.\nדערפון איז פארשטאנדיק, אז די שלימות פון ק\"כ שנה איז (ניט נאר בנוגע צו חיי האדם עלי אדמות, נאר) אויך לאחר מיתה — וויבאלד אז דער קיום פון דעם גוף לאחר מיתה איז ביז ק\"כ שנה [ע\"ד ווי עס איז געווען בא משה רבינו, ובתכלית השלימות בעלמא דין, אז „לא כהתה עינו ולא נס ליחו\"²¹²], און דערנאך איז ער „חוזר למלוא תרווד אחד רקב\", ער קומט צו דער שלימות פון „ואל עפר תשוב\" — וואס „נטל הקב\"ה ממקום המזבח\".\n* * *\nמא. אויף צו מבאר זיין איין פסוק עכ\"פ פון קאפיטל ק\"כ — וועט מען זיך שטעלן אויפן פסוק „אני שלום וכי אדבר",[["203","203","סה\"מ תש\"ה ע' 74."],["204","204","חולין קלט, ב."],["205","205","פרש\"י שם ד\"ה בשגם."],["206","206","כמ\"ש (מלאכי ג, כב) זכרו תורת משה עבדי. וראה הערה הבאה."],["207","207","ברכה לד, ז. וראה ספרי עה\"פ. ולהעיר מחדא\"ג מהר\"ל לחולין שם: כי מה שהיו ימי משה מאה ועשרים שנה הוא דבר מופלג בחכמה. וראה אוה\"ת לתהלים (יהל אור) ע' שכד."],["208","208","נזיר פ\"ב ה\"ב (לז, ב)."],["209","209","נח י, כה."],["210","210","מדרש אגדה עה\"פ. וראה דעת זקנים מבעלי התוספות עה\"פ. ספורנו עה\"פ."],["211","211","שיעורו — ראה נזיר ג, ב."],["212","212","ברכה שם."]]],[1300201425,"המה למלחמה\" (וואס שטייט אין סיום הקאפיטל²¹³), וואס דאס איז אויך פארבונדן מיט דעם וואס מ'האט גערעדט פריער בנוגע צו דעם ענין פון „שיר המעלות\":\nדער כללות הענין פון מלחמה („המה למלחמה\"), איז פארבונדן מיט דער מעלה פון אתכפיא און אתהפכא, וואס דורך דערויף ווערט אויפגעטאן דער „יתרון האור מן החושך\" און „יתרון החכמה מן הסכלות\".\nוכמבואר אין המשך תרס\"ו²¹⁴ (פון בעל יום ההולדת) דער משל פון בן המלך, אז בשעת ער געפינט זיך אין היכל אביו, איז עס ניט קיין חידוש, און עס איז ניט ניכר די מעלה פון בן המלך; און דוקא ווען דער מלך שיקט אים אוועק למרחקים, אין אן ארט וואו מ'ווייסט גארניט וועגן מציאות המלך, און זייענדיק דארטן, ווערט ער דערפון ניט נתפעל, און בלייבט במעמדו ומצבו, ואדרבה, ער פועל'ט אויף די וואס געפינען זיך דארטן אז זיי זאלן האבן א שייכות מיטן מלך — אין דערויף ווערט נתגלה די מעלה פון בן המלך.\nאון דאס פועל'ט אן עילוי אין דעם מלך, וארום אע\"פ אז דער מלך איז „משכמו ומעלה גבוה מכל העם\"²¹⁵, ביז אין אן אופן פון התנשאות עצמית, אעפ\"כ, דורך דעם וואס עס ווערט נתגלה די מעלה פון בן המלך, פועל'ט דאס אן עילוי אין דעם מלך.\nועד\"ז איז פארשטאנדיק בנוגע צו עבודת האדם — אז כללות ירידת הנשמה למטה, און כללות העבודה פון אתכפיא און אתהפכא (די מלחמה מיט לעו\"ז), איז כדי צו מגלה זיין די כחות פון דער נשמה.\nוואס אע\"פ אז דער אויבערשטער ווייסט ווי עס וועט זיין עבודת הנשמה למטה (און ער ווייסט די כחות פון דער נשמה וכו') — איז אבער ניט מספיק דאס וואס מ'ווייסט דערפון, נאר תכלית השלימות בזה איז, ווען עס קומט אראפ בפועל ממש, וואס דעמולט ווערן נתגלה די כחות פון דער נשמה²¹⁶.\nובדוגמא ווי דאס איז כביכול ביים אויבערשטן: כללות בריאת העולם איז כדי „שיתגלו שלימות כחותיו כו'\"²¹⁷, דערפאר וואס עלה ברצונו (מטעם הידוע לו, אדער מטעם הכמוס) אז זיינע כחות זאלן ארויסקומען בגילוי, וואס דאס איז דוקא ווען עס קומט אראפ בפועל²¹⁸.\nועד\"ז איז אויך אין עבודת האדם: דוקא דורך דעם וואס די נשמה קומט אראפ דא למטה, און דארטן איז זי עובד עבודתה אין אן אופן פון אתכפיא ואתהפכא — ווערן דעמולט נתגלה די כחות און די מעלה פון דער נשמה.\nוואס דאס איז אויך פארבונדן מיט דעם ענין פון מעשה המצוות בפועל ממש, וואס דערמיט פארבינדט מען זיך מיט עצמות, ווי דער בעל יום ההולדת איז מבאר²¹⁹ אז „כל המצוות מתייחסים אל העצמות\".",[["213","213","ו„הכל הולך אחר החיתום\" (ברכות יב, א)."],["214","214","ס\"ע שם ואילך."],["215","215","ש\"א ט, ב."],["216","216","ראה לעיל ע' 284 ואילך, מעלת הפועל על הכח."],["217","217","ע\"ח שער ההקדמות הקדמה ג'."],["218","218","ראה לעיל ע' 283 ואילך."],["219","219","סה\"ש תורת שלום ס\"ע 190 ואילך."]]],[1300201426,"מב. עפ\"ז וועט מען פארשטיין דעם ביאור אין דעם פסוק „אני שלום וכי אדבר המה למלחמה\":\nא איד מצ\"ע דארף וועלן אז זיין עבודה זאל זיין אין אן אופן פון „שלום\" („אני שלום\"), ד.ה. אז עס זאלן ניט זיין קיינע ענינים של נסיונות וכו', מיט וועלכע ער זאל דארפן פירן א מלחמה, ער איז מתפלל „אל תביאני כו' לידי נסיון\"²²⁰.\nואדרבה: א איד טאר ניט זוכן קיין ענין של נסיון וכו', ווי ס'איז אויך פארשטאנדיק דערפון וואס די גמרא²²¹ זאגט אז מ'טאר ניט דורכגיין אין א שוק של ע\"ז אדער אין א רחוב וואס איז היפך הצניעות.\nוואס די עבודה אין אן אופן פון „שלום\" (בלי ענינים פון נסיונות וכו') — איז כללות העבודה פון צדיקים.\nמג. עס איז אבער דא דער ענין וואס „המה למלחמה\":\n„והאלקים נסה את אברהם\"²²² — מען שטעלט אים אין א מצב ועניין של נסיון, א מצב וואס ער דארף אנקומען צו דעם אופן העבודה פון מלחמה, דארף ער קענען ביישטיין דעם נסיון.\nוואס דאס איז דער כללות הענין פון „נורא עלילה על בני אדם\"²²³, אז מ'ברענגט אים מלמעלה צו אן ענין של נסיון, וואס די כוונה בזה איז — „כי מנסה ה' אלקיכם אתכם לדעת הישכם אוהבים את ה' גו'\"²²⁴, כדי אז דורך עבודתו זאל זיין „מנסה\" — הגבהה²²⁵, יתרון האור מן החושך און יתרון החכמה מן הסכלות.\nדאס איז כללות העבודה פון בעלי תשובה — און וויבאלד אז מלמעלה וויל מען אז בײ אים זאל זיין אויך די מעלה פון בעלי תשובה, „לאתבא צדיקייא בתיובתא\"²²⁶, ברענגט מען אים צו אן ענין של נסיון וכו', כדי אז בײ אים זאל אויך זיין די מעלה פון בעלי תשובה.\nמד. און דאס איז אויך דער קשר מיט דעם ענין פון „שיר המעלות\", אן ענין של שיר, וואס איז פארבונדן מיט דעם ענין השמחה:\nלכאורה איז ניט פארשטאנדיק — וויבאלד עס רעדט זיך וועגן אן עבודה וואס איז פארבונדן מיט אן ענין של מלחמה, איז וואס פאר א שייכות האט דאס צו דעם ענין פון שיר („שיר המעלות\") און שמחה?!\nאיז דער ביאור בזה פארשטאנדיק ע\"פ האמור לעיל:\nוויבאלד אז די כוונה פון דער מלחמה איז, אז ער זאל צוקומען צו דער מעלה פון בעלי תשובה, אז בײ אים זאל זיין דער „יתרון האור מן החושך\" און „יתרון החכמה מן הסכלות\" — דערפאר איז דאס אן ענין אויף וועלכן מ'זאגט „שיר המעלות\", אן ענין של שיר ושמחה.\nמה. און וויבאלד אז די עבודה אין אן אופן פון מלחמה איז אויך אן ענין וואס איז פארבונדן מיט שיר ושמחה (מצד דער כוונה שבזה) — איז פארשטאנדיק, אז ער ווערט לגמרי ניט",[["220","220","ברכות ס, ב."],["221","221","ע\"ז יא, ב. שם יז, סע\"א ואילך. וראה גם טושו\"ע יו\"ד ר\"ס קמט. אה\"ע ר\"ס כא."],["222","222","פרשתנו כב, א."],["223","223","תהלים סו, ה. וראה תנחומא וישב ד. תו\"ח תולדות יג, א ואילך. ובכ\"מ."],["224","224","ראה יג, ד."],["225","225","ראה סה\"מ תר\"ס ע' קיב ואילך. ועוד."],["226","226","הובא בלקו\"ת שמע\"צ צב, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">שה\"ש נ, סע\"ב</a>. ובכ\"מ. וראה זח\"ג קנג, ב."]]],[1300201427,"נתפעל פון דעם ענין המלחמה, און ער טוט די עבודה מיטן תוקף המתאים, וויבאלד אז ער ווייס אז דאס איז פארבונדן מיט „ילחם מלחמות ה'\"²²⁷.\nובדוגמא ווי דאס איז אין דעם ענין המלחמה כפשוטה (בא כיבוש הארץ), אז פריער דארף מען אנהויבן מיט דעם ענין פון שלום („וקראת אלי' לשלום\"²²⁸),\n[ע\"ד ווי ס'איז געווען בא כיבוש הארץ, אז מצד דערויף וואס מ'האט זיך דערשראקן פאר אידן, איז „גרגשי פנה כו' והלך לו לאפריקי\"²²⁹],\nאבער בשעת מ'דארף אנקומען צו מלחמה, זאגט מען אז עס דארף זיין אין אן אופן פון „עד רדתה\" — אפילו בשבת²³⁰.\nד.ה. אז ווען מ'דארף אנקומען צו מלחמה, דארף מען זיך שטעלן מיטן תוקף המתאים, און מ'דארף ניט נתפעל ווערן פון א גוי, און אפילו ניט נתפעל ווערן פון א אידן!\nווייל דער תוקף איז ניט מצד „כחי ועוצם ידי\"²³¹ ח\"ו, נאר דערפאר וואס דאס איז „ילחם מלחמות ה'\".\nמו. און דורך דער עבודה אין אן אופן פון מלחמה, איז א איד מברר די ענינים פון עוה\"ז הגשמי, און איז זיי מהפך לקדושה,\nווי גערעדט פריער בארוכה אז די עבודה פון יעקב איז געווען „ויקח מאבני המקום\", נעמען די ענינים פון עוה\"ז הגשמי („אבני המקום\") און מעלה זיין לקדושה.\nוואס דאס איז דער כללות הענין פון „יעקב\", יו\"ד עקב²³², אז ער פארנעמט זיך מיט די דברים התחתונים (עקב), און איז זיי מעלה לקדושה.\nוכמבואר אין חסידות²³³ אז יעקב מצ\"ע האט פארענדיקט דאמאלס זיין עבודת הבירורים, און מצדו האט שוין געקענט זיין דער „ועלו מושיעים בהר ציון וגו'\"²³⁴, נאר ווען ער האט געשיקט די מלאכים צו עשו'ן, האבן זיי אים דערנאך געזאגט אז עשו איז נאך ניט גרייט, און דערפאר האט יעקב געזאגט אז „הצאן והבקר עלות עלי\", ובמילא איז „אני אתנהלה לאטי גו'\"²³⁵.\nמז. און כללות העבודה פון מלחמה, „ילחם מלחמות ה'\", איז פארבונדן מיט „ובנה מקדש במקומו\"²³⁶ — בנין ביהמ\"ק במקומו דא למטה, ניט נאר דער ביהמ\"ק של מעלה.\nוואס דער מקום פון דעם ביהמ\"ק האט מען כובש געווען דורך א מלחמה, און אויך האט דוד המלך דאס אפגעקויפט פון ארונה²³⁷.\nוואס אין דערויף איז אויך מודגש דער קשר צווישן „ילחם מלחמות ה'\", מיט „ובנה מקדש במקומו\".\nמח. האמור לעיל איז דיבור דרשות און רמזים וכו' — עס דארף אבער זיין א",[["227","227","רמב\"ם הל' מלכים ספי\"א."],["228","228","שופטים כ, י."],["229","229","ירושלמי שביעית פ\"ו ה\"א. ויק\"ר פי\"ז, ו."],["230","230","שופטים שם, כ. שבת יט, א."],["231","231","עקב ח, יז."],["232","232","תו\"א ויצא כא, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370135\" data-slug=\"torah-or\" data-id=\"3901370135\">וישב כט, א</a>. ובכ\"מ."],["233","233","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו\"א וישלח כד, סע\"ב</a> ואילך. תו\"ח שם לט, ג ואילך."],["234","234","עובדי' א, כא."],["235","235","וישלח לג, יג־יד. וראה פרש\"י עה\"פ שם, יד."],["236","236","רמב\"ם שם."],["237","237","דה\"א כא, כב־כד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101062\" data-slug=\"likkutei-sichot\" data-id=\"1300101062\">לקו\"ש ח\"י ע' 62</a>."]]],[1300201428,"הוראה בנוגע למעשה בפועל (וואס „המעשה הוא העיקר\"), מיט וועלכע מ'זאל אוועקגיין פון דער התוועדות.\nוואס די הוראה איז — אז ס'זאל זיין דער ענין פון הפצת התורה, נגלה דתורה און פנימיות התורה, סיי בנוגע צו זיך, און סיי בנוגע צו הפצת התורה לרבים.\nולפועל:\nיעדערער וואס געפינט זיך בא דער התוועדות און הערט וואס עס האט זיך גערעדט, ועד\"ז יעדערער פון די וואס מ'וועט זיי איבערגעבן דאס וואס עס האט זיך גערעדט אין דער התוועדות (וואס זיכער וועט מען דאס איבערגעבן) — זאל נעמען צו זיך נאך צוויי אידן לכה\"פ (וואס מיעוט רבים שנים), און פועל'ן בא זיי אז זיי זאלן (צוזאמען, באם אפשר) לערנען סיי נגלה דתורה און סיי פנימיות התורה, אין אן אופן פון „תורה אחת\".\nאון ווי דער אלטער רבי זאגט אין הל' ת\"ת²³⁸ אז „מ\"ע של תורה על כל חכם וחכם מישראל ללמד את כל התלמידים .. שנאמר²³⁹ ושננתם לבניך .. אלו תלמידיך\",\n[סיידן ווען ער בייט א מצוה אויף אן אנדער מצוה — כידוע דער סיפור²⁴⁰ אז דער אלטער רבי האט אמאל אריינגערופן א יונגערמאן (פון דעם מגיד\"ס תלמידים), און האט אים געזאגט: איך האב א מצוה פון „ולמדתם אותם את בניכם\"²⁴¹, דו האסט א מצוה פון זן ומפרנס בני ביתו, לאמיר זיך בייטן: איך וועל דיר געבן דו זאלסט קענען מקיים זיין דיין מצוה, און דו לערן מיט מיין זון].\nוואס דערפון איז פארשטאנדיק, אז יעדערער דארף טאן אין דעם ענין פון הפצת התורה, בנוגע צו די אלע וואס ער קען צו זיי דערגרייכן.\nוואס דאס איז נוסף לזה וואס יעדער תלמיד פון ישיבת תומכי תמימים דארף מוסיף זיין בא זיך בכמות ובאיכות, סיי אין נגלה דתורה און סיי אין פנימיות התורה, וואס נתגלתה בדורנו בתורת החסידות.\nמט. עד\"ז איז דא א הוראה וואס איז פארבונדן מיט די מוסדות פון „תומכי תמימים\" (און אלע מוסדות וואס ווערן אנגערופן מיט א נאמען וואס איז פארבונדן מיט תו\"ת):\nאין די ערטער וואו עס זיינען שוין דא די מוסדות, זאל מען זיי פארברייטערן נאכמער, סיי בכמות און סיי באיכות, און אריינעמען אהינצו מער תלמידים,\nאון אויך עפענען נייע סניפים פון „תומכי תמימים\" — אין די ערטער וואו ס'איז נאך ניטא קיין סניף.\nוואס בשעת מ'מאכט דעם חשבון וויפל יאר עס זיינען דורכגעגאנגען פון יום ההולדת פון רבי\"ן נ\"ע אין שנת כתר\"א, ביז היינט, וואס דאס איז הונדערט און צוואנציק יאר, און וויפל יאר עס זיינען דורכגעגאנגען פון התייסדות ישיבת תומכי תמימים אין שנת תרנ\"ז (זאל יעדערער מאכן דעם חשבון אליין), און וויפל יאר עס זיינען דורכגעגאנגען זינט כ\"ק מו\"ח אדמו\"ר האט אריבערגענומען און מייסד געווען ישיבת תומכי תמימים מעבר לים, אין חצי כדור התחתון, און מ'זעט וואס עס האט זיך אויפגעטאן במשך פון דער גאנצער צייט —",[["238","238","פ\"א ס\"ח."],["239","239","ואתחנן ו, ז."],["240","240","היום יום ע' כו."],["241","241","עקב יא, יט."]]],[1300201429,"איז דא פון וואס צו זיין שש ושמח, וארום מ'האט א סאך אויפגעטאן — דאס איז אבער נאך אלץ שלא בערך לגבי דאס וואס מ'האט געקענט אויפטאן, והעיקר: וואס מ'דארף אויפטאן, וארום עס דארף זיין „ומלאה הארץ דעה את ה' כמים לים מכסים\"²⁴²!\nנ. און שטייענדיק אין יום ההולדת פון רבי\"ן נ\"ע, וואס דעמולט איז „מזלו גובר\" — האט מען די נתינת כח אויף די אלע פעולות.\nאון די געלט וואס מ'דארף אויף דערויף האבן, איז שוין אויך דא מן המוכן, און מ'גיט דאס מלמעלה יעדערן וואס וועט נאר טאן אין דעם — מ'דארף נאר ניט נתפעל ווערן דערפון וואס עס קען זיין אז מ'וועט דארפן אריינגיין אין א חוב לזמן קצר עכ\"פ, וארום ס'איז א זיכערע זאך אז סוכ\"ס וועט מען ניט בלייבן קיין בע\"ח.\nובדוגמא ווי גערעדט כמ\"פ²⁴³ אז בשעת מ'גיט א שקל אחד לצדקה, גיט דער אויבערשטער די „ארבע הידות יהי' לכם\"²⁴⁴, לכה\"פ נאך ד' שקלים, ועד\"ז אויך בנדו\"ד, אז בשעת מ'וועט פארברייטערן די מוסדות און עפענען נייע מוסדות, האט מען די הבטחה אז „ארבע הידות יהי' לכם\".\nוכאמור אז ס'איז א זיכערע זאך אז מ'וועט ניט בלייבן קיין בע\"ח — הלואי אז מ'זאל ניט בלייבן א בע\"ח ברוחניות, אזוי ווי מ'וועט ניט בלייבן קיין בע\"ח בגשמיות!\nאון דערפאר איז (כאמור) ווען מ'געפינט זיך אין יום ההולדת פון רבי\"ן נ\"ע, און מ'גיט א קוק אויפן לוח און מ'זעט אז ס'איז דורכגעגאנגען נאך א יאר פון יום ההולדת בשנה שעברה, און צוויי יאר פון יום ההולדת מיט צוויי יאר צוריק וכו' — כאפט מען זיך אז מ'דארף נאכמער מוסיף זיין אין די פעולות פון הפצת התורה,\nוואס דערפאר דארף יעדערער פועל'ן כנ\"ל לכה\"פ אויף נאך צוויי אידן, אז בא זיי זאל זיין דער לימוד פון נגלה דתורה צוזאמען מיט פנימיות התורה,\nועד\"ז אויך בנוגע צו די מוסדות פון תומכי תמימים — פארברייטערן די מוסדות הקיימים, און מייסד זיין נאך מוסדות.\nאון אזוי ווי מ'שטייט אין יום ההולדת פון רבי\"ן נ\"ע, האט מען די הבטחה אז בשעת מ'וועט טאן אין דעם כדבעי, וועט מען מצליח זיין ביתר שאת וביתר עז.\nאון דאס וועט אויך געבן א תוספת ברכה אין בני חיי ומזוני רויחי כפשוטו, ועאכו\"כ ווי דאס איז ברוחניות הענינים, כמבואר אין דער צוואה פון בעל יום ההולדת (געדרוקט אין חנוך לנער²⁴⁵).",[["242","242","ישעי' יא, ט."],["243","243","שיחת יום שמח\"ת תש\"מ."],["244","244","ויגש מז, כד."],["245","245","ע' 48 ואילך."]]],[1300201430,"שיחת יום ג', טו\"ב כסלו ה'תשמ\"א - לפני תפלת מנחה* -\nא. ס'איז דא דער באוואוסטער בריוו פון כ\"ק מו\"ח אדמו\"ר¹ [וואס איז שוין אפגעדרוקט און מפורסם, און די וואס האבן אים ניט קענען מסתמא איצטער אויך באקומען], בנוגע צו הכנסת ספר תורה, וואס איז פאר־בונדן מיט סיום ספר תורה, וואס איז פאר־בונדן מיט כתיבת ספר תורה.\nוואס דארטן שרייבט ער (אויך) כמה פרטים און מנהגים וואס זיינען דערמיט פארבונדן, און צווישן זיי אויך — אז „איזה ימים לפני הסיום והכנסת התורה לבית הכנסת מכריזים בכל בתי הכנסיות שבעיר אשר ביום פלוני יתקיים בעזהשי\"ת סיום התורה והכנסתה לבית הכנסת\".\nב. וואס אע\"פ אז דער פירוש הפשוט אין „שבעיר\" איז דאך — אין דער זעלבער שטאט וואו דער סיום און הכנסת התורה קומט־פאר; איז דאך אבער איצטער צוגעקומען א פירוש במובן הרחב יותר אין דעם, דורך די תועלת וואס איז ארויסגעקומען פון די אנטדעקונגען שבזמן האחרון:\nס'איז דאך זיכער אז יעדער זאך וואס ווערט נתחדש און נתגלה בעולם [ניט נתחדש ממש — ווארום ס'איז דאך „אין כל חדש תחת השמש\"², נאר — מ'ווארט אויף דעם זמן ווען דאס זאל נתגלה ווערן, וואס „את הכל עשה יפה בעתו\"³] — איז דאס לכל לראש צוליב די ענינים טובים וקדושים וואס קומען דערפון ארויס:\nבכדי מ'זאל אבער ניט שולל זיין דעם ענין פון בחירה, אז עבודת האדם זאל געטאן ווערן מיט בחירה [וואס בשעת מ'איז בוחר צו פירן זיך כדבעי — באר־ווייזט דאס אז מ'געהערט צום „עם חכם ונבון\"⁴] — דערפאר איז אויך דא די מעגליכקייט פון נוצן דאס באופן בלתי רצוי, ח\"ו.\nאבער דער עיקר פון דעם, ווי פון אלע ענינים, ובפרט פון ענינים חשובים, איז — צוליב די דברים טובים וואס קומען דערפון ארויס.\nבדוגמא ווי עס שטייט אין מדרש⁵ אז „לא הי' העולם ראוי להשתמש בזהב ולמה נברא בשביל בית המקדש\": אזוי ווי מ'האט געדארפט האבן דעם זהב צוליב דעם בית המקדש (און צוליב דעם משכן וואס „איקרי מקדש\"⁶), איז ער אויך געגעבן געווארן בעולם, ובמילא איז דאס ניט שולל דעם ענין הבחירה; אבער עיקר ענינו (למה נברא) איז — צוליב עניני טוב וקדושה.",[["","","*) התוועדות בקשר לחגיגת סיום והכנסת ספר התורה שנכתב על שם כ\"ק אדמו\"ר שליט\"א והרבנית שתליט\"א — לרגל מלאת חמשים שנה לחתונתם לאריכות ימים ושנים טובות ולרגל שנת השלשים לנשיאות כ\"ק אדמו\"ר שליט\"א — שתתקיים בי\"ט כסלו הבעל\"ט, בבית הכנסת „בית מנחם\", בכפר חב\"ד, בארץ הקודש."],["1","1","בקובץ מכתבים ג (נ.י. תשי\"ג) ע' 7 ואילך. אגרות קודש שלו ח\"ז ע' עג. חלקו נעתק גם בקובץ „יגדיל תורה\" (נ.י.) שנה ג' חוברת ג (כח) סל\"א."],["2","2","קהלת א, ט. וראה מדרז\"ל עה\"פ (נסמנו ב„תולדות אהרן\" וברשימות הצ\"צ עה\"פ)."],["3","3","קהלת ג, יא."],["4","4","ואתחנן ד, ו."],["5","5","ב\"ר פט\"ז, ב. שמו\"ר רפל\"ה."],["6","6","עירובין ב, א. וראה שמו\"ר שם: ולמה נברא בשביל המשכן ובשביל ביהמ\"ק."]]],[1300201431,"ג. דערפון איז אויך פארשטאנדיק, אז בשעת ס'איז נתגלה געווארן א מכשיר וואס גיט א מעגליכקייט אז באותה שעה קען מען זיך פארבינדן פון איין ארט מיט מרחקי תבל, ביז אפילו מיט א פנה נדחת —\nאיז דאס לכל לראש — כדי עס זאל קענען ווערן א קשר אין אלע ענינים טובים, ענינים פון „אין טוב אלא תורה\"⁷ ומצותי', צווישן דעם מקום מיט די אלע מקומות מיט וועלכע מ'פארבינדט זיך, אפילו מיט א פנה נדחת כפשוטה,\nאפילו אויך מיט א פנה נדחת אין רוחניות הענינים, וואס מצד דערויף וואס ער הערט זיך צו, מאיזו סיבה שתהי', צו דעם מכשיר — איז דער־ווייל, בהשגחה פרטית, עפענט ער דעם מכשיר און ער דערהערט אן ענין פארבונדן מיט תורה ומצות.\nד. וואס דערפון איז אויך פאר־שטאנדיק בעניננו, אז וויבאלד ס'איז איצטער נתגלה געווארן א מכשיר דורך וועלכן מ'קען זיך פארבינדן פון איין ארט מיט מרחקי תבל — איז צוגע־קומען א פירוש במובן הרחב יותר אין דעם וואס מ'איז מפרסם וועגן סיום והכנסת הספר תורה „בכל בתי הכנסיות שבעיר\" — אז דאס איז כולל אויך די ערטער וואס מ'קען זיך מיט זיי פאר־בינדן דורך די מכשירים, וואס דאס איז כולל א פנה נדחת בגשמיות, און אפילו א פנה נדחת ברוחניות.\nדאס הייסט, אז וואו א איד זאל זיך נאר געפינען, און ער עפענט־אויף דעם מכשיר (מאיזו סיבה שתהי') — דער־הערט ער וועגן דעם ענין פון א ספר תורה, און אז אידן האבן זיך צוזאמענ־געקליבן און מחליט געווען צו שרייבן א ספר תורה, און האבן איר אנגעהויבן שרייבן, און האבן אויסגעפירט החלטתם הטובה בפועל אין „המעשה הוא העיקר\"⁸ — אז מ'איז מסיים די ספר תורה,\nאון אז דאס וועט געטאן ווערן „ברוב עם\"⁹ בעתו, אין א פאר טעג ארום (ווי ער זאגט אין דעם מכתב הנ\"ל אז דער פרסום (וואס איז איצטער) הויבט זיך אן „איזה ימים לפני הסיום והכנסת התורה לבית הכנסת\", כנ\"ל).\nה. דורך דערויף וואס מ'איז מפרסם וועגן סיום והכנסת הספר תורה „בכל בתי הכנסיות שבעיר\" (עטליכע טעג פאר דערויף), סיי צו די וואס הערן דאס דא, און סיי צו די וואס הערן דאס דורך די מכשירים הנ\"ל — טוט דאס אויף אן אחדות צווישן אלע אידן, וואס דאס איז פארבונדן מיט דער אחדות פון תורה.\nוהביאור בזה:\nס'איז ידוע אז „ישראל\"\n— וואס דאס גייט דאך אויף יעדן איד, אין וואס פאר א מעמד ומצב ער געפינט זיך, ווארום „אע\"פ שחטא ישראל הוא\"¹⁰, וכלשון הידוע פון כ\"ק מו\"ח אדמו\"ר במכתבו לחג הגאולה שלו¹¹, אז „לא אותי בלבד גאל הקב\"ה\" נאר אלע אידן און יעדער איד, ביז אפילו אזא וואס „בשם ישראל (איז נאר) יכונה\" —\nאיז ר\"ת „יש ששים ריבוא אותיות",[["7","7","אבות פ\"ו סוף מ\"ג."],["8","8","אבות פ\"א מי\"ז."],["9","9","כלשון כ\"ק מו\"ח אדמו\"ר במכתבו הנ\"ל."],["10","10","סנהדרין מד, רע\"א."],["11","11","נדפס בסה\"מ תרפ\"ח ע' קמו ואילך. תש\"ח ע' 263 ואילך."]]],[1300201432,"לתורה\"¹², דערפאר וואס יעדער איד, וואס עס זיינען דא ששים ריבוא אידן, האט אן אות אין תורה¹³, כמבואר ומפורסם.\nוהגם אז עס זיינען דא מערער ווי ששים ריבוא אידן (מערער אידן ווי אותיות אין תורה) — איז אבער מבואר אין תניא¹⁴ אז אט די ששים ריבוא זיינען נשמות כלליות און שרשים, „וכל שרש מתחלק לששים ריבוא ניצוצות שכל ניצוץ הוא נשמה אחת כו'\",\nוואס דערפאר, בשעת דער אוי־בערשטער בענטשט אידן, און ס'איז דא א מספר רב יותר ווי ששים ריבוא בפשטות — איז יעדערער פון זיי נכלל אין די ששים ריבוא מישראל, ובמילא אין די ששים ריבוא אותיות לתורה, יעדערער פון די אידן האט אן אות אין דער תורה.\nדאס הייסט, אז אין תורה ווערן נכלל און נתאחד אלע אידן, ביז אז זיי ווערן איין זאך ממש,\nווארום וויבאלד אז יעדערער פון די ששים ריבוא אידן האט אן אות אין תורה וואס אין איר איז דא ששים ריבוא אותיות — איז אזוי ווי די תורה איז אן איין־און־איינציקע זאך, א תורה וואס האט אין זיך ששים ריבוא אותיות, אזוי אויך זיינען אידן אן איין־און־איינציקע זאך וואס האט אין זיך ששים ריבוא חלקים (כדלקמן).\nו. און דער ענין ווערט נתחדש יעדער מאל ווען עס ווערט געשריבן א נייע ספר תורה (ובנדו\"ד — די ספר תורה וואס מ'וועט מסיים זיין אין צוויי טעג ארום):\nבשעת עס ווערט געשריבן א נייע ספר תורה, איז ניט דער פירוש אז עס קומט צו א הוספה אין דעם מספר הספרי תורה'ס — נאר עס קומט צו אן עיקר — א ספר תורה: יעדע נייע ספר תורה איז „חדשים\" ממש (און א כ\"ף הדמיון), ווי די ערשטע ספר תורה וואס משה רבינו האט געשריבן,\nוואס די ספר תורה וואס משה רבינו האט געשריבן נעמט זיך פון (און איז ע\"ד ווי) די עשרת הדברות וואס זיינען געגעבן געווארן בפעם הראשונה בא מ\"ת, ווארום אין די עשה\"ד איז געווען כלול די גאנצע ספר תורה בשלימותה (כולל אויך תושבע\"פ), „מזה ומזה הם כתובים\"¹⁵,\nאון דערנאך איז „ויכתוב משה את התורה הזאת\"¹⁶, ער האט געשריבן י\"ג ספרי תורה — איין ספר תורה פאר",[["12","12","„ואף שבתורה אין נמצא ס\"ר אותיות\", היינו מפני אותיות המשך שהם אותיות אהו\"י שבכלל הנקודות שאינן בכתב אבל ישנן במחשבה, שהקמץ הוא א' והחיריק י' כו' (וכדפרש\"י ס\"פ ז' דכתובות גבי ינחם כתיב כאילו כתיב ינאחם), אך איזו מהנקודות הם אינו ידוע כו' — <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380253\" data-slug=\"likkutei-torah\" data-id=\"4001380253\">לקו\"ת בהר מא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380263\" data-slug=\"likkutei-torah\" data-id=\"4001380263\">שם מג, ד</a>, עיי\"ש. עוד בזה — ראה ניצוצי זהר לזהר חדש עד, ד (במילואים — קכו, ב)."],["13","13","מגלה עמוקות אופן קפו."],["14","14","פל\"ז (מח, א). *) כ\"א ערך ל\"ו ריבוא אותיות — המשך וככה תרל\"ז פפ\"ט. ובסה\"מ קונטרסים ח\"א קצא, ב: שמספר אותיות הכתובים בתורה הם בערך ש\"ה אלפים כו'. וכ\"ה במאמר הנפש (לרמ\"ע מפאנו) ח\"ג פ\"ה, שאין בתורה רק בערך ל' וחצי ריבוא אותיות. וראה בנצו\"ז דלקמן בפנים הערה, שהביא מכמה ספרים שמספר האותיות בתורה בדיוק הוא: 304,805."],["15","15","תשא לב, טו. וראה ירושלמי שקלים פ\"ו ה\"א."],["16","16","וילך לא, ט."]]],[1300201433,"יעדער שבט באזונדער, און איין ספר תורה וואס מ'האט אריינגעגעבן אין משכן (און לאח\"ז — אין ביהמ\"ק) אין דעם ארון הקודש (צוזאמען מיט די לוחות)¹⁷,\nאון די ספר תורה איז מאחד¹⁸ די אנדערע צוועלף ספרי תורה, אז עס ווערט פון זיי איין ענין.\nאון דערנאך בשעת א יחיד (אפילו) איז מקיים די מ\"ע מן התורה פון כתיבת ספר תורה¹⁹, די מ\"ע פון „וכתב לו\"²⁰ — ווערט נתחדש מיט דער גאנצער שלימות דער ענין וואס איז געווען אין דער ערשטער ספר תורה וואס איז גע־שריבן געווארן דורך משה רבינו.\nאון במילא אויך דער ענין וואס יש ששים ריבוא אותיות לתורה, און אז דאס איז כולל אין זיך אלע אידן — איז אויך דא אין א ניי־געשריבענע ספר תורה, פונקט אזוי ווי אין דער תורה וואס איז געגעבן געווארן בא מתן תורה.\n[ובפרט נאך אז בנדו\"ד קומט־פאר דער סיום והכנסת הספר תורה אין א שנת הקהל, וואס (כדלקמן) הקהל איז דאך פארבונדן מיט מתן תורה מחדש, ווי דער רמב\"ם²¹ שרייבט אז בשעת מ'לייענט די פרשיות בתורה אין דעם זמן פון הקהל — איז דאס „כיום שניתנה בו בסיני . . כאילו מפי הגבורה שומעה\"].\nז. נאכמער:\nדער אויבערשטער האט אנגעזאגט „עם קרובו\"²² אז אין עניני קדושה דארף זיין „מעלין בקודש\"²³.\nאון וויבאלד אז „מגיד דבריו ליעקב חוקיו ומשפטיו לישראל\"²⁴ — איז דער אויבערשטער, כביכול, מקיים דאס וואס ער האט אנגעזאגט אידן, אז אין עניני קדושה זאל זיין „מעלין בקודש\".\nוע\"ד ווי דער אלטער רבי איז מבאר אין אגה\"ק²⁵ בנוגע צו ראש השנה, אז בכל שנה ושנה ווערט נמשך (בר\"ה) אן „אור חדש עליון יותר שלא הי' מאיר עדיין מימי עולם אור עליון כזה\".\nועד\"ז איז פארשטאנדיק בנוגע צו אן ענין פון ספר תורה, אז דער אוי־בערשטער איז זיכער מקיים וואס ער האט אנגעזאגט אידן — אז בשעת מ'איז",[["17","17","דב\"ר פ\"ט, ט. מדרש תהלים עה\"פ צ, א. הקדמת הרמב\"ם לספר היד."],["18","18","להעיר שממנה מגיהין כל הס\"ת (פסדר\"כ פיסקא וזאת הברכה. ילק\"ש ברכה רמז תתקנ)."],["19","19","סנהדרין כא, ב. רמב\"ם הל' ס\"ת פ\"ז ה\"א. טושו\"ע יו\"ד סר\"ע ס\"א. ואף שהדרמ\"א והש\"ך כתבו שדעת הרא\"ש שעתה אין מצוה בזה (ומה שהקשו על הדרמ\"א כבר מתורץ, ע\"פ מ\"ש בבאר הגולה ובנימוקי ריב\"ז שם), וגם השאגת ארי' סל\"ו ס\"ל שאין עתה מצוה בכתיבת ס\"ת — אבל המחבר, עט\"ז, מ\"מ ריש הל' ס\"ת, ס\"ז, ש\"ך, מנחת חינוך בסופו, פסקו שתמיד ישנה מ\"ע של כתיבת ספר תורה. וראה ג\"כ שו\"ת חת\"ס חלק או\"ח סנ\"ב, חלק יו\"ד סרנ\"ד. שו\"ת מנחת אלעזר ח\"ג סכ\"ח. וראה בארוכה לקו\"ש חכ\"ג חגה\"ש (תשמ\"א). חכ\"ד פ' וילך (תשמ\"ב)."],["20","20","כה\"ל לשון כ\"ק מו\"ח אדמו\"ר במכתבו הנ\"ל („קיום מ\"ע של וכתב לו\"). וצ\"ע, דהא מצות כתיבת ס\"ת ילפינן (סנהדרין שם. רמב\"ם שם) מ„ועתה כתבו לכם את השירה הזאת\" (וילך לא, יט), ומהפסוק (שופטים יז, יח) „וכתב לו\" ילפינן (סנהדרין שם. רמב\"ם שם ה\"ב) מצות כתיבת ס\"ת שעל המלך לכתוב. אבל להעיר מהכלל (דהרמב\"ם) להביא הדרשא (והפסוק, אע\"פ שלא נזכר בגמרא כלל) היותר פשוט ומבואר (יד מלאכי כללי הרמב\"ם ד וש\"נ). והרמב\"ם כאן מוכרח להביא „ועתה כתבו\", כיון ש„וכתב לו\" מביא חומ\"י בנוגע למלך."],["21","21","הל' חגיגה פ\"ג ה\"ו."],["22","22","תהלים קמח, יד."],["23","23","ברכות כח, א. וש\"נ."],["24","24","תהלים קמז, יט. שמו\"ר פ\"ל, ט."],["25","25","סוף סי\"ד."]]],[1300201434,"מסיים און מ'טראגט אריין אין בית הכנסת א נייע ספר תורה (ווי מ'וועט טאן אין צוויי טעג ארום), ווערט דעמולט נמשך אן ענין חדש וואס איז נאך קיינמאל ניט געווען.\nוואס מצד דערויף איז דא א מעלה אין דער ספר תורה (און אין דעם וואס דאס איז כולל אין זיך אלע ששים ריבוא אידן (ופרטיהם)) וואס מ'וועט מסיים זיין אין צוויי טעג ארום, לגבי אלע ספרי תורה וואס זיינען פריער געווען, ביז אפילו כביכול לגבי דער ספר תורה וואס משה רבינו האט געשריבן.\nח. וואס ע\"פ כל הנ\"ל, איז בשעת מ'איז מפרסם עטליכע טעג פריער וועגן דעם סיום והכנסת ספר תורה וואס וועט זיין אין צוויי טעג ארום — איז דורך דערויף וואס אידן הערן (בכל האופנים, כולל דורך די מכשירים הנ\"ל) דערוועקט דאס אין זיי דעם אות וואס יעדערער פון זיי האט אין (תורה בכלל, און אין) אט דער ספר תורה,\nאון דאס פועל'ט א התאחדות צווישן אלע אידן, ווארום ווי אלע ששים ריבוא שטייען אין (די ששים ריבוא אותיות ל)תורה ווערן זיי אלע נתאחד, כנ\"ל.\nפונקט ווי דאס איז אין א ספר תורה עצמה:\nאמיתית און שלימות פון א ספר תורה באשטייט ניט ווי זי איז כל אות בנפרד בפני עצמה, אדער כל יריעה בפני עצמה, אדער כל ספר בפני עצמו, אדער עטליכע ספרים בפני עצמם — נאר ווי זי איז אן איין־און־איינציקע ספר תורה,\nווי ער זאגט אין זהר²⁶ (וואס מ'זאגט אין „מענה לשון\" (בשעת מ'איז מבקר אויפן בית החיים פון צדיקים, וואס זיי זיינען „דומין לבוראן\"²⁷ און חיים בחיים נצחיים), ווי גערעדט אין דער פריער־דיקער התוועדות²⁸), אז כדי א ספר תורה זאל זיין בשלימות תוקפה וקדושתה — דארף אין איר זיין יעדער אות בשלימותה ובמקומה (א „מוקפת גויל\"²⁹, און מיט אלע פרטים המבוארים בזה, כמבואר אין לקו\"ת³⁰ אין די ענינים), און אויב אפילו איין אות איז ניט בשלימות (אדער עס איז דא אן איבעריקער אות) רירט עס אן אין דער שלימות פון דער גאנצער ספר תורה.\nואין ענין יוצא מידי פשוטו:\nאע\"פ אז א ספר תורה דארף בא־שטיין פון ששים ריבוא אותיות (און דערצו „תגין\"³¹ וכיו\"ב), און זי דארף זיין געשריבן אויף א קלף לבן — איז אבער ח\"ו צו זאגן אז זי איז נפרד אין חלקים, ווארום דעמולט פעלט אין איר שלימות — נאר זי איז בהדגשה אן איין־און־איינציקע זאך.\nאון דער ענין האחדות אין תורה איז מודגש (במיוחד) אין דעם ענין הקלף והלבן וואס איז דא אין א ספר תורה, ווארום דאס באווייזט אויפן אור מקיף³², וואס אור מקיף באווייזט אויף פשיטות העליונה פון דעם וואס ער איז בתכלית הפשיטות — עצמות ומהות אליין, וועל־כער זאגט³³ „אנא נפשי כתבית יהבית\",",[["26","26","ח\"ג עא, א."],["27","27","ב\"ר פס\"ז, ח."],["28","28","שיחת ש\"פ וישלח, י\"ד כסלו."],["29","29","מנחות כט, א. רמב\"ם הל' תפילין פ\"א הי\"ט. טושו\"ע יו\"ד סרע\"ד ס\"ד. או\"ח סל\"ב ס\"ד. שו\"ע אדה\"ז או\"ח שם ס\"ה."],["30","30","בחוקותי מה, ד ואילך. שה\"ש ה, א. מה, ג. מו, ג ואילך."],["31","31","טושו\"ע יו\"ד שם ס\"ז. רמ\"א או\"ח שם. שו\"ע אדה\"ז שם."],["32","32","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381149\" data-slug=\"likkutei-torah\" data-id=\"4001381149\">לקו\"ת שה\"ש ה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381314\" data-slug=\"likkutei-torah\" data-id=\"4001381314\">מו, ג</a> ואילך. ובכ\"מ."],["33","33","שבת קה, א (ע\"פ גירסת העי\")."]]]]});
